typedef struct MBJSMallocState {
    size_t malloc_count;
    size_t malloc_size;
    size_t malloc_limit;
    void *opaque; /* user opaque */
} MBJSMallocState;

/* Small-block "arena" allocator.
   mbjs_{malloc,free,realloc,calloc}_rt serve allocations up to ~512
   bytes from size-classed 4KB arenas carved out of the underlying
   MBJSMallocFunctions allocator, so the backing allocator (system malloc,
   mimalloc, ...) sees roughly one request per arena refill instead of one per
   object. */

#define MBJS_ARENA_ALIGN             8
#define MBJS_ARENA_SIZE              4096
#define MBJS_ARENA_BLOCK_SIZE_COUNT  31
#define MBJS_ARENA_MAX_SMALL_SIZE    512
#define MBJS_ARENA_FREE_NIL          0xffff

#if defined(__SANITIZE_ADDRESS__) || defined(FORCE_GC_AT_MALLOC)
/* Route every allocation through the backing malloc so each block is seen
   individually: ASan can then poison a freed block, and a GC-stress build
   (FORCE_GC_AT_MALLOC) exposes prematurely-freed objects instead of the pool
   silently recycling them. */
#define MBJS_ARENA_LARGE_BLOCKS_ONLY 1
#else
#define MBJS_ARENA_LARGE_BLOCKS_ONLY 0
#endif

/* 8-byte header preceding every user allocation. It carries the allocator
   bookkeeping (block_idx/free_next + block_size_idx) and, the
   GC/refcount fields (gc_obj_type/mark/ref_count) that would otherwise sit in
   the object body. The 8-byte size keeps user_data MBJS_ARENA_ALIGN-aligned. */
typedef struct MBJSMallocBlockHeader {
    union {
        uint16_t block_idx;   /* MBJS_ARENA_FREE_NIL => large or zero-size block */
        uint16_t free_next;   /* next free block index while on a free list */
    } u;
    uint8_t  block_size_idx;
    /* GC/refcount header merged into the allocator header:
       the object body keeps only MBJSGCObjectHeader.link (no ref_count/flags). */
    uint8_t  gc_obj_type : 7; /* MBJSGCObjectTypeEnum for GC objects */
    uint8_t  mark : 1;        /* used by the cycle collector */
    int      ref_count;
    _Alignas(MBJS_ARENA_ALIGN) uint8_t user_data[];
} MBJSMallocBlockHeader;

typedef struct MBJSArena {
    struct list_head free_link;   /* in free_arena_list[idx] while not full */
    struct list_head link;        /* in arena_list[idx] for the whole lifetime */
    uint8_t  block_size_idx;
    uint16_t n_used_blocks;
    uint16_t n_blocks;
    uint16_t first_free_block;    /* MBJS_ARENA_FREE_NIL if none */
    _Alignas(MBJS_ARENA_ALIGN) uint8_t blocks[];
} MBJSArena;

typedef struct MBJSArenaState {
    struct list_head arena_list[MBJS_ARENA_BLOCK_SIZE_COUNT];
    struct list_head free_arena_list[MBJS_ARENA_BLOCK_SIZE_COUNT];
    _Alignas(MBJS_ARENA_ALIGN) uint8_t zero_size_block[sizeof(MBJSMallocBlockHeader)];
} MBJSArenaState;

typedef struct MBJSRuntimeFinalizerState {
    struct MBJSRuntimeFinalizerState *next;
    MBJSRuntimeFinalizer *finalizer;
    void *arg;
} MBJSRuntimeFinalizerState;

typedef struct MBJSValueLink {
    struct MBJSValueLink *next;
    MBJSValueConst value;
} MBJSValueLink;

typedef struct MBJSClass {
    uint32_t class_id; /* 0 means free entry */
    MBJSAtom class_name;
    MBJSClassFinalizer *finalizer;
    MBJSClassGCMark *gc_mark;
    MBJSClassCall *call;
    /* pointers for exotic behavior, can be NULL if none are present */
    const MBJSClassExoticMethods *exotic;
} MBJSClass;

struct MBJSRuntime {
    MBJSMallocFunctions mf;
    MBJSMallocState malloc_state;
    MBJSArenaState arena_state;
    const char *rt_info;

    int atom_hash_size; /* power of two */
    int atom_count;
    int atom_size;
    int atom_count_resize; /* resize hash table at this count */
    uint32_t *atom_hash;
    MBJSAtomStruct **atom_array;
    int atom_free_index; /* 0 = none */

    MBJSClassID mbjs_class_id_alloc; /* counter for user defined classes */
    int class_count;    /* size of class_array */
    MBJSClass *class_array;

    struct list_head context_list; /* list of MBJSContext.link */
    /* list of MBJSGCObjectHeader.link. List of allocated GC objects (used
       by the garbage collector) */
    struct list_head gc_obj_list;
    /* list of MBJSGCObjectHeader.link. Used during MBJS_FreeValueRT() */
    struct list_head gc_zero_ref_count_list;
    struct list_head tmp_obj_list; /* used during GC */
    MBJSGCPhaseEnum gc_phase : 8;
    size_t malloc_gc_threshold;
#ifdef MBJS_SUNAT_GC
    MBJSMemArena *sunat_arena; /* arena backing this runtime (owned by rt) */
#endif
#ifdef ENABLE_DUMPS // MBJS_DUMP_LEAKS
    struct list_head string_list; /* list of MBJSString.link */
#endif
    /* stack limitation */
    uintptr_t stack_size; /* in bytes, 0 if no limit */
    uintptr_t stack_top;
    uintptr_t stack_limit; /* lower stack limit */

    MBJSValue current_exception;
    /* true if inside an out of memory error, to avoid recursing */
    bool in_out_of_memory;
    /* true if inside build_backtrace, to avoid recursing */
    bool in_build_stack_trace;
    /* true if inside MBJS_FreeRuntime */
    bool in_free;

    struct MBJSStackFrame *current_stack_frame;

    MBJSInterruptHandler *interrupt_handler;
    void *interrupt_opaque;

    /* Superset selector for the MochiBerry engine/compiler (Takegawa TGPM).
     * NULL means "default engine" (no superset). */
    char *superset;

    MBJSPromiseHook *promise_hook;
    void *promise_hook_opaque;
    // for smuggling the parent promise from mbjs_promise_then
    // to mbjs_promise_constructor
    MBJSValueLink *parent_promise;

    MBJSHostPromiseRejectionTracker *host_promise_rejection_tracker;
    void *host_promise_rejection_tracker_opaque;

    struct list_head job_list; /* list of MBJSJobEntry.link */

    bool module_normalize_has_attr;
    union {
        MBJSModuleNormalizeFunc *module_normalize_func;
        MBJSModuleNormalizeFunc2 *module_normalize_func2;
    } normalize_u;
    bool module_loader_has_attr;
    union {
        MBJSModuleLoaderFunc *module_loader_func;
        MBJSModuleLoaderFunc2 *module_loader_func2;
    } u;
    MBJSModuleCheckSupportedImportAttributes *module_check_attrs;
    void *module_loader_opaque;
    MBJSDynamicImportFunc *dynamic_import;
    void *dynamic_import_opaque;
    /* timestamp for internal use in module evaluation */
    int64_t module_async_evaluation_next_timestamp;

    /* used to allocate, free and clone SharedArrayBuffers */
    MBJSSharedArrayBufferFunctions sab_funcs;

    bool can_block; /* true if Atomics.wait can block */
    uint32_t dump_flags : 24;

    /* Shape hash table */
    int shape_hash_bits;
    int shape_hash_size;
    int shape_hash_count; /* number of hashed shapes */
    MBJSShape **shape_hash;
    void *user_opaque;
    void *libc_opaque;
    MBJSRuntimeFinalizerState *finalizers;
};

typedef struct MBJSStackFrame {
    struct MBJSStackFrame *prev_frame; /* NULL if first stack frame */
    MBJSValue cur_func; /* current function, MBJS_UNDEFINED if the frame is detached */
    MBJSValue *arg_buf; /* arguments */
    MBJSValue *var_buf; /* variables */
    struct MBJSVarRef **var_refs; /* references to arguments or local variables */
    uint8_t *cur_pc; /* only used in bytecode functions : PC of the
                        instruction after the call */
    uint16_t var_ref_count; /* number of var refs */
    uint16_t arg_count;
    bool is_strict_mode;
    bool is_constructor; /* true if invoked as a constructor (new) */
    /* only used in generators. Current stack pointer value. NULL if
       the function is running. */
    MBJSValue *cur_sp;
    /* only set for coroutine frames (async function / generator /
       async generator): the GC object owning this heap-allocated frame,
       NULL for ordinary C-stack frames. Lets a var_ref capturing one of
       the coroutine's locals keep the (suspended) coroutine reachable by
       the cycle collector. */
    struct MBJSGCObjectHeader *cur_gc_obj;
} MBJSStackFrame;

typedef enum {
    MBJS_GC_OBJ_TYPE_JS_OBJECT,
    MBJS_GC_OBJ_TYPE_FUNCTION_BYTECODE,
    MBJS_GC_OBJ_TYPE_SHAPE,
    MBJS_GC_OBJ_TYPE_VAR_REF,
    MBJS_GC_OBJ_TYPE_ASYNC_FUNCTION,
    MBJS_GC_OBJ_TYPE_JS_CONTEXT,
} MBJSGCObjectTypeEnum;

/* header for GC objects. GC objects are C data structures with a
   reference count that can reference other GC objects. JS Objects are
   a particular type of GC object. */
struct MBJSGCObjectHeader {
    /* ref_count/gc_obj_type/mark live in the allocator block header (mbjs_rc(p),
       the 8 bytes before every allocation); only the GC list link remains in
       the object body. */
    struct list_head link;
};

typedef struct MBJSVarRef {
    MBJSGCObjectHeader header; /* {link}; must come first so &p->header == p */
    uint8_t is_detached;
    uint8_t is_lexical; /* only used with global variables */
    uint8_t is_const; /* only used with global variables */
    /* Set at creation for an open var_ref that captures a local of a
       coroutine (async function / generator / async generator): such a
       var_ref holds a counted reference to that coroutine's GC object and
       is itself a GC object, so the cycle collector can see the closure ->
       var_ref -> coroutine edge and keep the suspended coroutine (hence the
       captured variable it points into) alive. The coroutine is recovered
       as stack_frame->cur_gc_obj (valid while open). This is a *snapshot* of
       cur_gc_obj != NULL taken at creation, NOT rederived at read time:
       cur_gc_obj transitions NULL -> owner (it is set only after a
       generator's initial resume), so var_refs created during the prologue
       (e.g. mapped `arguments`) must stay non-coro even though cur_gc_obj is
       later set. Cleared when the var_ref is detached; the ref is released on
       detach/free. */
    uint8_t is_coro;
    MBJSValue *pvalue; /* pointer to the value, either on the stack or
                        to 'value' */
    union {
        MBJSValue value; /* used when is_detached = true */
        struct {
            uint16_t var_ref_idx; /* index in MBJSStackFrame.var_refs[] */
            MBJSStackFrame *stack_frame;
        }; /* used when is_detached = false */
    };
} MBJSVarRef;

/* Accessors for the reference count and GC mark/type. These fields live in the
   arena block header (the 8 bytes before every allocation, reached via
   mbjs_rc()), not in the object body. The macros yield lvalues, and the argument
   is always the object/header pointer (whose address equals the GC header's,
   since the header is the first member). */
static inline MBJSMallocBlockHeader *mbjs_rc(const void *p) {
    return (MBJSMallocBlockHeader *)((uint8_t *)(uintptr_t)p - offsetof(MBJSMallocBlockHeader, user_data));
}
#define MBJS_REF_COUNT(p) (mbjs_rc(p)->ref_count)
#define MBJS_GC_TYPE(p)   (mbjs_rc(p)->gc_obj_type)
#define MBJS_GC_MARK(p)   (mbjs_rc(p)->mark)

/* bigint */
typedef int32_t mbjs_slimb_t;
typedef uint32_t mbjs_limb_t;
typedef int64_t mbjs_sdlimb_t;
typedef uint64_t mbjs_dlimb_t;

#define MBJS_LIMB_DIGITS 9

/* Must match the size of short_big_int in MBJSValueUnion */
#define MBJS_LIMB_BITS 32
#define MBJS_SHORT_BIG_INT_BITS MBJS_LIMB_BITS
#define MBJS_BIGINT_MAX_SIZE ((1024 * 1024) / MBJS_LIMB_BITS) /* in limbs */
#define MBJS_SHORT_BIG_INT_MIN INT32_MIN
#define MBJS_SHORT_BIG_INT_MAX INT32_MAX


typedef struct MBJSBigInt {
    uint32_t len; /* number of limbs, >= 1 */
    mbjs_limb_t tab[]; /* two's complement representation, always
                        normalized so that 'len' is the minimum
                        possible length >= 1 */
} MBJSBigInt;

/* this bigint structure can hold a 64 bit integer */
typedef struct {
    mbjs_limb_t big_int_buf[sizeof(MBJSBigInt) / sizeof(mbjs_limb_t)]; /* for MBJSBigInt */
    /* must come just after */
    mbjs_limb_t tab[(64 + MBJS_LIMB_BITS - 1) / MBJS_LIMB_BITS];
} MBJSBigIntBuf;

typedef enum {
    MBJS_AUTOINIT_ID_PROTOTYPE,
    MBJS_AUTOINIT_ID_MODULE_NS,
    MBJS_AUTOINIT_ID_PROP,
    MBJS_AUTOINIT_ID_BYTECODE,
} MBJSAutoInitIDEnum;

enum {
    MBJS_BUILTIN_ARRAY_FROMASYNC = 1,
    MBJS_BUILTIN_ITERATOR_ZIP,
    MBJS_BUILTIN_ITERATOR_ZIP_KEYED,
};

/* must be large enough to have a negligible runtime cost and small
   enough to call the interrupt callback often. */
#define MBJS_INTERRUPT_COUNTER_INIT 10000

struct MBJSContext {
    MBJSGCObjectHeader header; /* must come first */
    MBJSRuntime *rt;
    struct list_head link;

    uint16_t binary_object_count;
    uint32_t binary_object_size : 31;

    /* true if the array prototype is "normal":
       - no small index properties which are get/set or non writable
       - its prototype is Object.prototype
       - Object.prototype has no small index properties which are get/set or non writable
       - the prototype of Object.prototype is null (always true as it is immutable)
    */
    uint8_t std_array_prototype : 1;

    MBJSShape *array_shape;   /* initial shape for Array objects */
    MBJSShape *arguments_shape;  /* shape for arguments objects */
    MBJSShape *mapped_arguments_shape;  /* shape for mapped arguments objects */
    MBJSShape *regexp_shape;  /* shape for regexp objects */
    MBJSShape *regexp_result_shape;  /* shape for regexp result objects */

    MBJSValue *class_proto;
    MBJSValue function_proto;
    MBJSValue function_ctor;
    MBJSValue array_ctor;
    MBJSValue regexp_ctor;
    MBJSValue promise_ctor;
    MBJSValue native_error_proto[MBJS_NATIVE_ERROR_COUNT];
    MBJSValue error_ctor;
    MBJSValue error_back_trace;
    MBJSValue error_prepare_stack;
    MBJSValue error_stack_trace_limit;
    MBJSValue iterator_ctor;
    MBJSValue iterator_ctor_getset;
    MBJSValue iterator_proto;
    MBJSValue async_iterator_proto;
    MBJSValue array_proto_values;
    MBJSValue throw_type_error;
    MBJSValue eval_obj;

    MBJSValue global_obj; /* global object */
    MBJSValue global_var_obj; /* contains the global let/const definitions */

    double time_origin;

    uint64_t random_state;
    uint32_t hash_seed;

    /* when the counter reaches zero, MBJSRutime.interrupt_handler is called */
    int interrupt_counter;

    struct list_head loaded_modules; /* list of MBJSModuleDef.link */

    /* if NULL, RegExp compilation is not supported */
    MBJSValue (*compile_regexp)(MBJSContext *ctx, MBJSValueConst pattern,
                              MBJSValueConst flags);
    /* if NULL, eval is not supported */
    MBJSValue (*eval_internal)(MBJSContext *ctx, MBJSValueConst this_obj,
                             const char *input, size_t input_len,
                             const char *filename, int line, int flags, int scope_idx);
    void *user_opaque;
};

