typedef enum {
    MBJS_STRING_KIND_NORMAL,
    MBJS_STRING_KIND_SLICE,
    MBJS_STRING_KIND_INDIRECT,
} MBJSStringKind;

#define MBJS_ATOM_HASH_MASK  ((1 << 28) - 1)

struct MBJSString {
    uint32_t len : 31;
    uint32_t is_wide_char : 1; /* 0 = 8 bits, 1 = 16 bits characters */
    /* for MBJS_ATOM_TYPE_SYMBOL: hash = 0, atom_type = 3,
       for MBJS_ATOM_TYPE_PRIVATE: hash = 1, atom_type = 3
       XXX: could change encoding to have one more bit in hash */
    uint32_t hash : 28;
    uint32_t kind : 2;
    uint32_t atom_type : 2; /* != 0 if atom, MBJS_ATOM_TYPE_x */
    uint32_t hash_next; /* atom_index for MBJS_ATOM_TYPE_SYMBOL */
    MBJSWeakRefRecord *first_weak_ref;
#ifdef ENABLE_DUMPS // MBJS_DUMP_LEAKS
    struct list_head link; /* string list */
#endif
};

typedef struct MBJSStringSlice {
    MBJSString *parent;
    uint32_t start; // in bytes, not characters
} MBJSStringSlice;

struct MBJSStringRope {
    uint32_t len;
    uint8_t is_wide_char; /* 0 = 8 bits, 1 = 16 bits characters */
    uint8_t depth;        /* max depth of the rope tree */
    MBJSValue left;
    MBJSValue right;        /* might be the empty string */
};

static inline void *strv(MBJSString *p)
{
    MBJSStringSlice *slice;
    void **indirect;

    switch (p->kind) {
    case MBJS_STRING_KIND_NORMAL:
        return (void *)&p[1];
    case MBJS_STRING_KIND_SLICE:
        slice = (void *)&p[1];
        return (char *)&slice->parent[1] + slice->start;
    case MBJS_STRING_KIND_INDIRECT:
        indirect = (void *)&p[1];
        return *indirect;
    }
    abort();
    return NULL;
}

static inline uint8_t *str8(MBJSString *p)
{
    return strv(p);
}

static inline uint16_t *str16(MBJSString *p)
{
    return strv(p);
}

typedef enum {
    MBJS_CLOSURE_LOCAL, /* 'var_idx' is the index of a local variable in the parent function */
    MBJS_CLOSURE_ARG, /* 'var_idx' is the index of an argument variable in the parent function */
    MBJS_CLOSURE_REF, /* 'var_idx' is the index of a closure variable in the parent function */
    MBJS_CLOSURE_GLOBAL_REF, /* 'var_idx' is the index of a closure variable in the parent
                              function referencing a global variable */
    MBJS_CLOSURE_GLOBAL_DECL, /* global variable declaration (eval code only) */
    MBJS_CLOSURE_GLOBAL, /* global variable (eval code only) */
    MBJS_CLOSURE_MODULE_DECL, /* definition of a module variable (eval code only) */
    MBJS_CLOSURE_MODULE_IMPORT, /* definition of a module import (eval code only) */
} MBJSClosureTypeEnum;

typedef struct MBJSClosureVar {
    uint8_t closure_type : 3; /* see MBJSClosureTypeEnum */
    uint8_t is_lexical : 1; /* lexical variable */
    uint8_t is_const : 1; /* const variable (is_lexical = 1 if is_const = 1) */
    uint8_t var_kind : 4; /* see MBJSVarKindEnum */
    /* 7 bits available */
    uint16_t var_idx; /* MBJS_CLOSURE_LOCAL/MBJS_CLOSURE_ARG: index to a normal variable of the
                    parent function. otherwise: index to a closure
                    variable of the parent function */
    MBJSAtom var_name;
} MBJSClosureVar;

#define ARG_SCOPE_INDEX 1
#define ARG_SCOPE_END (-2)

typedef struct MBJSVarScope {
    int parent;  /* index into fd->scopes of the enclosing scope */
    int first;   /* index into fd->vars of the last variable in this scope */
    uint8_t has_using : 1; /* scope has using declarations */
    uint8_t is_await_using : 1; /* scope has await using declarations */
    int using_label_catch; /* label for catch handler (-1 if none) */
    int using_label_end;   /* label for end of disposal block (-1 if none) */
} MBJSVarScope;

typedef enum {
    /* XXX: add more variable kinds here instead of using bit fields */
    MBJS_VAR_NORMAL,
    MBJS_VAR_FUNCTION_DECL, /* lexical var with function declaration */
    MBJS_VAR_NEW_FUNCTION_DECL, /* lexical var with async/generator
                                 function declaration */
    MBJS_VAR_CATCH,
    MBJS_VAR_FUNCTION_NAME, /* function expression name */
    MBJS_VAR_PRIVATE_FIELD,
    MBJS_VAR_PRIVATE_METHOD,
    MBJS_VAR_PRIVATE_GETTER,
    MBJS_VAR_PRIVATE_SETTER, /* must come after MBJS_VAR_PRIVATE_GETTER */
    MBJS_VAR_PRIVATE_GETTER_SETTER, /* must come after MBJS_VAR_PRIVATE_SETTER */
    MBJS_VAR_USING, /* using declaration variable */
    MBJS_VAR_USING_METHOD, /* hidden local holding the cached dispose method
                            for the preceding MBJS_VAR_USING var (always
                            allocated immediately after it). */
} MBJSVarKindEnum;

/* XXX: could use a different structure in bytecode functions to save
   memory */
typedef struct MBJSVarDef {
    MBJSAtom var_name;
    /* index into fd->scopes of this variable lexical scope */
    int scope_level;
    /* during compilation:
        - if scope_level = 0: scope in which the variable is defined
        - if scope_level != 0: index into fd->vars of the next
          variable in the same or enclosing lexical scope
       in a bytecode function:
       index into fd->vars of the next
       variable in the same or enclosing lexical scope
    */
    int scope_next;
    uint8_t is_const : 1;
    uint8_t is_lexical : 1;
    uint8_t is_captured : 1;
    uint8_t is_static_private : 1; /* only used during private class field parsing */
    uint8_t var_kind : 4; /* see MBJSVarKindEnum */
    /* if is_captured = true, provides the index of the corresponding
       MBJSVarRef on stack */
    uint16_t var_ref_idx;
    /* only used during compilation: function pool index for lexical
       variables with var_kind =
       MBJS_VAR_FUNCTION_DECL/MBJS_VAR_NEW_FUNCTION_DECL or scope level of
       the definition of the 'var' variables (they have scope_level =
       0) */
    int func_pool_idx; /* only used during compilation : index in
                          the constant pool for hoisted function
                          definition */
} MBJSVarDef;

/* for the encoding of the pc2line table */
#define PC2LINE_BASE     (-1)
#define PC2LINE_RANGE    5
#define PC2LINE_OP_FIRST 1
#define PC2LINE_DIFF_PC_MAX ((255 - PC2LINE_OP_FIRST) / PC2LINE_RANGE)

typedef enum MBJSFunctionKindEnum {
    MBJS_FUNC_NORMAL = 0,
    MBJS_FUNC_GENERATOR = (1 << 0),
    MBJS_FUNC_ASYNC = (1 << 1),
    MBJS_FUNC_ASYNC_GENERATOR = (MBJS_FUNC_GENERATOR | MBJS_FUNC_ASYNC),
} MBJSFunctionKindEnum;

typedef struct MBJSFunctionBytecode {
    MBJSGCObjectHeader header; /* must come first */
    uint8_t is_strict_mode : 1;
    uint8_t has_prototype : 1; /* true if a prototype field is necessary */
    uint8_t has_simple_parameter_list : 1;
    uint8_t is_derived_class_constructor : 1;
    /* true if home_object needs to be initialized */
    uint8_t need_home_object : 1;
    uint8_t func_kind : 2;
    uint8_t new_target_allowed : 1;
    uint8_t super_call_allowed : 1;
    uint8_t super_allowed : 1;
    uint8_t arguments_allowed : 1;
    uint8_t backtrace_barrier : 1; /* stop backtrace on this function */
    /* XXX: 5 bits available */
    uint8_t *byte_code_buf; /* (self pointer) */
    int byte_code_len;
    MBJSAtom func_name;
    MBJSVarDef *vardefs; /* arguments + local variables (arg_count + var_count) (self pointer) */
    MBJSClosureVar *closure_var; /* list of variables in the closure (self pointer) */
    uint16_t arg_count;
    uint16_t var_count;
    uint16_t defined_arg_count; /* for length function property */
    uint16_t stack_size; /* maximum stack size */
    uint16_t var_ref_count; /* number of local variable references */
    uint16_t closure_var_count;
    int cpool_count;
    MBJSContext *realm; /* function realm */
    MBJSValue *cpool; /* constant pool (self pointer) */
    MBJSAtom filename;
    int line_num;
    int col_num;
    int source_len;
    int pc2line_len;
    uint8_t *pc2line_buf;
    char *source;
} MBJSFunctionBytecode;

