int MBJS_AddRuntimeFinalizer(MBJSRuntime *rt, MBJSRuntimeFinalizer *finalizer,
                           void *arg)
{
    MBJSRuntimeFinalizerState *fs = mbjs_malloc_rt(rt, sizeof(*fs));
    if (!fs)
        return -1;
    fs->next       = rt->finalizers;
    fs->finalizer  = finalizer;
    fs->arg        = arg;
    rt->finalizers = fs;
    return 0;
}

static void *mbjs_def_calloc(void *opaque, size_t count, size_t size)
{
    return calloc(count, size);
}

static void *mbjs_def_malloc(void *opaque, size_t size)
{
    return malloc(size);
}

static void mbjs_def_free(void *opaque, void *ptr)
{
    free(ptr);
}

static void *mbjs_def_realloc(void *opaque, void *ptr, size_t size)
{
    return realloc(ptr, size);
}

static const MBJSMallocFunctions def_malloc_funcs = {
    mbjs_def_calloc,
    mbjs_def_malloc,
    mbjs_def_free,
    mbjs_def_realloc,
    mbjs__malloc_usable_size
};

MBJSRuntime *MBJS_NewRuntime(void)
{
#ifdef MBJS_SUNAT_GC
    /* Sunat GC build: one deterministic arena backs every byte the runtime
       allocates. The arena is created here and destroyed in
       MBJS_FreeRuntime(); GC never runs (mbjs_trigger_gc/MBJS_RunGC are
       no-ops), so memory usage is a monotone bump that is fully reclaimed
       in bulk at teardown. */
    MBJSMemArena *arena = mbjs_def_calloc(NULL, 1, sizeof(MBJSMemArena));
    if (!arena)
        return NULL;
    mbjs_mem_arena_init(arena, 0);
    {
        MBJSRuntime *rt = MBJS_NewRuntime2(mbjs_mem_mf(), arena);
        if (!rt) {
            mbjs_mem_arena_destroy(arena);
            mbjs_def_free(NULL, arena);
            return NULL;
        }
        rt->sunat_arena = arena;
        return rt;
    }
#else
    return MBJS_NewRuntime2(&def_malloc_funcs, NULL);
#endif
}

#ifdef MBJS_SUNAT_GC
/* Sunat GC build only: stats of the deterministic backing arena and the
   circumcised GC. gc_runs is always 0. */
void MBJS_GetSunatStats(MBJSRuntime *rt, MBJSMemSunatStats *st)
{
    MBJSMemArena *arena = rt->sunat_arena;

    if (!arena && rt->malloc_state.opaque) {
        /* Embedder-created arena via
           MBJS_NewRuntime2(mbjs_mem_mf(), arena): resolve it from the
           allocator opaque, validated by the arena magic. */
        MBJSMemArena *a = (MBJSMemArena *)rt->malloc_state.opaque;
        if (a->magic == MBJS_MEM_ARENA_MAGIC)
            arena = a;
    }
    st->gc_runs = 0; /* the GC never runs in this build */
    if (arena) {
        st->arena_used = mbjs_mem_arena_used(arena);
        st->arena_peak = mbjs_mem_arena_peak(arena);
        st->arena_limit = arena->limit;
    } else {
        st->arena_used = 0;
        st->arena_peak = 0;
        st->arena_limit = 0;
    }
    st->engine_malloc_size = rt->malloc_state.malloc_size;
    st->engine_malloc_count = rt->malloc_state.malloc_count;
}

/* Sunat GC build only: the mbjs-mem arena backing the runtime, or NULL.
   For runtimes created through MBJS_NewRuntime() the runtime owns the
   arena and destroys it at MBJS_FreeRuntime(). For runtimes created
   through MBJS_NewRuntime2(mbjs_mem_mf(), arena) this returns the
   embedder-owned arena, which the embedder keeps and must destroy. */
void *MBJS_GetSunatArena(MBJSRuntime *rt)
{
    MBJSMemArena *arena = rt->sunat_arena;

    if (!arena && rt->malloc_state.opaque) {
        MBJSMemArena *a = (MBJSMemArena *)rt->malloc_state.opaque;
        if (a->magic == MBJS_MEM_ARENA_MAGIC)
            arena = a;
    }
    return arena;
}
#endif /* MBJS_SUNAT_GC */

