int MBJS_SetSuperset(MBJSRuntime *rt, const char *name)
{
    char *copy;
    if (!rt)
        return -1;
    if (rt->superset) {
        mbjs_free_rt(rt, rt->superset);
        rt->superset = NULL;
    }
    if (!name || !*name ||
        !strcmp(name, MBJS_SUPERSET_DEFAULT)) {
        return 0;
    }
    if (!mbjs_superset_lookup(name))
        return -1;
    copy = (char *)mbjs_malloc_rt(rt, strlen(name) + 1);
    if (!copy)
        return -1;
    strcpy(copy, name);
    rt->superset = copy;
    return 0;
}

