static MBJSValue mbjs_error_capture_stack_trace(MBJSContext *ctx, MBJSValueConst this_val,
                                            int argc, MBJSValueConst *argv)
{
    MBJSValueConst v = argv[0];
    if (MBJS_VALUE_GET_TAG(v) != MBJS_TAG_OBJECT)
        return MBJS_ThrowTypeErrorNotAnObject(ctx);
    build_backtrace(ctx, v, argv[1], NULL, 0, 0, MBJS_BACKTRACE_FLAG_SKIP_FIRST_LEVEL|MBJS_BACKTRACE_FLAG_FILTER_FUNC);
    return MBJS_UNDEFINED;
}

