/* AggregateError */

/* used by C code. */
static MBJSValue mbjs_aggregate_error_constructor(MBJSContext *ctx,
                                              MBJSValueConst errors)
{
    MBJSValue obj;

    obj = MBJS_NewObjectProtoClass(ctx,
                                 ctx->native_error_proto[MBJS_AGGREGATE_ERROR],
                                 MBJS_CLASS_ERROR);
    if (MBJS_IsException(obj))
        return obj;
    MBJS_DefinePropertyValueConst(ctx, obj, MBJS_ATOM_errors, errors,
                               MBJS_PROP_WRITABLE | MBJS_PROP_CONFIGURABLE);
    return obj;
}

/* Array */

static int MBJS_CopySubArray(MBJSContext *ctx,
                           MBJSValue obj, int64_t to_pos,
                           int64_t from_pos, int64_t count, int dir)
{
    MBJSObject *p;
    int64_t i, from, to, len;
    MBJSValue val;
    int fromPresent;

    p = NULL;
    if (MBJS_VALUE_GET_TAG(obj) == MBJS_TAG_OBJECT) {
        p = MBJS_VALUE_GET_OBJ(obj);
        if (p->class_id != MBJS_CLASS_ARRAY || !p->fast_array) {
            p = NULL;
        }
    }

    for (i = 0; i < count; ) {
        if (dir < 0) {
            from = from_pos + count - i - 1;
            to = to_pos + count - i - 1;
        } else {
            from = from_pos + i;
            to = to_pos + i;
        }
        if (p && p->fast_array &&
            from >= 0 && from < (len = p->u.array.count)  &&
            to >= 0 && to < len) {
            int64_t l, j;
            /* Fast path for fast arrays. Since we don't look at the
               prototype chain, we can optimize only the cases where
               all the elements are present in the array. */
            l = count - i;
            if (dir < 0) {
                l = min_int64(l, from + 1);
                l = min_int64(l, to + 1);
                for(j = 0; j < l; j++) {
                    set_value(ctx, &p->u.array.u.values[to - j],
                              mbjs_dup(p->u.array.u.values[from - j]));
                }
            } else {
                l = min_int64(l, len - from);
                l = min_int64(l, len - to);
                for(j = 0; j < l; j++) {
                    set_value(ctx, &p->u.array.u.values[to + j],
                              mbjs_dup(p->u.array.u.values[from + j]));
                }
            }
            i += l;
        } else {
            fromPresent = MBJS_TryGetPropertyInt64(ctx, obj, from, &val);
            if (fromPresent < 0)
                goto exception;

            if (fromPresent) {
                if (MBJS_SetPropertyInt64(ctx, obj, to, val) < 0)
                    goto exception;
            } else {
                if (MBJS_DeletePropertyInt64(ctx, obj, to, MBJS_PROP_THROW) < 0)
                    goto exception;
            }
            i++;
        }
    }
    return 0;

 exception:
    return -1;
}

static MBJSValue mbjs_array_constructor(MBJSContext *ctx, MBJSValueConst new_target,
                                    int argc, MBJSValueConst *argv)
{
    MBJSValue obj;
    int i;

    obj = mbjs_create_from_ctor(ctx, new_target, MBJS_CLASS_ARRAY);
    if (MBJS_IsException(obj))
        return obj;
    if (argc == 1 && MBJS_IsNumber(argv[0])) {
        uint32_t len;
        if (MBJS_ToArrayLengthFree(ctx, &len, mbjs_dup(argv[0]), true))
            goto fail;
        if (MBJS_SetProperty(ctx, obj, MBJS_ATOM_length, mbjs_uint32(len)) < 0)
            goto fail;
    } else {
        for(i = 0; i < argc; i++) {
            if (MBJS_SetPropertyUint32(ctx, obj, i, mbjs_dup(argv[i])) < 0)
                goto fail;
        }
    }
    return obj;
fail:
    MBJS_FreeValue(ctx, obj);
    return MBJS_EXCEPTION;
}

static MBJSValue mbjs_array_from(MBJSContext *ctx, MBJSValueConst this_val,
                             int argc, MBJSValueConst *argv)
{
    // from(items, mapfn = void 0, this_arg = void 0)
    MBJSValueConst items = argv[0], mapfn, this_arg;
    MBJSValueConst args[2];
    MBJSValue stack[2];
    MBJSValue iter, r, v, v2, arrayLike;
    int64_t k, len;
    int done, mapping;

    mapping = false;
    mapfn = MBJS_UNDEFINED;
    this_arg = MBJS_UNDEFINED;
    r = MBJS_UNDEFINED;
    arrayLike = MBJS_UNDEFINED;
    stack[0] = MBJS_UNDEFINED;
    stack[1] = MBJS_UNDEFINED;

    if (argc > 1) {
        mapfn = argv[1];
        if (!MBJS_IsUndefined(mapfn)) {
            if (check_function(ctx, mapfn))
                goto exception;
            mapping = 1;
            if (argc > 2)
                this_arg = argv[2];
        }
    }
    iter = MBJS_GetProperty(ctx, items, MBJS_ATOM_Symbol_iterator);
    if (MBJS_IsException(iter))
        goto exception;
    if (!MBJS_IsUndefined(iter)) {
        MBJS_FreeValue(ctx, iter);
        if (MBJS_IsConstructor(ctx, this_val))
            r = MBJS_CallConstructor(ctx, this_val, 0, NULL);
        else
            r = MBJS_NewArray(ctx);
        if (MBJS_IsException(r))
            goto exception;
        stack[0] = mbjs_dup(items);
        if (mbjs_for_of_start(ctx, &stack[1], false))
            goto exception;
        for (k = 0;; k++) {
            v = MBJS_IteratorNext(ctx, stack[0], stack[1], 0, NULL, &done);
            if (MBJS_IsException(v))
                goto exception_close;
            if (done)
                break;
            if (mapping) {
                args[0] = v;
                args[1] = mbjs_int32(k);
                v2 = MBJS_Call(ctx, mapfn, this_arg, 2, args);
                MBJS_FreeValue(ctx, v);
                v = v2;
                if (MBJS_IsException(v))
                    goto exception_close;
            }
            if (MBJS_DefinePropertyValueInt64(ctx, r, k, v,
                                            MBJS_PROP_C_W_E | MBJS_PROP_THROW) < 0)
                goto exception_close;
        }
    } else {
        arrayLike = MBJS_ToObject(ctx, items);
        if (MBJS_IsException(arrayLike))
            goto exception;
        if (mbjs_get_length64(ctx, &len, arrayLike) < 0)
            goto exception;
        v = mbjs_int64(len);
        args[0] = v;
        if (MBJS_IsConstructor(ctx, this_val)) {
            r = MBJS_CallConstructor(ctx, this_val, 1, args);
        } else {
            r = mbjs_array_constructor(ctx, MBJS_UNDEFINED, 1, args);
        }
        MBJS_FreeValue(ctx, v);
        if (MBJS_IsException(r))
            goto exception;
        for(k = 0; k < len; k++) {
            v = MBJS_GetPropertyInt64(ctx, arrayLike, k);
            if (MBJS_IsException(v))
                goto exception;
            if (mapping) {
                args[0] = v;
                args[1] = mbjs_int32(k);
                v2 = MBJS_Call(ctx, mapfn, this_arg, 2, args);
                MBJS_FreeValue(ctx, v);
                v = v2;
                if (MBJS_IsException(v))
                    goto exception;
            }
            if (MBJS_DefinePropertyValueInt64(ctx, r, k, v,
                                            MBJS_PROP_C_W_E | MBJS_PROP_THROW) < 0)
                goto exception;
        }
    }
    if (MBJS_SetProperty(ctx, r, MBJS_ATOM_length, mbjs_uint32(k)) < 0)
        goto exception;
    goto done;

 exception_close:
    if (!MBJS_IsUndefined(stack[0]))
        MBJS_IteratorClose(ctx, stack[0], true);
 exception:
    MBJS_FreeValue(ctx, r);
    r = MBJS_EXCEPTION;
 done:
    MBJS_FreeValue(ctx, arrayLike);
    MBJS_FreeValue(ctx, stack[0]);
    MBJS_FreeValue(ctx, stack[1]);
    return r;
}

static MBJSValue mbjs_array_of(MBJSContext *ctx, MBJSValueConst this_val,
                           int argc, MBJSValueConst *argv)
{
    MBJSValue n, obj;
    int i;

    if (MBJS_IsConstructor(ctx, this_val)) {
        n = mbjs_int32(argc);
        obj = MBJS_CallConstructor(ctx, this_val, 1, vc(&n));
    } else {
        obj = MBJS_NewArray(ctx);
    }
    if (MBJS_IsException(obj))
        return MBJS_EXCEPTION;
    for(i = 0; i < argc; i++) {
        if (MBJS_CreateDataPropertyUint32Const(ctx, obj, i, argv[i],
                                             MBJS_PROP_THROW) < 0) {
            goto fail;
        }
    }
    if (MBJS_SetProperty(ctx, obj, MBJS_ATOM_length, mbjs_uint32(argc)) < 0) {
    fail:
        MBJS_FreeValue(ctx, obj);
        return MBJS_EXCEPTION;
    }
    return obj;
}

static MBJSValue mbjs_array_isArray(MBJSContext *ctx, MBJSValueConst this_val,
                                int argc, MBJSValueConst *argv)
{
    int ret;
    ret = mbjs_is_array(ctx, argv[0]);
    if (ret < 0)
        return MBJS_EXCEPTION;
    else
        return mbjs_bool(ret);
}

static MBJSValue mbjs_get_this(MBJSContext *ctx, MBJSValueConst this_val)
{
    return mbjs_dup(this_val);
}

static MBJSValue MBJS_ArraySpeciesCreate(MBJSContext *ctx, MBJSValueConst obj,
                                     MBJSValueConst len_val)
{
    MBJSValue ctor, ret, species;
    int res;
    MBJSContext *realm;

    res = mbjs_is_array(ctx, obj);
    if (res < 0)
        return MBJS_EXCEPTION;
    if (!res)
        return mbjs_array_constructor(ctx, MBJS_UNDEFINED, 1, &len_val);
    ctor = MBJS_GetProperty(ctx, obj, MBJS_ATOM_constructor);
    if (MBJS_IsException(ctor))
        return ctor;
    if (MBJS_IsConstructor(ctx, ctor)) {
        /* legacy web compatibility */
        realm = MBJS_GetFunctionRealm(ctx, ctor);
        if (!realm) {
            MBJS_FreeValue(ctx, ctor);
            return MBJS_EXCEPTION;
        }
        if (realm != ctx &&
            mbjs_same_value(ctx, ctor, realm->array_ctor)) {
            MBJS_FreeValue(ctx, ctor);
            ctor = MBJS_UNDEFINED;
        }
    }
    if (MBJS_IsObject(ctor)) {
        species = MBJS_GetProperty(ctx, ctor, MBJS_ATOM_Symbol_species);
        MBJS_FreeValue(ctx, ctor);
        if (MBJS_IsException(species))
            return species;
        ctor = species;
        if (MBJS_IsNull(ctor))
            ctor = MBJS_UNDEFINED;
    }
    if (MBJS_IsUndefined(ctor)) {
        return mbjs_array_constructor(ctx, MBJS_UNDEFINED, 1, &len_val);
    } else {
        ret = MBJS_CallConstructor(ctx, ctor, 1, &len_val);
        MBJS_FreeValue(ctx, ctor);
        return ret;
    }
}

static const MBJSCFunctionListEntry mbjs_array_funcs[] = {
    MBJS_CFUNC_DEF("isArray", 1, mbjs_array_isArray ),
    MBJS_CFUNC_DEF("from", 1, mbjs_array_from ),
    MBJS_CFUNC_DEF("of", 0, mbjs_array_of ),
    MBJS_CGETSET_DEF("[Symbol.species]", mbjs_get_this, NULL ),
};

static int MBJS_isConcatSpreadable(MBJSContext *ctx, MBJSValueConst obj)
{
    MBJSValue val;

    if (!MBJS_IsObject(obj))
        return false;
    val = MBJS_GetProperty(ctx, obj, MBJS_ATOM_Symbol_isConcatSpreadable);
    if (MBJS_IsException(val))
        return -1;
    if (!MBJS_IsUndefined(val))
        return MBJS_ToBoolFree(ctx, val);
    return mbjs_is_array(ctx, obj);
}

static MBJSValue mbjs_array_at(MBJSContext *ctx, MBJSValueConst this_val,
                           int argc, MBJSValueConst *argv)
{
    MBJSValue obj, ret;
    int64_t len, idx;

    ret = MBJS_EXCEPTION;
    obj = MBJS_ToObject(ctx, this_val);
    if (mbjs_get_length64(ctx, &len, obj))
        goto exception;

    if (MBJS_ToInt64Sat(ctx, &idx, argv[0]))
        goto exception;

    if (idx < 0)
        idx = len + idx;

    if (idx < 0 || idx >= len) {
        ret = MBJS_UNDEFINED;
    } else {
        ret = MBJS_GetPropertyInt64(ctx, obj, idx);
    }

 exception:
    MBJS_FreeValue(ctx, obj);
    return ret;
}

static MBJSValue mbjs_array_with(MBJSContext *ctx, MBJSValueConst this_val,
                             int argc, MBJSValueConst *argv)
{
    MBJSValue arr, obj, ret, *arrp, *pval;
    MBJSObject *p;
    int64_t i, len, idx;
    uint32_t count32;

    ret = MBJS_EXCEPTION;
    arr = MBJS_UNDEFINED;
    obj = MBJS_ToObject(ctx, this_val);
    if (mbjs_get_length64(ctx, &len, obj))
        goto exception;

    if (MBJS_ToInt64Sat(ctx, &idx, argv[0]))
        goto exception;

    if (idx < 0)
        idx = len + idx;

    if (idx < 0 || idx >= len) {
        MBJS_ThrowRangeError(ctx, "invalid array index: %" PRId64, idx);
        goto exception;
    }

    arr = mbjs_allocate_fast_array(ctx, len);
    if (MBJS_IsException(arr))
        goto exception;

    p = MBJS_VALUE_GET_OBJ(arr);
    i = 0;
    pval = p->u.array.u.values;
    if (mbjs_get_fast_array(ctx, obj, &arrp, &count32) && count32 == len) {
        for (; i < idx; i++, pval++)
            *pval = mbjs_dup(arrp[i]);
        *pval = mbjs_dup(argv[1]);
        for (i++, pval++; i < len; i++, pval++)
            *pval = mbjs_dup(arrp[i]);
    } else {
        for (; i < idx; i++, pval++)
            if (-1 == MBJS_TryGetPropertyInt64(ctx, obj, i, pval))
                goto exception;
        *pval = mbjs_dup(argv[1]);
        for (i++, pval++; i < len; i++, pval++) {
            if (-1 == MBJS_TryGetPropertyInt64(ctx, obj, i, pval))
                goto exception;
        }
    }

    ret = arr;
    arr = MBJS_UNDEFINED;

exception:
    MBJS_FreeValue(ctx, arr);
    MBJS_FreeValue(ctx, obj);
    return ret;
}

static MBJSValue mbjs_array_concat(MBJSContext *ctx, MBJSValueConst this_val,
                               int argc, MBJSValueConst *argv)
{
    MBJSValue obj, arr, val;
    MBJSValueConst e;
    int64_t len, k, n;
    int i, res;

    arr = MBJS_UNDEFINED;
    obj = MBJS_ToObject(ctx, this_val);
    if (MBJS_IsException(obj))
        goto exception;

    arr = MBJS_ArraySpeciesCreate(ctx, obj, mbjs_int32(0));
    if (MBJS_IsException(arr))
        goto exception;
    n = 0;
    for (i = -1; i < argc; i++) {
        if (i < 0)
            e = obj;
        else
            e = argv[i];

        res = MBJS_isConcatSpreadable(ctx, e);
        if (res < 0)
            goto exception;
        if (res) {
            if (mbjs_get_length64(ctx, &len, e))
                goto exception;
            if (n + len > MAX_SAFE_INTEGER) {
                MBJS_ThrowTypeError(ctx, "Array loo long");
                goto exception;
            }
            for (k = 0; k < len; k++, n++) {
                res = MBJS_TryGetPropertyInt64(ctx, e, k, &val);
                if (res < 0)
                    goto exception;
                if (res) {
                    if (MBJS_DefinePropertyValueInt64(ctx, arr, n, val,
                                                    MBJS_PROP_C_W_E | MBJS_PROP_THROW) < 0)
                        goto exception;
                }
            }
        } else {
            if (n >= MAX_SAFE_INTEGER) {
                MBJS_ThrowTypeError(ctx, "Array loo long");
                goto exception;
            }
            if (MBJS_DefinePropertyValueInt64Const(ctx, arr, n, e,
                                                 MBJS_PROP_C_W_E | MBJS_PROP_THROW) < 0)
                goto exception;
            n++;
        }
    }
    if (MBJS_SetProperty(ctx, arr, MBJS_ATOM_length, mbjs_int64(n)) < 0)
        goto exception;

    MBJS_FreeValue(ctx, obj);
    return arr;

exception:
    MBJS_FreeValue(ctx, arr);
    MBJS_FreeValue(ctx, obj);
    return MBJS_EXCEPTION;
}

#define special_every    0
#define special_some     1
#define special_forEach  2
#define special_map      3
#define special_filter   4
#define special_TA       8

static MBJSObject *get_typed_array(MBJSContext *ctx, MBJSValueConst this_val)
{
    MBJSObject *p;
    if (MBJS_VALUE_GET_TAG(this_val) != MBJS_TAG_OBJECT)
        goto fail;
    p = MBJS_VALUE_GET_OBJ(this_val);
    if (!is_typed_array(p->class_id)) {
    fail:
        MBJS_ThrowTypeError(ctx, "not a TypedArray");
        return NULL;
    }
    return p;
}

// Be *very* careful if you touch the typed array's memory directly:
// the length is only valid until the next call into JS land because
// JS code can detach or resize the backing array buffer. Functions
// like MBJS_GetProperty and MBJS_ToIndex call JS code.
//
// Exclusively reading or writing elements with MBJS_GetProperty,
// MBJS_GetPropertyInt64, MBJS_SetProperty, etc. is safe because they
// perform bounds checks, as does mbjs_get_fast_array_element.
static int mbjs_typed_array_get_length_unsafe(MBJSContext *ctx, MBJSValueConst obj)
{
    MBJSObject *p;
    p = get_typed_array(ctx, obj);
    if (!p)
        return -1;
    if (typed_array_is_oob(p)) {
        MBJS_ThrowTypeErrorArrayBufferOOB(ctx);
        return -1;
    }
    return p->u.array.count;
}

static MBJSValue mbjs_typed_array___speciesCreate(MBJSContext *ctx,
                                              MBJSValueConst this_val,
                                              int argc, MBJSValueConst *argv,
                                              bool require_mutable);

static MBJSValue mbjs_array_every(MBJSContext *ctx, MBJSValueConst this_val,
                              int argc, MBJSValueConst *argv, int special)
{
    MBJSValue obj, val, index_val, res, ret;
    MBJSValueConst args[3];
    MBJSValueConst func, this_arg;
    int64_t len, k, n;
    int present;

    ret = MBJS_UNDEFINED;
    val = MBJS_UNDEFINED;
    if (special & special_TA) {
        obj = mbjs_dup(this_val);
        len = mbjs_typed_array_get_length_unsafe(ctx, obj);
        if (len < 0)
            goto exception;
    } else {
        obj = MBJS_ToObject(ctx, this_val);
        if (mbjs_get_length64(ctx, &len, obj))
            goto exception;
    }
    func = argv[0];
    this_arg = MBJS_UNDEFINED;
    if (argc > 1)
        this_arg = argv[1];

    if (check_function(ctx, func))
        goto exception;

    switch (special) {
    case special_every:
    case special_every | special_TA:
        ret = MBJS_TRUE;
        break;
    case special_some:
    case special_some | special_TA:
        ret = MBJS_FALSE;
        break;
    case special_map:
        /* XXX: MBJS_ArraySpeciesCreate should take int64_t */
        ret = MBJS_ArraySpeciesCreate(ctx, obj, mbjs_int64(len));
        if (MBJS_IsException(ret))
            goto exception;
        break;
    case special_filter:
        ret = MBJS_ArraySpeciesCreate(ctx, obj, mbjs_int32(0));
        if (MBJS_IsException(ret))
            goto exception;
        break;
    case special_map | special_TA:
        args[0] = obj;
        args[1] = mbjs_int32(len);
        ret = mbjs_typed_array___speciesCreate(ctx, MBJS_UNDEFINED, 2, args, true);
        if (MBJS_IsException(ret))
            goto exception;
        break;
    case special_filter | special_TA:
        ret = MBJS_NewArray(ctx);
        if (MBJS_IsException(ret))
            goto exception;
        break;
    }
    n = 0;

    for(k = 0; k < len; k++) {
        if (mbjs_poll_interrupts(ctx))
            goto exception;
        if (special & special_TA) {
            val = MBJS_GetPropertyInt64(ctx, obj, k);
            if (MBJS_IsException(val))
                goto exception;
            present = true;
        } else {
            present = MBJS_TryGetPropertyInt64(ctx, obj, k, &val);
            if (present < 0)
                goto exception;
        }
        if (present) {
            index_val = mbjs_int64(k);
            args[0] = val;
            args[1] = index_val;
            args[2] = obj;
            res = MBJS_Call(ctx, func, this_arg, 3, args);
            MBJS_FreeValue(ctx, index_val);
            if (MBJS_IsException(res))
                goto exception;
            switch (special) {
            case special_every:
            case special_every | special_TA:
                if (!MBJS_ToBoolFree(ctx, res)) {
                    ret = MBJS_FALSE;
                    goto done;
                }
                break;
            case special_some:
            case special_some | special_TA:
                if (MBJS_ToBoolFree(ctx, res)) {
                    ret = MBJS_TRUE;
                    goto done;
                }
                break;
            case special_map:
                if (MBJS_DefinePropertyValueInt64(ctx, ret, k, res,
                                                MBJS_PROP_C_W_E | MBJS_PROP_THROW) < 0)
                    goto exception;
                break;
            case special_map | special_TA:
                if (MBJS_SetPropertyValue(ctx, ret, mbjs_int32(k), res, MBJS_PROP_THROW) < 0)
                    goto exception;
                break;
            case special_filter:
            case special_filter | special_TA:
                if (MBJS_ToBoolFree(ctx, res)) {
                    if (MBJS_DefinePropertyValueInt64Const(ctx, ret, n++, val,
                                                         MBJS_PROP_C_W_E | MBJS_PROP_THROW) < 0)
                        goto exception;
                }
                break;
            default:
                MBJS_FreeValue(ctx, res);
                break;
            }
            MBJS_FreeValue(ctx, val);
            val = MBJS_UNDEFINED;
        }
    }
done:
    if (special == (special_filter | special_TA)) {
        MBJSValue arr;
        args[0] = obj;
        args[1] = mbjs_int32(n);
        arr = mbjs_typed_array___speciesCreate(ctx, MBJS_UNDEFINED, 2, args, true);
        if (MBJS_IsException(arr))
            goto exception;
        args[0] = ret;
        res = MBJS_Invoke(ctx, arr, MBJS_ATOM_set, 1, args);
        if (check_exception_free(ctx, res)) {
            MBJS_FreeValue(ctx, arr);
            goto exception;
        }
        MBJS_FreeValue(ctx, ret);
        ret = arr;
    }
    MBJS_FreeValue(ctx, val);
    MBJS_FreeValue(ctx, obj);
    return ret;

exception:
    MBJS_FreeValue(ctx, ret);
    MBJS_FreeValue(ctx, val);
    MBJS_FreeValue(ctx, obj);
    return MBJS_EXCEPTION;
}

#define special_reduce       0
#define special_reduceRight  1

static MBJSValue mbjs_array_reduce(MBJSContext *ctx, MBJSValueConst this_val,
                               int argc, MBJSValueConst *argv, int special)
{
    MBJSValue obj, val, index_val, acc, acc1;
    MBJSValueConst args[4];
    MBJSValueConst func;
    int64_t len, k, k1;
    int present;

    acc = MBJS_UNDEFINED;
    val = MBJS_UNDEFINED;
    if (special & special_TA) {
        obj = mbjs_dup(this_val);
        len = mbjs_typed_array_get_length_unsafe(ctx, obj);
        if (len < 0)
            goto exception;
    } else {
        obj = MBJS_ToObject(ctx, this_val);
        if (mbjs_get_length64(ctx, &len, obj))
            goto exception;
    }
    func = argv[0];

    if (check_function(ctx, func))
        goto exception;

    k = 0;
    if (argc > 1) {
        acc = mbjs_dup(argv[1]);
    } else {
        for(;;) {
            if (k >= len) {
                MBJS_ThrowTypeError(ctx, "empty array");
                goto exception;
            }
            if (mbjs_poll_interrupts(ctx))
                goto exception;
            k1 = (special & special_reduceRight) ? len - k - 1 : k;
            k++;
            if (special & special_TA) {
                acc = MBJS_GetPropertyInt64(ctx, obj, k1);
                if (MBJS_IsException(acc))
                    goto exception;
                break;
            } else {
                present = MBJS_TryGetPropertyInt64(ctx, obj, k1, &acc);
                if (present < 0)
                    goto exception;
                if (present)
                    break;
            }
        }
    }
    for (; k < len; k++) {
        if (mbjs_poll_interrupts(ctx))
            goto exception;
        k1 = (special & special_reduceRight) ? len - k - 1 : k;
        if (special & special_TA) {
            val = MBJS_GetPropertyInt64(ctx, obj, k1);
            if (MBJS_IsException(val))
                goto exception;
            present = true;
        } else {
            present = MBJS_TryGetPropertyInt64(ctx, obj, k1, &val);
            if (present < 0)
                goto exception;
        }
        if (present) {
            index_val = mbjs_int64(k1);
            args[0] = acc;
            args[1] = val;
            args[2] = index_val;
            args[3] = obj;
            acc1 = MBJS_Call(ctx, func, MBJS_UNDEFINED, 4, args);
            MBJS_FreeValue(ctx, index_val);
            MBJS_FreeValue(ctx, val);
            val = MBJS_UNDEFINED;
            if (MBJS_IsException(acc1))
                goto exception;
            MBJS_FreeValue(ctx, acc);
            acc = acc1;
        }
    }
    MBJS_FreeValue(ctx, obj);
    return acc;

exception:
    MBJS_FreeValue(ctx, acc);
    MBJS_FreeValue(ctx, val);
    MBJS_FreeValue(ctx, obj);
    return MBJS_EXCEPTION;
}

static MBJSValue mbjs_array_fill(MBJSContext *ctx, MBJSValueConst this_val,
                             int argc, MBJSValueConst *argv)
{
    MBJSValue obj;
    int64_t len, start, end;

    obj = MBJS_ToObject(ctx, this_val);
    if (mbjs_get_length64(ctx, &len, obj))
        goto exception;

    start = 0;
    if (argc > 1 && !MBJS_IsUndefined(argv[1])) {
        if (MBJS_ToInt64Clamp(ctx, &start, argv[1], 0, len, len))
            goto exception;
    }

    end = len;
    if (argc > 2 && !MBJS_IsUndefined(argv[2])) {
        if (MBJS_ToInt64Clamp(ctx, &end, argv[2], 0, len, len))
            goto exception;
    }

    /* XXX: should special case fast arrays */
    while (start < end) {
        if (MBJS_SetPropertyInt64(ctx, obj, start, mbjs_dup(argv[0])) < 0)
            goto exception;
        start++;
    }
    return obj;

 exception:
    MBJS_FreeValue(ctx, obj);
    return MBJS_EXCEPTION;
}

static MBJSValue mbjs_array_includes(MBJSContext *ctx, MBJSValueConst this_val,
                                 int argc, MBJSValueConst *argv)
{
    MBJSValue obj, val;
    int64_t len, n;
    MBJSValue *arrp;
    uint32_t count;
    int res;

    obj = MBJS_ToObject(ctx, this_val);
    if (mbjs_get_length64(ctx, &len, obj))
        goto exception;

    res = true;
    if (len > 0) {
        n = 0;
        if (argc > 1) {
            if (MBJS_ToInt64Clamp(ctx, &n, argv[1], 0, len, len))
                goto exception;
        }
        if (mbjs_get_fast_array(ctx, obj, &arrp, &count)) {
            for (; n < count; n++) {
                if (mbjs_strict_eq2(ctx, argv[0], arrp[n],
                                  MBJS_EQ_SAME_VALUE_ZERO)) {
                    goto done;
                }
            }
        }
        for (; n < len; n++) {
            if (mbjs_poll_interrupts(ctx))
                goto exception;
            val = MBJS_GetPropertyInt64(ctx, obj, n);
            if (MBJS_IsException(val))
                goto exception;
            if (mbjs_strict_eq2(ctx, argv[0], val, MBJS_EQ_SAME_VALUE_ZERO)) {
                MBJS_FreeValue(ctx, val);
                goto done;
            }
            MBJS_FreeValue(ctx, val);
        }
    }
    res = false;
 done:
    MBJS_FreeValue(ctx, obj);
    return mbjs_bool(res);

 exception:
    MBJS_FreeValue(ctx, obj);
    return MBJS_EXCEPTION;
}

static MBJSValue mbjs_array_indexOf(MBJSContext *ctx, MBJSValueConst this_val,
                                int argc, MBJSValueConst *argv)
{
    MBJSValue obj, val;
    int64_t len, n;
    MBJSValue *arrp;
    uint32_t count;

    obj = MBJS_ToObject(ctx, this_val);
    if (mbjs_get_length64(ctx, &len, obj))
        goto exception;

    if (len > 0) {
        n = 0;
        if (argc > 1) {
            if (MBJS_ToInt64Clamp(ctx, &n, argv[1], 0, len, len))
                goto exception;
        }
        if (mbjs_get_fast_array(ctx, obj, &arrp, &count)) {
            for (; n < count; n++) {
                if (mbjs_strict_eq2(ctx, argv[0], arrp[n], MBJS_EQ_STRICT)) {
                    goto done;
                }
            }
        }
        for (; n < len; n++) {
            if (mbjs_poll_interrupts(ctx))
                goto exception;
            int present = MBJS_TryGetPropertyInt64(ctx, obj, n, &val);
            if (present < 0)
                goto exception;
            if (present) {
                if (mbjs_strict_eq2(ctx, argv[0], val, MBJS_EQ_STRICT)) {
                    MBJS_FreeValue(ctx, val);
                    goto done;
                }
                MBJS_FreeValue(ctx, val);
            }
        }
    }
    n = -1;
 done:
    MBJS_FreeValue(ctx, obj);
    return mbjs_int64(n);

 exception:
    MBJS_FreeValue(ctx, obj);
    return MBJS_EXCEPTION;
}

static MBJSValue mbjs_array_lastIndexOf(MBJSContext *ctx, MBJSValueConst this_val,
                                    int argc, MBJSValueConst *argv)
{
    MBJSValue obj, val;
    int64_t len, n;
    MBJSValue *arrp;
    uint32_t count;

    obj = MBJS_ToObject(ctx, this_val);
    if (mbjs_get_length64(ctx, &len, obj))
        goto exception;

    if (len > 0) {
        n = len - 1;
        if (argc > 1) {
            if (MBJS_ToInt64Clamp(ctx, &n, argv[1], -1, len - 1, len))
                goto exception;
        }
        if (mbjs_get_fast_array(ctx, obj, &arrp, &count) && count == len) {
            for (; n >= 0; n--) {
                if (mbjs_strict_eq2(ctx, argv[0], arrp[n],
                                  MBJS_EQ_STRICT)) {
                    goto done;
                }
            }
        }
        for (; n >= 0; n--) {
            if (mbjs_poll_interrupts(ctx))
                goto exception;
            int present = MBJS_TryGetPropertyInt64(ctx, obj, n, &val);
            if (present < 0)
                goto exception;
            if (present) {
                if (mbjs_strict_eq2(ctx, argv[0], val, MBJS_EQ_STRICT)) {
                    MBJS_FreeValue(ctx, val);
                    goto done;
                }
                MBJS_FreeValue(ctx, val);
            }
        }
    }
    n = -1;
 done:
    MBJS_FreeValue(ctx, obj);
    return mbjs_int64(n);

 exception:
    MBJS_FreeValue(ctx, obj);
    return MBJS_EXCEPTION;
}

enum {
    ArrayFind,
    ArrayFindIndex,
    ArrayFindLast,
    ArrayFindLastIndex,
};

static MBJSValue mbjs_array_find(MBJSContext *ctx, MBJSValueConst this_val,
                             int argc, MBJSValueConst *argv, int mode)
{
    MBJSValueConst func, this_arg;
    MBJSValueConst args[3];
    MBJSValue obj, val, index_val, res;
    int64_t len, k, end;
    int dir;

    index_val = MBJS_UNDEFINED;
    val = MBJS_UNDEFINED;
    obj = MBJS_ToObject(ctx, this_val);
    if (mbjs_get_length64(ctx, &len, obj))
        goto exception;

    func = argv[0];
    if (check_function(ctx, func))
        goto exception;

    this_arg = MBJS_UNDEFINED;
    if (argc > 1)
        this_arg = argv[1];

    k = 0;
    dir = 1;
    end = len;
    if (mode == ArrayFindLast || mode == ArrayFindLastIndex) {
        k = len - 1;
        dir = -1;
        end = -1;
    }

    // TODO(bnoordhuis) add fast path for fast arrays
    for(; k != end; k += dir) {
        if (mbjs_poll_interrupts(ctx))
            goto exception;
        index_val = mbjs_int64(k);
        val = MBJS_GetPropertyValue(ctx, obj, index_val);
        if (MBJS_IsException(val))
            goto exception;
        args[0] = val;
        args[1] = index_val;
        args[2] = this_val;
        res = MBJS_Call(ctx, func, this_arg, 3, args);
        if (MBJS_IsException(res))
            goto exception;
        if (MBJS_ToBoolFree(ctx, res)) {
            if (mode == ArrayFindIndex || mode == ArrayFindLastIndex) {
                MBJS_FreeValue(ctx, val);
                MBJS_FreeValue(ctx, obj);
                return index_val;
            } else {
                MBJS_FreeValue(ctx, index_val);
                MBJS_FreeValue(ctx, obj);
                return val;
            }
        }
        MBJS_FreeValue(ctx, val);
        MBJS_FreeValue(ctx, index_val);
    }
    MBJS_FreeValue(ctx, obj);
    if (mode == ArrayFindIndex || mode == ArrayFindLastIndex)
        return mbjs_int32(-1);
    else
        return MBJS_UNDEFINED;

exception:
    MBJS_FreeValue(ctx, index_val);
    MBJS_FreeValue(ctx, val);
    MBJS_FreeValue(ctx, obj);
    return MBJS_EXCEPTION;
}

static MBJSValue mbjs_array_toString(MBJSContext *ctx, MBJSValueConst this_val,
                                 int argc, MBJSValueConst *argv)
{
    MBJSValue obj, method, ret;

    obj = MBJS_ToObject(ctx, this_val);
    if (MBJS_IsException(obj))
        return MBJS_EXCEPTION;
    method = MBJS_GetProperty(ctx, obj, MBJS_ATOM_join);
    if (MBJS_IsException(method)) {
        ret = MBJS_EXCEPTION;
    } else
    if (!MBJS_IsFunction(ctx, method)) {
        /* Use intrinsic Object.prototype.toString */
        MBJS_FreeValue(ctx, method);
        ret = mbjs_object_toString(ctx, obj, 0, NULL);
    } else {
        ret = MBJS_CallFree(ctx, method, obj, 0, NULL);
    }
    MBJS_FreeValue(ctx, obj);
    return ret;
}

static MBJSValue mbjs_array_join(MBJSContext *ctx, MBJSValueConst this_val,
                             int argc, MBJSValueConst *argv, int toLocaleString)
{
    MBJSValue obj, sep = MBJS_UNDEFINED, el;
    StringBuffer b_s, *b = &b_s;
    MBJSString *p = NULL;
    int64_t i, n;
    int c;

    obj = MBJS_ToObject(ctx, this_val);
    if (mbjs_get_length64(ctx, &n, obj))
        goto exception;

    c = ',';    /* default separator */
    if (!toLocaleString && argc > 0 && !MBJS_IsUndefined(argv[0])) {
        sep = MBJS_ToString(ctx, argv[0]);
        if (MBJS_IsException(sep))
            goto exception;
        p = MBJS_VALUE_GET_STRING(sep);
        if (p->len == 1 && !p->is_wide_char)
            c = str8(p)[0];
        else
            c = -1;
    }
    string_buffer_init(ctx, b, 0);

    for(i = 0; i < n; i++) {
        if (i > 0) {
            if (c >= 0) {
                string_buffer_putc8(b, c);
            } else {
                string_buffer_concat(b, p, 0, p->len);
            }
        }
        el = MBJS_GetPropertyUint32(ctx, obj, i);
        if (MBJS_IsException(el))
            goto fail;
        if (!MBJS_IsNull(el) && !MBJS_IsUndefined(el)) {
            if (toLocaleString) {
                el = MBJS_ToLocaleStringFree(ctx, el);
            }
            if (string_buffer_concat_value_free(b, el))
                goto fail;
        }
    }
    MBJS_FreeValue(ctx, sep);
    MBJS_FreeValue(ctx, obj);
    return string_buffer_end(b);

fail:
    string_buffer_free(b);
    MBJS_FreeValue(ctx, sep);
exception:
    MBJS_FreeValue(ctx, obj);
    return MBJS_EXCEPTION;
}

static MBJSValue mbjs_array_pop(MBJSContext *ctx, MBJSValueConst this_val,
                            int argc, MBJSValueConst *argv, int shift)
{
    MBJSValue obj, res = MBJS_UNDEFINED;
    int64_t len, newLen;
    MBJSValue *arrp;
    uint32_t count32;

    obj = MBJS_ToObject(ctx, this_val);
    if (mbjs_get_length64(ctx, &len, obj))
        goto exception;
    newLen = 0;
    if (len > 0) {
        newLen = len - 1;
        /* Special case fast arrays */
        if (mbjs_get_fast_array(ctx, obj, &arrp, &count32) && count32 == len) {
            MBJSObject *p = MBJS_VALUE_GET_OBJ(obj);
            if (shift) {
                res = arrp[0];
                memmove(arrp, arrp + 1, (count32 - 1) * sizeof(*arrp));
                p->u.array.count--;
            } else {
                res = arrp[count32 - 1];
                p->u.array.count--;
            }
        } else {
            if (shift) {
                res = MBJS_GetPropertyInt64(ctx, obj, 0);
                if (MBJS_IsException(res))
                    goto exception;
                if (MBJS_CopySubArray(ctx, obj, 0, 1, len - 1, +1))
                    goto exception;
            } else {
                res = MBJS_GetPropertyInt64(ctx, obj, newLen);
                if (MBJS_IsException(res))
                    goto exception;
            }
            if (MBJS_DeletePropertyInt64(ctx, obj, newLen, MBJS_PROP_THROW) < 0)
                goto exception;
        }
    }
    if (MBJS_SetProperty(ctx, obj, MBJS_ATOM_length, mbjs_int64(newLen)) < 0)
        goto exception;

    MBJS_FreeValue(ctx, obj);
    return res;

 exception:
    MBJS_FreeValue(ctx, res);
    MBJS_FreeValue(ctx, obj);
    return MBJS_EXCEPTION;
}

static MBJSValue mbjs_array_push(MBJSContext *ctx, MBJSValueConst this_val,
                             int argc, MBJSValueConst *argv, int unshift)
{
    MBJSValue obj;
    int i;
    int64_t len, from, newLen;

    /* fast path for push on fast arrays */
    if (likely(MBJS_VALUE_GET_TAG(this_val) == MBJS_TAG_OBJECT && !unshift)) {
        MBJSObject *p = MBJS_VALUE_GET_OBJ(this_val);
        if (likely(p->class_id == MBJS_CLASS_ARRAY &&
                   p->fast_array &&
                   p->extensible &&
                   p->shape->proto == MBJS_VALUE_GET_OBJ(ctx->class_proto[MBJS_CLASS_ARRAY]) &&
                   ctx->std_array_prototype)) {
            uint32_t array_len, new_len;
            if (likely(MBJS_VALUE_GET_TAG(p->prop[0].u.value) == MBJS_TAG_INT &&
                       (get_shape_prop(p->shape)->flags & MBJS_PROP_WRITABLE))) {
                array_len = MBJS_VALUE_GET_INT(p->prop[0].u.value);
                new_len = array_len + argc;
                if (likely(array_len == p->u.array.count &&
                           new_len >= array_len && new_len <= (uint32_t)INT32_MAX)) { /* no overflow and within fast-array bounds */
                    if (unlikely(new_len > p->u.array.u1.size)) {
                        if (expand_fast_array(ctx, p, new_len))
                            return MBJS_EXCEPTION;
                    }
                    for(i = 0; i < argc; i++) {
                        p->u.array.u.values[array_len + i] = mbjs_dup(argv[i]);
                    }
                    p->u.array.count = new_len;
                    p->prop[0].u.value = mbjs_uint32(new_len);
                    return mbjs_int32(new_len);
                }
            }
        }
    }

    obj = MBJS_ToObject(ctx, this_val);
    if (mbjs_get_length64(ctx, &len, obj))
        goto exception;
    newLen = len + argc;
    if (newLen > MAX_SAFE_INTEGER) {
        MBJS_ThrowTypeError(ctx, "Array loo long");
        goto exception;
    }
    from = len;
    if (unshift && argc > 0) {
        if (MBJS_CopySubArray(ctx, obj, argc, 0, len, -1))
            goto exception;
        from = 0;
    }
    for(i = 0; i < argc; i++) {
        if (MBJS_SetPropertyInt64(ctx, obj, from + i, mbjs_dup(argv[i])) < 0)
            goto exception;
    }
    if (MBJS_SetProperty(ctx, obj, MBJS_ATOM_length, mbjs_int64(newLen)) < 0)
        goto exception;

    MBJS_FreeValue(ctx, obj);
    return mbjs_int64(newLen);

 exception:
    MBJS_FreeValue(ctx, obj);
    return MBJS_EXCEPTION;
}

static MBJSValue mbjs_array_reverse(MBJSContext *ctx, MBJSValueConst this_val,
                                int argc, MBJSValueConst *argv)
{
    MBJSValue obj, lval, hval;
    MBJSValue *arrp;
    int64_t len, l, h;
    int l_present, h_present;
    uint32_t count32;

    lval = MBJS_UNDEFINED;
    obj = MBJS_ToObject(ctx, this_val);
    if (mbjs_get_length64(ctx, &len, obj))
        goto exception;

    /* Special case fast arrays */
    if (mbjs_get_fast_array(ctx, obj, &arrp, &count32) && count32 == len) {
        uint32_t ll, hh;

        if (count32 > 1) {
            for (ll = 0, hh = count32 - 1; ll < hh; ll++, hh--) {
                lval = arrp[ll];
                arrp[ll] = arrp[hh];
                arrp[hh] = lval;
            }
        }
        return obj;
    }

    for (l = 0, h = len - 1; l < h; l++, h--) {
        l_present = MBJS_TryGetPropertyInt64(ctx, obj, l, &lval);
        if (l_present < 0)
            goto exception;
        h_present = MBJS_TryGetPropertyInt64(ctx, obj, h, &hval);
        if (h_present < 0)
            goto exception;
        if (h_present) {
            if (MBJS_SetPropertyInt64(ctx, obj, l, hval) < 0)
                goto exception;

            if (l_present) {
                if (MBJS_SetPropertyInt64(ctx, obj, h, lval) < 0) {
                    lval = MBJS_UNDEFINED;
                    goto exception;
                }
                lval = MBJS_UNDEFINED;
            } else {
                if (MBJS_DeletePropertyInt64(ctx, obj, h, MBJS_PROP_THROW) < 0)
                    goto exception;
            }
        } else {
            if (l_present) {
                if (MBJS_DeletePropertyInt64(ctx, obj, l, MBJS_PROP_THROW) < 0)
                    goto exception;
                if (MBJS_SetPropertyInt64(ctx, obj, h, lval) < 0) {
                    lval = MBJS_UNDEFINED;
                    goto exception;
                }
                lval = MBJS_UNDEFINED;
            }
        }
    }
    return obj;

 exception:
    MBJS_FreeValue(ctx, lval);
    MBJS_FreeValue(ctx, obj);
    return MBJS_EXCEPTION;
}

// Note: a.toReversed() is a.slice().reverse() with the twist that a.slice()
// leaves holes in sparse arrays intact whereas a.toReversed() replaces them
// with undefined, thus in effect creating a dense array.
// Does not use Array[@@species], always returns a base Array.
static MBJSValue mbjs_array_toReversed(MBJSContext *ctx, MBJSValueConst this_val,
                                   int argc, MBJSValueConst *argv)
{
    MBJSValue arr, obj, ret, *arrp, *pval;
    MBJSObject *p;
    int64_t i, len;
    uint32_t count32;

    ret = MBJS_EXCEPTION;
    arr = MBJS_UNDEFINED;
    obj = MBJS_ToObject(ctx, this_val);
    if (mbjs_get_length64(ctx, &len, obj))
        goto exception;

    arr = mbjs_allocate_fast_array(ctx, len);
    if (MBJS_IsException(arr))
        goto exception;

    if (len > 0) {
        p = MBJS_VALUE_GET_OBJ(arr);

        i = len - 1;
        pval = p->u.array.u.values;
        if (mbjs_get_fast_array(ctx, obj, &arrp, &count32) && count32 == len) {
            for (; i >= 0; i--, pval++)
                *pval = mbjs_dup(arrp[i]);
        } else {
            // Query order is observable; test262 expects descending order.
            for (; i >= 0; i--, pval++) {
                if (-1 == MBJS_TryGetPropertyInt64(ctx, obj, i, pval))
                    goto exception;
            }
        }
    }

    ret = arr;
    arr = MBJS_UNDEFINED;

exception:
    MBJS_FreeValue(ctx, arr);
    MBJS_FreeValue(ctx, obj);
    return ret;
}

static MBJSValue mbjs_array_slice(MBJSContext *ctx, MBJSValueConst this_val,
                              int argc, MBJSValueConst *argv, int splice)
{
    MBJSValue obj, arr, val, len_val;
    int64_t len, start, k, final, n, count, del_count, new_len;
    int kPresent;
    MBJSValue *arrp;
    uint32_t count32, i, item_count;

    arr = MBJS_UNDEFINED;
    obj = MBJS_ToObject(ctx, this_val);
    if (mbjs_get_length64(ctx, &len, obj))
        goto exception;

    if (MBJS_ToInt64Clamp(ctx, &start, argv[0], 0, len, len))
        goto exception;

    if (splice) {
        if (argc == 0) {
            item_count = 0;
            del_count = 0;
        } else if (argc == 1) {
            item_count = 0;
            del_count = len - start;
        } else {
            item_count = argc - 2;
            if (MBJS_ToInt64Clamp(ctx, &del_count, argv[1], 0, len - start, 0))
                goto exception;
        }
        if (len + item_count - del_count > MAX_SAFE_INTEGER) {
            MBJS_ThrowTypeError(ctx, "Array loo long");
            goto exception;
        }
        count = del_count;
    } else {
        item_count = 0; /* avoid warning */
        final = len;
        if (!MBJS_IsUndefined(argv[1])) {
            if (MBJS_ToInt64Clamp(ctx, &final, argv[1], 0, len, len))
                goto exception;
        }
        count = max_int64(final - start, 0);
    }
    len_val = mbjs_int64(count);
    arr = MBJS_ArraySpeciesCreate(ctx, obj, len_val);
    MBJS_FreeValue(ctx, len_val);
    if (MBJS_IsException(arr))
        goto exception;

    k = start;
    final = start + count;
    n = 0;
    /* The fast array test on arr ensures that
       MBJS_CreateDataPropertyUint32() won't modify obj in case arr is
       an exotic object */
    /* Special case fast arrays */
    if (mbjs_get_fast_array(ctx, obj, &arrp, &count32) &&
        mbjs_is_fast_array(ctx, arr)) {
        /* XXX: should share code with fast array constructor */
        for (; k < final && k < count32; k++, n++) {
            if (MBJS_CreateDataPropertyUint32Const(ctx, arr, n, arrp[k], MBJS_PROP_THROW) < 0)
                goto exception;
        }
    }
    /* Copy the remaining elements if any (handle case of inherited properties) */
    for (; k < final; k++, n++) {
        kPresent = MBJS_TryGetPropertyInt64(ctx, obj, k, &val);
        if (kPresent < 0)
            goto exception;
        if (kPresent) {
            if (MBJS_CreateDataPropertyUint32(ctx, arr, n, val, MBJS_PROP_THROW) < 0)
                goto exception;
        }
    }
    if (MBJS_SetProperty(ctx, arr, MBJS_ATOM_length, mbjs_int64(n)) < 0)
        goto exception;

    if (splice) {
        new_len = len + item_count - del_count;
        if (item_count != del_count) {
            if (MBJS_CopySubArray(ctx, obj, start + item_count,
                                start + del_count, len - (start + del_count),
                                item_count <= del_count ? +1 : -1) < 0)
                goto exception;

            for (k = len; k-- > new_len; ) {
                if (MBJS_DeletePropertyInt64(ctx, obj, k, MBJS_PROP_THROW) < 0)
                    goto exception;
            }
        }
        for (i = 0; i < item_count; i++) {
            if (MBJS_SetPropertyInt64(ctx, obj, start + i, mbjs_dup(argv[i + 2])) < 0)
                goto exception;
        }
        if (MBJS_SetProperty(ctx, obj, MBJS_ATOM_length, mbjs_int64(new_len)) < 0)
            goto exception;
    }
    MBJS_FreeValue(ctx, obj);
    return arr;

 exception:
    MBJS_FreeValue(ctx, obj);
    MBJS_FreeValue(ctx, arr);
    return MBJS_EXCEPTION;
}

static MBJSValue mbjs_array_toSpliced(MBJSContext *ctx, MBJSValueConst this_val,
                                  int argc, MBJSValueConst *argv)
{
    MBJSValue arr, obj, ret, *arrp, *pval, *last;
    MBJSObject *p;
    int64_t i, j, len, newlen, start, add, del;
    uint32_t count32;

    ret = MBJS_EXCEPTION;
    arr = MBJS_UNDEFINED;

    obj = MBJS_ToObject(ctx, this_val);
    if (mbjs_get_length64(ctx, &len, obj))
        goto exception;

    start = 0;
    if (argc > 0)
        if (MBJS_ToInt64Clamp(ctx, &start, argv[0], 0, len, len))
            goto exception;

    del = 0;
    if (argc > 0)
        del = len - start;
    if (argc > 1)
        if (MBJS_ToInt64Clamp(ctx, &del, argv[1], 0, del, 0))
            goto exception;

    add = 0;
    if (argc > 2)
        add = argc - 2;

    newlen = len + add - del;
    if (newlen > MAX_SAFE_INTEGER) {
        MBJS_ThrowTypeError(ctx, "invalid array length");
        goto exception;
    }

    arr = mbjs_allocate_fast_array(ctx, newlen);
    if (MBJS_IsException(arr))
        goto exception;

    if (newlen <= 0)
        goto done;

    p = MBJS_VALUE_GET_OBJ(arr);
    pval = &p->u.array.u.values[0];
    last = &p->u.array.u.values[newlen];

    if (mbjs_get_fast_array(ctx, obj, &arrp, &count32) && count32 == len) {
        for (i = 0; i < start; i++, pval++)
            *pval = mbjs_dup(arrp[i]);
        for (j = 0; j < add; j++, pval++)
            *pval = mbjs_dup(argv[2 + j]);
        for (i += del; i < len; i++, pval++)
            *pval = mbjs_dup(arrp[i]);
    } else {
        for (i = 0; i < start; i++, pval++)
            if (-1 == MBJS_TryGetPropertyInt64(ctx, obj, i, pval))
                goto exception;
        for (j = 0; j < add; j++, pval++)
            *pval = mbjs_dup(argv[2 + j]);
        for (i += del; i < len; i++, pval++)
            if (-1 == MBJS_TryGetPropertyInt64(ctx, obj, i, pval))
                goto exception;
    }

    assert(pval == last);

done:
    ret = arr;
    arr = MBJS_UNDEFINED;

exception:
    MBJS_FreeValue(ctx, arr);
    MBJS_FreeValue(ctx, obj);
    return ret;
}

static MBJSValue mbjs_array_copyWithin(MBJSContext *ctx, MBJSValueConst this_val,
                                   int argc, MBJSValueConst *argv)
{
    MBJSValue obj;
    int64_t len, from, to, final, count;

    obj = MBJS_ToObject(ctx, this_val);
    if (mbjs_get_length64(ctx, &len, obj))
        goto exception;

    if (MBJS_ToInt64Clamp(ctx, &to, argv[0], 0, len, len))
        goto exception;

    if (MBJS_ToInt64Clamp(ctx, &from, argv[1], 0, len, len))
        goto exception;

    final = len;
    if (argc > 2 && !MBJS_IsUndefined(argv[2])) {
        if (MBJS_ToInt64Clamp(ctx, &final, argv[2], 0, len, len))
            goto exception;
    }

    count = min_int64(final - from, len - to);

    if (MBJS_CopySubArray(ctx, obj, to, from, count,
                        (from < to && to < from + count) ? -1 : +1))
        goto exception;

    return obj;

 exception:
    MBJS_FreeValue(ctx, obj);
    return MBJS_EXCEPTION;
}

static int64_t MBJS_FlattenIntoArray(MBJSContext *ctx, MBJSValueConst target,
                                   MBJSValueConst source, int64_t sourceLen,
                                   int64_t targetIndex, int depth,
                                   MBJSValueConst mapperFunction,
                                   MBJSValueConst thisArg)
{
    MBJSValue element;
    int64_t sourceIndex, elementLen;
    int present, is_array;

    if (mbjs_check_stack_overflow(ctx->rt, 0)) {
        MBJS_ThrowStackOverflow(ctx);
        return -1;
    }

    for (sourceIndex = 0; sourceIndex < sourceLen; sourceIndex++) {
        present = MBJS_TryGetPropertyInt64(ctx, source, sourceIndex, &element);
        if (present < 0)
            return -1;
        if (!present)
            continue;
        if (!MBJS_IsUndefined(mapperFunction)) {
            MBJSValue index = mbjs_int64(sourceIndex);
            MBJSValueConst args[3] = { element, index, source };
            MBJSValue ret = MBJS_Call(ctx, mapperFunction, thisArg, 3, args);
            MBJS_FreeValue(ctx, element);
            MBJS_FreeValue(ctx, index);
            if (MBJS_IsException(ret))
                return -1;
            element = ret;
        }
        if (depth > 0) {
            is_array = mbjs_is_array(ctx, element);
            if (is_array < 0)
                goto fail;
            if (is_array) {
                if (mbjs_get_length64(ctx, &elementLen, element) < 0)
                    goto fail;
                targetIndex = MBJS_FlattenIntoArray(ctx, target, element,
                                                  elementLen, targetIndex,
                                                  depth - 1,
                                                  MBJS_UNDEFINED, MBJS_UNDEFINED);
                if (targetIndex < 0)
                    goto fail;
                MBJS_FreeValue(ctx, element);
                continue;
            }
        }
        if (targetIndex >= MAX_SAFE_INTEGER) {
            MBJS_ThrowTypeError(ctx, "Array too long");
            goto fail;
        }
        if (MBJS_DefinePropertyValueInt64(ctx, target, targetIndex, element,
                                        MBJS_PROP_C_W_E | MBJS_PROP_THROW) < 0)
            return -1;
        targetIndex++;
    }
    return targetIndex;

fail:
    MBJS_FreeValue(ctx, element);
    return -1;
}

static MBJSValue mbjs_array_flatten(MBJSContext *ctx, MBJSValueConst this_val,
                                int argc, MBJSValueConst *argv, int map)
{
    MBJSValue obj, arr;
    MBJSValueConst mapperFunction, thisArg;
    int64_t sourceLen;
    int depthNum;

    arr = MBJS_UNDEFINED;
    obj = MBJS_ToObject(ctx, this_val);
    if (mbjs_get_length64(ctx, &sourceLen, obj))
        goto exception;

    depthNum = 1;
    mapperFunction = MBJS_UNDEFINED;
    thisArg = MBJS_UNDEFINED;
    if (map) {
        mapperFunction = argv[0];
        if (argc > 1) {
            thisArg = argv[1];
        }
        if (check_function(ctx, mapperFunction))
            goto exception;
    } else {
        if (argc > 0 && !MBJS_IsUndefined(argv[0])) {
            if (MBJS_ToInt32Sat(ctx, &depthNum, argv[0]) < 0)
                goto exception;
        }
    }
    arr = MBJS_ArraySpeciesCreate(ctx, obj, mbjs_int32(0));
    if (MBJS_IsException(arr))
        goto exception;
    if (MBJS_FlattenIntoArray(ctx, arr, obj, sourceLen, 0, depthNum,
                            mapperFunction, thisArg) < 0)
        goto exception;
    MBJS_FreeValue(ctx, obj);
    return arr;

exception:
    MBJS_FreeValue(ctx, obj);
    MBJS_FreeValue(ctx, arr);
    return MBJS_EXCEPTION;
}

/* Array sort */

typedef struct ValueSlot {
    MBJSValue val;
    MBJSString *str;
    int64_t pos;
} ValueSlot;

struct array_sort_context {
    MBJSContext *ctx;
    int exception;
    int has_method;
    MBJSValueConst method;
};

static int mbjs_array_cmp_generic(const void *a, const void *b, void *opaque) {
    struct array_sort_context *psc = opaque;
    MBJSContext *ctx = psc->ctx;
    MBJSValueConst argv[2];
    MBJSValue res;
    ValueSlot *ap = (ValueSlot *)(void *)a;
    ValueSlot *bp = (ValueSlot *)(void *)b;
    int cmp;

    if (psc->exception)
        return 0;

    if (psc->has_method) {
        argv[0] = ap->val;
        argv[1] = bp->val;
        res = MBJS_Call(ctx, psc->method, MBJS_UNDEFINED, 2, argv);
        if (MBJS_IsException(res))
            goto exception;
        if (MBJS_VALUE_GET_TAG(res) == MBJS_TAG_INT) {
            int val = MBJS_VALUE_GET_INT(res);
            cmp = (val > 0) - (val < 0);
        } else {
            double val;
            if (MBJS_ToFloat64Free(ctx, &val, res) < 0)
                goto exception;
            cmp = (val > 0) - (val < 0);
        }
    } else {
        /* Not supposed to bypass ToString even for identical objects as
         * tested in test262/test/built-ins/Array/prototype/sort/bug_596_1.js
         */
        if (!ap->str) {
            MBJSValue str = MBJS_ToString(ctx, ap->val);
            if (MBJS_IsException(str))
                goto exception;
            ap->str = MBJS_VALUE_GET_STRING(str);
        }
        if (!bp->str) {
            MBJSValue str = MBJS_ToString(ctx, bp->val);
            if (MBJS_IsException(str))
                goto exception;
            bp->str = MBJS_VALUE_GET_STRING(str);
        }
        cmp = mbjs_string_compare(ap->str, bp->str);
    }
    if (cmp != 0)
        return cmp;
    /* make sort stable: compare array offsets */
    return (ap->pos > bp->pos) - (ap->pos < bp->pos);

exception:
    psc->exception = 1;
    return 0;
}

static MBJSValue mbjs_array_sort(MBJSContext *ctx, MBJSValueConst this_val,
                             int argc, MBJSValueConst *argv)
{
    struct array_sort_context asc = { ctx, 0, 0, argv[0] };
    MBJSValue obj = MBJS_UNDEFINED;
    ValueSlot *array = NULL;
    size_t array_size = 0, pos = 0, n = 0;
    int64_t i, len, undefined_count = 0;
    int present;

    if (!MBJS_IsUndefined(asc.method)) {
        if (check_function(ctx, asc.method))
            goto exception;
        asc.has_method = 1;
    }
    obj = MBJS_ToObject(ctx, this_val);
    if (mbjs_get_length64(ctx, &len, obj))
        goto exception;

    /* XXX: should special case fast arrays */
    for (i = 0; i < len; i++) {
        if (pos >= array_size) {
            size_t new_size;
            ValueSlot *new_array;
            new_size = (array_size + (array_size >> 1) + 31) & ~15;
            new_array = mbjs_realloc(ctx, array, new_size * sizeof(*array));
            if (new_array == NULL)
                goto exception;
            array = new_array;
            array_size = new_size;
        }
        present = MBJS_TryGetPropertyInt64(ctx, obj, i, &array[pos].val);
        if (present < 0)
            goto exception;
        if (present == 0)
            continue;
        if (MBJS_IsUndefined(array[pos].val)) {
            undefined_count++;
            continue;
        }
        array[pos].str = NULL;
        array[pos].pos = i;
        pos++;
    }
    rqsort(array, pos, sizeof(*array), mbjs_array_cmp_generic, &asc);
    if (asc.exception)
        goto exception;

    /* XXX: should special case fast arrays */
    while (n < pos) {
        if (array[n].str)
            MBJS_FreeValue(ctx, MBJS_MKPTR(MBJS_TAG_STRING, array[n].str));
        if (array[n].pos == n) {
            MBJS_FreeValue(ctx, array[n].val);
        } else {
            if (MBJS_SetPropertyInt64(ctx, obj, n, array[n].val) < 0) {
                n++;
                goto exception;
            }
        }
        n++;
    }
    mbjs_free(ctx, array);
    for (i = n; undefined_count-- > 0; i++) {
        if (MBJS_SetPropertyInt64(ctx, obj, i, MBJS_UNDEFINED) < 0)
            goto fail;
    }
    for (; i < len; i++) {
        if (MBJS_DeletePropertyInt64(ctx, obj, i, MBJS_PROP_THROW) < 0)
            goto fail;
    }
    return obj;

exception:
    for (; n < pos; n++) {
        MBJS_FreeValue(ctx, array[n].val);
        if (array[n].str)
            MBJS_FreeValue(ctx, MBJS_MKPTR(MBJS_TAG_STRING, array[n].str));
    }
    mbjs_free(ctx, array);
fail:
    MBJS_FreeValue(ctx, obj);
    return MBJS_EXCEPTION;
}

// Note: a.toSorted() is a.slice().sort() with the twist that a.slice()
// leaves holes in sparse arrays intact whereas a.toSorted() replaces them
// with undefined, thus in effect creating a dense array.
// Does not use Array[@@species], always returns a base Array.
static MBJSValue mbjs_array_toSorted(MBJSContext *ctx, MBJSValueConst this_val,
                                 int argc, MBJSValueConst *argv)
{
    MBJSValue arr, obj, ret, *arrp, *pval;
    MBJSObject *p;
    int64_t i, len;
    uint32_t count32;

    if (!MBJS_IsUndefined(argv[0]))
        if (check_function(ctx, argv[0]))
            return MBJS_EXCEPTION;

    ret = MBJS_EXCEPTION;
    arr = MBJS_UNDEFINED;
    obj = MBJS_ToObject(ctx, this_val);
    if (mbjs_get_length64(ctx, &len, obj))
        goto exception;

    arr = mbjs_allocate_fast_array(ctx, len);
    if (MBJS_IsException(arr))
        goto exception;

    if (len > 0) {
        p = MBJS_VALUE_GET_OBJ(arr);
        i = 0;
        pval = p->u.array.u.values;
        if (mbjs_get_fast_array(ctx, obj, &arrp, &count32) && count32 == len) {
            for (; i < len; i++, pval++)
                *pval = mbjs_dup(arrp[i]);
        } else {
            for (; i < len; i++, pval++) {
                if (-1 == MBJS_TryGetPropertyInt64(ctx, obj, i, pval))
                    goto exception;
            }
        }
    }

    ret = mbjs_array_sort(ctx, arr, argc, argv);
    if (MBJS_IsException(ret))
        goto exception;
    MBJS_FreeValue(ctx, ret);

    ret = arr;
    arr = MBJS_UNDEFINED;

exception:
    MBJS_FreeValue(ctx, arr);
    MBJS_FreeValue(ctx, obj);
    return ret;
}

typedef struct MBJSArrayIteratorData {
    MBJSValue obj;
    MBJSIteratorKindEnum kind;
    uint32_t idx;
} MBJSArrayIteratorData;

static void mbjs_array_iterator_finalizer(MBJSRuntime *rt, MBJSValueConst val)
{
    MBJSObject *p = MBJS_VALUE_GET_OBJ(val);
    MBJSArrayIteratorData *it = p->u.array_iterator_data;
    if (it) {
        MBJS_FreeValueRT(rt, it->obj);
        mbjs_free_rt(rt, it);
    }
}

static void mbjs_array_iterator_mark(MBJSRuntime *rt, MBJSValueConst val,
                                   MBJS_MarkFunc *mark_func)
{
    MBJSObject *p = MBJS_VALUE_GET_OBJ(val);
    MBJSArrayIteratorData *it = p->u.array_iterator_data;
    if (it) {
        MBJS_MarkValue(rt, it->obj, mark_func);
    }
}

static MBJSValue mbjs_create_array(MBJSContext *ctx, int len, MBJSValueConst *tab)
{
    MBJSValue obj;
    MBJSObject *p;
    int i;

    obj = MBJS_NewArray(ctx);
    if (MBJS_IsException(obj))
        return MBJS_EXCEPTION;
    if (len > 0) {
        p = MBJS_VALUE_GET_OBJ(obj);
        if (expand_fast_array(ctx, p, len) < 0) {
            MBJS_FreeValue(ctx, obj);
            return MBJS_EXCEPTION;
        }
        p->u.array.count = len;
        for(i = 0; i < len; i++)
            p->u.array.u.values[i] = mbjs_dup(tab[i]);
        /* update the 'length' field */
        set_value(ctx, &p->prop[0].u.value, mbjs_int32(len));
    }
    return obj;
}

static MBJSValue mbjs_create_array_iterator(MBJSContext *ctx, MBJSValueConst this_val,
                                        int argc, MBJSValueConst *argv, int magic)
{
    MBJSValue enum_obj, arr;
    MBJSArrayIteratorData *it;
    MBJSIteratorKindEnum kind;
    int class_id;

    kind = magic & 3;
    if (magic & 4) {
        /* string iterator case */
        arr = MBJS_ToStringCheckObject(ctx, this_val);
        class_id = MBJS_CLASS_STRING_ITERATOR;
    } else {
        arr = MBJS_ToObject(ctx, this_val);
        class_id = MBJS_CLASS_ARRAY_ITERATOR;
    }
    if (MBJS_IsException(arr))
        goto fail;
    enum_obj = MBJS_NewObjectClass(ctx, class_id);
    if (MBJS_IsException(enum_obj))
        goto fail;
    it = mbjs_malloc(ctx, sizeof(*it));
    if (!it)
        goto fail1;
    it->obj = arr;
    it->kind = kind;
    it->idx = 0;
    MBJS_SetOpaqueInternal(enum_obj, it);
    return enum_obj;
 fail1:
    MBJS_FreeValue(ctx, enum_obj);
 fail:
    MBJS_FreeValue(ctx, arr);
    return MBJS_EXCEPTION;
}

static MBJSValue mbjs_array_iterator_next(MBJSContext *ctx, MBJSValueConst this_val,
                                      int argc, MBJSValueConst *argv,
                                      int *pdone, int magic)
{
    MBJSArrayIteratorData *it;
    uint32_t len, idx;
    MBJSValue val, obj;
    MBJSObject *p;

    it = MBJS_GetOpaque2(ctx, this_val, MBJS_CLASS_ARRAY_ITERATOR);
    if (!it)
        goto fail1;
    if (MBJS_IsUndefined(it->obj))
        goto done;
    p = MBJS_VALUE_GET_OBJ(it->obj);
    if (is_typed_array(p->class_id)) {
        if (typed_array_is_oob(p)) {
            MBJS_ThrowTypeErrorArrayBufferOOB(ctx);
            goto fail1;
        }
        len = p->u.array.count;
    } else {
        if (mbjs_get_length32(ctx, &len, it->obj)) {
        fail1:
            *pdone = false;
            return MBJS_EXCEPTION;
        }
    }
    idx = it->idx;
    if (idx >= len) {
        MBJS_FreeValue(ctx, it->obj);
        it->obj = MBJS_UNDEFINED;
    done:
        *pdone = true;
        return MBJS_UNDEFINED;
    }
    it->idx = idx + 1;
    *pdone = false;
    if (it->kind == MBJS_ITERATOR_KIND_KEY) {
        return mbjs_uint32(idx);
    } else {
        val = MBJS_GetPropertyUint32(ctx, it->obj, idx);
        if (MBJS_IsException(val))
            return MBJS_EXCEPTION;
        if (it->kind == MBJS_ITERATOR_KIND_VALUE) {
            return val;
        } else {
            MBJSValueConst args[2];
            MBJSValue num;
            num = mbjs_uint32(idx);
            args[0] = num;
            args[1] = val;
            obj = mbjs_create_array(ctx, 2, args);
            MBJS_FreeValue(ctx, val);
            MBJS_FreeValue(ctx, num);
            return obj;
        }
    }
}

typedef struct MBJSIteratorWrapData {
    MBJSValue wrapped_iter;
    MBJSValue wrapped_next;
} MBJSIteratorWrapData;

static void mbjs_iterator_wrap_finalizer(MBJSRuntime *rt, MBJSValueConst val)
{
    MBJSObject *p = MBJS_VALUE_GET_OBJ(val);
    MBJSIteratorWrapData *it = p->u.iterator_wrap_data;
    if (it) {
        MBJS_FreeValueRT(rt, it->wrapped_iter);
        MBJS_FreeValueRT(rt, it->wrapped_next);
        mbjs_free_rt(rt, it);
    }
}

static void mbjs_iterator_wrap_mark(MBJSRuntime *rt, MBJSValueConst val,
                                  MBJS_MarkFunc *mark_func)
{
    MBJSObject *p = MBJS_VALUE_GET_OBJ(val);
    MBJSIteratorWrapData *it = p->u.iterator_wrap_data;
    if (it) {
        MBJS_MarkValue(rt, it->wrapped_iter, mark_func);
        MBJS_MarkValue(rt, it->wrapped_next, mark_func);
    }
}

static MBJSValue mbjs_iterator_wrap_next(MBJSContext *ctx, MBJSValueConst this_val,
                                     int argc, MBJSValueConst *argv,
                                     int *pdone, int magic)
{
    MBJSIteratorWrapData *it;
    MBJSValue method, ret;
    it = MBJS_GetOpaque2(ctx, this_val, MBJS_CLASS_ITERATOR_WRAP);
    if (!it)
        return MBJS_EXCEPTION;
    if (magic == GEN_MAGIC_NEXT)
        return MBJS_IteratorNext(ctx, it->wrapped_iter, it->wrapped_next, argc, argv, pdone);
    method = MBJS_GetProperty(ctx, it->wrapped_iter, MBJS_ATOM_return);
    if (MBJS_IsException(method))
        return MBJS_EXCEPTION;
    if (MBJS_IsNull(method) || MBJS_IsUndefined(method)) {
        *pdone = true;
        return MBJS_UNDEFINED;
    }
    ret = MBJS_IteratorNext2(ctx, it->wrapped_iter, method, argc, argv, pdone);
    MBJS_FreeValue(ctx, method);
    return ret;
}

static const MBJSCFunctionListEntry mbjs_iterator_wrap_proto_funcs[] = {
    MBJS_ITERATOR_NEXT_DEF("next", 0, mbjs_iterator_wrap_next, GEN_MAGIC_NEXT ),
    MBJS_ITERATOR_NEXT_DEF("return", 0, mbjs_iterator_wrap_next, GEN_MAGIC_RETURN ),
};

static int check_iterator(MBJSContext *ctx, MBJSValueConst obj);

static MBJSValue mbjs_iterator_constructor_getset(MBJSContext *ctx,
                                              MBJSValueConst this_val,
                                              int argc, MBJSValueConst *argv,
                                              int magic,
                                              MBJSValueConst *func_data)
{
    int ret;

    if (magic) { // setter (the getter is registered with magic == 0)
        // SetterThatIgnoresPrototypeProperties(%Iterator.prototype%, "constructor", v)
        // argv[0] is the assigned value; it defaults to undefined because the
        // setter is registered with length 1 (see MBJS_AddIntrinsicBaseObjects).
        if (check_iterator(ctx, this_val) < 0)
            return MBJS_EXCEPTION;
        if (mbjs_same_value(ctx, this_val, ctx->class_proto[MBJS_CLASS_ITERATOR]))
            return MBJS_ThrowTypeError(ctx, "Cannot assign to read only property");
        ret = MBJS_GetOwnProperty(ctx, NULL, this_val, MBJS_ATOM_constructor);
        if (ret < 0)
            return MBJS_EXCEPTION;
        if (ret) {
            if (MBJS_SetProperty(ctx, this_val, MBJS_ATOM_constructor, mbjs_dup(argv[0])) < 0)
                return MBJS_EXCEPTION;
        } else {
            if (MBJS_DefinePropertyValue(ctx, this_val, MBJS_ATOM_constructor,
                                       mbjs_dup(argv[0]),
                                       MBJS_PROP_C_W_E | MBJS_PROP_THROW) < 0)
                return MBJS_EXCEPTION;
        }
        return MBJS_UNDEFINED;
    }
    return mbjs_dup(func_data[0]);
}

static MBJSValue mbjs_iterator_constructor(MBJSContext *ctx, MBJSValueConst new_target,
                                       int argc, MBJSValueConst *argv)
{
    MBJSObject *p;

    if (MBJS_TAG_OBJECT != MBJS_VALUE_GET_TAG(new_target))
        return MBJS_ThrowTypeError(ctx, "constructor requires 'new'");
    p = MBJS_VALUE_GET_OBJ(new_target);
    if (p->class_id == MBJS_CLASS_C_FUNCTION)
        if (p->u.cfunc.c_function.generic == mbjs_iterator_constructor)
            return MBJS_ThrowTypeError(ctx, "abstract class not constructable");
    return mbjs_create_from_ctor(ctx, new_target, MBJS_CLASS_ITERATOR);
}

typedef struct MBJSIteratorConcatData {
    uint32_t index : 31; // elements (not pairs!) in values[] array
    uint32_t done : 1;
    uint32_t count : 31;
    uint32_t running : 1;
    MBJSValue iter, next, values[]; // array of (object, method) pairs
} MBJSIteratorConcatData;

static void mbjs_iterator_concat_finalizer(MBJSRuntime *rt, MBJSValueConst val)
{
    MBJSObject *p = MBJS_VALUE_GET_OBJ(val);
    MBJSIteratorConcatData *it = p->u.iterator_concat_data;
    if (it) {
        MBJS_FreeValueRT(rt, it->iter);
        MBJS_FreeValueRT(rt, it->next);
        for (uint32_t i = it->index; i < it->count; i++)
            MBJS_FreeValueRT(rt, it->values[i]);
        mbjs_free_rt(rt, it);
    }
}

static void mbjs_iterator_concat_mark(MBJSRuntime *rt, MBJSValueConst val,
                                    MBJS_MarkFunc *mark_func)
{
    MBJSObject *p = MBJS_VALUE_GET_OBJ(val);
    MBJSIteratorConcatData *it = p->u.iterator_concat_data;
    if (it) {
        MBJS_MarkValue(rt, it->iter, mark_func);
        MBJS_MarkValue(rt, it->next, mark_func);
        for (uint32_t i = it->index; i < it->count; i++)
            MBJS_MarkValue(rt, it->values[i], mark_func);
    }
}

static MBJSValue mbjs_iterator_concat_next(MBJSContext *ctx, MBJSValueConst this_val,
                                       int argc, MBJSValueConst *argv,
                                       int *pdone, int magic)
{
    MBJSValue iter, item, next, val, *obj, *meth;
    MBJSIteratorConcatData *it;
    int done;

    it = MBJS_GetOpaque2(ctx, this_val, MBJS_CLASS_ITERATOR_CONCAT);
    if (!it)
        return MBJS_EXCEPTION;
    if (it->running)
        return MBJS_ThrowTypeError(ctx, "already running");
    if (it->done) {
        *pdone = true;
        return MBJS_UNDEFINED;
    }
    it->running = true;
next:
    if (it->index >= it->count) {
        *pdone = true;
        val = MBJS_UNDEFINED;
        goto done;
    }
    obj = &it->values[it->index + 0];
    meth = &it->values[it->index + 1];
    iter = it->iter;
    if (MBJS_IsUndefined(iter)) {
        iter = MBJS_GetIterator2(ctx, *obj, *meth);
        if (MBJS_IsException(iter))
            goto fail;
        it->iter = iter;
    }
    next = it->next;
    if (MBJS_IsUndefined(next)) {
        next = MBJS_GetProperty(ctx, iter, MBJS_ATOM_next);
        if (MBJS_IsException(next))
            goto fail;
        it->next = next;
    }
    item = MBJS_IteratorNext2(ctx, iter, next, 0, NULL, &done);
    if (MBJS_IsException(item))
        goto fail;
    if (!done) {
        *pdone = false;
        val = item;
        goto done;
    }
    // done==1 means really done, done==2 means "unknown, inspect object"
    if (done == 2) {
        val = MBJS_GetProperty(ctx, item, MBJS_ATOM_done);
        if (MBJS_IsException(val)) {
            MBJS_FreeValue(ctx, item);
            goto fail;
        }
        done = MBJS_ToBoolFree(ctx, val);
    }
    if (done) {
        MBJS_FreeValue(ctx, item);
        MBJS_FreeValue(ctx, iter);
        MBJS_FreeValue(ctx, next);
        it->iter = MBJS_UNDEFINED;
        it->next = MBJS_UNDEFINED;
        MBJS_FreeValue(ctx, *meth);
        MBJS_FreeValue(ctx, *obj);
        it->index += 2;
        goto next;
    }
    val = MBJS_GetProperty(ctx, item, MBJS_ATOM_value);
    MBJS_FreeValue(ctx, item);
    if (MBJS_IsException(val))
        goto fail;
    *pdone = false;
done:
    it->running = false;
    return val;
fail:
    /* an abrupt completion finishes the iterator */
    it->done = true;
    val = MBJS_EXCEPTION;
    goto done;
}

static MBJSValue mbjs_iterator_concat_return(MBJSContext *ctx, MBJSValueConst this_val,
                                         int argc, MBJSValueConst *argv,
                                         int *pdone, int magic)
{
    MBJSIteratorConcatData *it;
    MBJSValue *pval;
    int res;

    it = MBJS_GetOpaque2(ctx, this_val, MBJS_CLASS_ITERATOR_CONCAT);
    if (!it)
        return MBJS_EXCEPTION;
    if (it->running)
        return MBJS_ThrowTypeError(ctx, "already running");
    if (it->done) {
        /* a completed generator does not run IteratorClose */
        *pdone = true;
        return MBJS_UNDEFINED;
    }
    res = 0;
    if (!MBJS_IsUndefined(it->iter)) {
        /* IteratorClose: leaves the iterator alone when it has no .return
           method and rejects a result that is not an object */
        it->running = true;
        res = MBJS_IteratorClose(ctx, it->iter, /*is_exception_pending*/false);
        it->running = false;
    }
    /* the iterator is closed either way, the remaining iterables are never
       opened */
    while (it->index < it->count) {
        pval = &it->values[it->index++];
        MBJS_FreeValue(ctx, *pval);
        *pval = MBJS_UNDEFINED;
    }
    MBJS_FreeValue(ctx, it->iter);
    MBJS_FreeValue(ctx, it->next);
    it->iter = MBJS_UNDEFINED;
    it->next = MBJS_UNDEFINED;
    it->done = true;
    *pdone = true;
    if (res < 0)
        return MBJS_EXCEPTION;
    return MBJS_UNDEFINED;
}

static MBJSValue mbjs_iterator_concat(MBJSContext *ctx, MBJSValueConst this_val,
                                  int argc, MBJSValueConst *argv)
{
    MBJSIteratorConcatData *it;
    MBJSValue obj, method;

    it = mbjs_malloc(ctx, sizeof(*it) + 2*argc * sizeof(it->values[0]));
    if (!it)
        return MBJS_EXCEPTION;
    it->running = false;
    it->done = false;
    it->index = 0;
    it->count = 0;
    it->iter = MBJS_UNDEFINED;
    it->next = MBJS_UNDEFINED;
    for (int i = 0; i < argc; i++) {
        MBJSValueConst obj = argv[i];
        /* GetIteratorFlattenable: strings are iterable primitives and are
           accepted (V8-compatible); any other non-object is an error. */
        if (!MBJS_IsObject(obj) && !MBJS_IsString(obj)) {
            MBJS_ThrowTypeErrorNotAnObject(ctx);
            goto fail;
        }
        method = MBJS_GetProperty(ctx, obj, MBJS_ATOM_Symbol_iterator);
        if (MBJS_IsException(method))
            goto fail;
        if (!MBJS_IsFunction(ctx, method)) {
            MBJS_ThrowTypeErrorNotAFunction(ctx);
            MBJS_FreeValue(ctx, method);
            goto fail;
        }
        it->values[it->count++] = mbjs_dup(obj);
        it->values[it->count++] = method;
    }
    obj = MBJS_NewObjectClass(ctx, MBJS_CLASS_ITERATOR_CONCAT);
    if (MBJS_IsException(obj))
        goto fail;
    MBJS_SetOpaqueInternal(obj, it);
    return obj;
fail:
    for (uint32_t i = 0; i < it->count; i++)
        MBJS_FreeValue(ctx, it->values[i]);
    mbjs_free(ctx, it);
    return MBJS_EXCEPTION;
}

static MBJSValue mbjs_iterator_from(MBJSContext *ctx, MBJSValueConst this_val,
                                int argc, MBJSValueConst *argv)
{
    MBJSValue method, iter, next, wrapper;
    MBJSIteratorWrapData *it;
    int ret;

    MBJSValueConst obj = argv[0];
    if (!MBJS_IsObject(obj) && !MBJS_IsString(obj))
        return MBJS_ThrowTypeError(ctx, "Iterator.from called on non-object");
    method = MBJS_GetProperty(ctx, obj, MBJS_ATOM_Symbol_iterator);
    if (MBJS_IsException(method))
        return MBJS_EXCEPTION;
    if (MBJS_IsNull(method) || MBJS_IsUndefined(method)) {
        iter = mbjs_dup(obj);
    } else {
        iter = MBJS_GetIterator2(ctx, obj, method);
    }
    MBJS_FreeValue(ctx, method);
    if (MBJS_IsException(iter))
        return MBJS_EXCEPTION;
    if (!MBJS_IsObject(iter)) {
        MBJS_FreeValue(ctx, iter);
        return MBJS_ThrowTypeErrorNotAnObject(ctx);
    }

    /* GetIteratorDirect */
    next = MBJS_GetProperty(ctx, iter, MBJS_ATOM_next);
    if (MBJS_IsException(next)) {
        MBJS_FreeValue(ctx, iter);
        return MBJS_EXCEPTION;
    }
    ret = MBJS_OrdinaryIsInstanceOf(ctx, iter, ctx->iterator_ctor);
    if (ret < 0)
        goto fail;
    if (ret) {
        MBJS_FreeValue(ctx, next);
        return iter;
    }

    wrapper = MBJS_NewObjectClass(ctx, MBJS_CLASS_ITERATOR_WRAP);
    if (MBJS_IsException(wrapper))
        goto fail;
    it = mbjs_malloc(ctx, sizeof(*it));
    if (!it) {
        MBJS_FreeValue(ctx, wrapper);
        goto fail;
    }
    it->wrapped_iter = iter;
    it->wrapped_next = next;
    MBJS_SetOpaqueInternal(wrapper, it);
    return wrapper;
fail:
    MBJS_FreeValue(ctx, iter);
    MBJS_FreeValue(ctx, next);
    return MBJS_EXCEPTION;
}

static int check_iterator(MBJSContext *ctx, MBJSValueConst obj)
{
    if (!MBJS_IsObject(obj)) {
        MBJS_ThrowTypeErrorNotAnObject(ctx);
        return -1;
    }
    return 0;
}

typedef struct MBJSIteratorHelperData {
    MBJSValue obj;
    MBJSValue next;
    MBJSValue func; // predicate (filter) or mapper (flatMap, map)
    MBJSValue inner; // innerValue (flatMap)
    MBJSValue *buf; // buffered values (chunks, windows)
    int64_t count; // limit (drop, take), counter (filter, map, flatMap) or
                   // chunk/window size (chunks, windows)
    int buf_count; // number of values in |buf|
    int buf_size; // allocated size of |buf|
    MBJSIteratorHelperKindEnum kind : 8;
    uint8_t executing : 1;
    uint8_t done : 1;
    uint8_t allow_partial : 1; // yield a partial final window (windows)
} MBJSIteratorHelperData;

static MBJSValue mbjs_create_iterator_helper(MBJSContext *ctx, MBJSValueConst this_val,
                                         int argc, MBJSValueConst *argv, int magic)
{
    MBJSValueConst func;
    MBJSValue obj, method;
    int64_t count;
    bool allow_partial;
    MBJSIteratorHelperData *it;

    if (check_iterator(ctx, this_val) < 0)
        return MBJS_EXCEPTION;
    func = MBJS_UNDEFINED;
    count = 0;
    allow_partial = false;

    switch(magic) {
    case MBJS_ITERATOR_HELPER_KIND_CHUNKS:
    case MBJS_ITERATOR_HELPER_KIND_WINDOWS:
        {
            const char *name;
            double d;
            bool ok;

            name = magic == MBJS_ITERATOR_HELPER_KIND_CHUNKS ? "chunkSize"
                                                           : "windowSize";
            // note: no coercion, the argument must be an integral number
            d = NAN;
            if (MBJS_IsNumber(argv[0]) && MBJS_ToFloat64(ctx, &d, argv[0]))
                goto fail;
            if (!isfinite(d) || trunc(d) != d) {
                MBJS_ThrowTypeError(ctx, "%s is not an integral number", name);
                goto fail;
            }
            if (d < 1 || d > UINT32_MAX) {
                MBJS_ThrowRangeError(ctx, "%s out of range", name);
                goto fail;
            }
            count = (int64_t)d;
            if (magic == MBJS_ITERATOR_HELPER_KIND_WINDOWS && argc > 1 &&
                !MBJS_IsUndefined(argv[1])) {
                ok = false;
                if (MBJS_IsString(argv[1])) {
                    const char *str = MBJS_ToCString(ctx, argv[1]);
                    if (!str)
                        goto fail;
                    allow_partial = !strcmp(str, "allow-partial");
                    ok = allow_partial || !strcmp(str, "only-full");
                    MBJS_FreeCString(ctx, str);
                }
                if (!ok) {
                    MBJS_ThrowTypeError(ctx, "bad undersized option");
                    goto fail;
                }
            }
        }
        break;
    case MBJS_ITERATOR_HELPER_KIND_DROP:
    case MBJS_ITERATOR_HELPER_KIND_TAKE:
        {
            MBJSValue v;
            double dlimit;
            v = MBJS_ToNumber(ctx, argv[0]);
            if (MBJS_IsException(v))
                goto fail;
            MBJS_ToFloat64Free(ctx, &dlimit, v);
            if (isnan(dlimit))
                goto range_error;
            if (isfinite(dlimit) && dlimit > MAX_SAFE_INTEGER)
                goto range_error;
            dlimit = trunc(dlimit);
            if (dlimit < 0)
                goto range_error;
            // +Infinity means "no limit"; use MAX_SAFE_INTEGER
            count = isfinite(dlimit) ? (int64_t)dlimit : MAX_SAFE_INTEGER;
        }
        break;
    case MBJS_ITERATOR_HELPER_KIND_FILTER:
    case MBJS_ITERATOR_HELPER_KIND_FLAT_MAP:
    case MBJS_ITERATOR_HELPER_KIND_MAP:
        {
            func = argv[0];
            if (check_function(ctx, func))
                goto fail;
        }
        break;
    default:
        abort();
        break;
    }

    /* GetIteratorDirect: an exception here propagates as is, the iterator
       object is only closed for a bad argument */
    method = MBJS_GetProperty(ctx, this_val, MBJS_ATOM_next);
    if (MBJS_IsException(method))
        return MBJS_EXCEPTION;
    obj = MBJS_NewObjectClass(ctx, MBJS_CLASS_ITERATOR_HELPER);
    if (MBJS_IsException(obj)) {
        MBJS_FreeValue(ctx, method);
        goto fail;
    }
    it = mbjs_malloc(ctx, sizeof(*it));
    if (!it) {
        MBJS_FreeValue(ctx, obj);
        MBJS_FreeValue(ctx, method);
        goto fail;
    }
    it->kind = magic;
    it->obj = mbjs_dup(this_val);
    it->func = mbjs_dup(func);
    it->next = method;
    it->inner = MBJS_UNDEFINED;
    it->buf = NULL;
    it->count = count;
    it->buf_count = 0;
    it->buf_size = 0;
    it->executing = 0;
    it->done = 0;
    it->allow_partial = allow_partial;
    MBJS_SetOpaqueInternal(obj, it);
    return obj;
range_error:
    MBJS_ThrowRangeError(ctx, "must be positive");
fail:
    MBJS_IteratorClose(ctx, this_val, true);
    return MBJS_EXCEPTION;
}

static MBJSValue mbjs_iterator_proto_func(MBJSContext *ctx, MBJSValueConst this_val,
                                      int argc, MBJSValueConst *argv, int magic)
{
    MBJSValue item, method, ret, func, index_val, r;
    MBJSValueConst args[2];
    int64_t idx;
    int done;

    if (check_iterator(ctx, this_val) < 0)
        return MBJS_EXCEPTION;
    func = MBJS_UNDEFINED;
    method = MBJS_UNDEFINED;
    if (check_function(ctx, argv[0]))
        goto fail;
    func = mbjs_dup(argv[0]);
    /* GetIteratorDirect: propagates as is, no IteratorClose */
    method = MBJS_GetProperty(ctx, this_val, MBJS_ATOM_next);
    if (MBJS_IsException(method))
        goto step_fail;

    r = MBJS_UNDEFINED;

    switch(magic) {
    case MBJS_ITERATOR_HELPER_KIND_EVERY:
        {
            r = MBJS_TRUE;
            for (idx = 0; /*empty*/; idx++) {
                item = MBJS_IteratorNext(ctx, this_val, method, 0, NULL, &done);
                if (MBJS_IsException(item))
                    goto step_fail;
                if (done)
                    break;
                index_val = mbjs_int64(idx);
                args[0] = item;
                args[1] = index_val;
                ret = MBJS_Call(ctx, func, MBJS_UNDEFINED, countof(args), args);
                MBJS_FreeValue(ctx, item);
                MBJS_FreeValue(ctx, index_val);
                if (MBJS_IsException(ret))
                    goto fail;
                if (!MBJS_ToBoolFree(ctx, ret)) {
                    if (MBJS_IteratorClose(ctx, this_val, false) < 0)
                        r = MBJS_EXCEPTION;
                    else
                        r = MBJS_FALSE;
                    break;
                }
                index_val = MBJS_UNDEFINED;
                ret = MBJS_UNDEFINED;
                item = MBJS_UNDEFINED;
            }
        }
        break;
    case MBJS_ITERATOR_HELPER_KIND_FIND:
        {
            for (idx = 0; /*empty*/; idx++) {
                item = MBJS_IteratorNext(ctx, this_val, method, 0, NULL, &done);
                if (MBJS_IsException(item))
                    goto step_fail;
                if (done)
                    break;
                index_val = mbjs_int64(idx);
                args[0] = item;
                args[1] = index_val;
                ret = MBJS_Call(ctx, func, MBJS_UNDEFINED, countof(args), args);
                MBJS_FreeValue(ctx, index_val);
                if (MBJS_IsException(ret)) {
                    MBJS_FreeValue(ctx, item);
                    goto fail;
                }
                if (MBJS_ToBoolFree(ctx, ret)) {
                    if (MBJS_IteratorClose(ctx, this_val, false) < 0) {
                        MBJS_FreeValue(ctx, item);
                        r = MBJS_EXCEPTION;
                    } else {
                        r = item;
                    }
                    break;
                }
                MBJS_FreeValue(ctx, item);
                index_val = MBJS_UNDEFINED;
                ret = MBJS_UNDEFINED;
                item = MBJS_UNDEFINED;
            }
        }
        break;
    case MBJS_ITERATOR_HELPER_KIND_FOR_EACH:
        {
            for (idx = 0; /*empty*/; idx++) {
                item = MBJS_IteratorNext(ctx, this_val, method, 0, NULL, &done);
                if (MBJS_IsException(item))
                    goto step_fail;
                if (done)
                    break;
                index_val = mbjs_int64(idx);
                args[0] = item;
                args[1] = index_val;
                ret = MBJS_Call(ctx, func, MBJS_UNDEFINED, countof(args), args);
                MBJS_FreeValue(ctx, item);
                MBJS_FreeValue(ctx, index_val);
                if (MBJS_IsException(ret))
                    goto fail;
                MBJS_FreeValue(ctx, ret);
                index_val = MBJS_UNDEFINED;
                ret = MBJS_UNDEFINED;
                item = MBJS_UNDEFINED;
            }
        }
        break;
    case MBJS_ITERATOR_HELPER_KIND_SOME:
        {
            r = MBJS_FALSE;
            for (idx = 0; /*empty*/; idx++) {
                item = MBJS_IteratorNext(ctx, this_val, method, 0, NULL, &done);
                if (MBJS_IsException(item))
                    goto step_fail;
                if (done)
                    break;
                index_val = mbjs_int64(idx);
                args[0] = item;
                args[1] = index_val;
                ret = MBJS_Call(ctx, func, MBJS_UNDEFINED, countof(args), args);
                MBJS_FreeValue(ctx, item);
                MBJS_FreeValue(ctx, index_val);
                if (MBJS_IsException(ret))
                    goto fail;
                if (MBJS_ToBoolFree(ctx, ret)) {
                    if (MBJS_IteratorClose(ctx, this_val, false) < 0)
                        r = MBJS_EXCEPTION;
                    else
                        r = MBJS_TRUE;
                    break;
                }
                index_val = MBJS_UNDEFINED;
                ret = MBJS_UNDEFINED;
                item = MBJS_UNDEFINED;
            }
        }
        break;
    default:
        abort();
        break;
    }

    MBJS_FreeValue(ctx, func);
    MBJS_FreeValue(ctx, method);
    return r;
fail:
    /* an abrupt completion from the callback closes the iterator
       (IfAbruptCloseIterator) */
    MBJS_IteratorClose(ctx, this_val, true);
step_fail:
    /* GetIteratorDirect and IteratorStepValue leave the iterator alone */
    MBJS_FreeValue(ctx, func);
    MBJS_FreeValue(ctx, method);
    return MBJS_EXCEPTION;
}

static MBJSValue mbjs_iterator_proto_includes(MBJSContext *ctx, MBJSValueConst this_val,
                                          int argc, MBJSValueConst *argv)
{
    MBJSValue item, method;
    int64_t to_skip, skipped;
    double d;
    int done;

    if (check_iterator(ctx, this_val) < 0)
        return MBJS_EXCEPTION;

    // skippedElements is deliberately not coerced: anything that isn't an
    // integral Number (or +/-Infinity) is a TypeError, and the underlying
    // iterator is closed before the error propagates.
    to_skip = 0;
    if (argc > 1 && !MBJS_IsUndefined(argv[1])) {
        if (!MBJS_IsNumber(argv[1])) {
            MBJS_ThrowTypeError(ctx, "not a number");
            goto fail;
        }
        MBJS_ToFloat64(ctx, &d, argv[1]); // cannot fail
        if (isnan(d) || (isfinite(d) && trunc(d) != d)) {
            MBJS_ThrowTypeError(ctx, "not an integral number");
            goto fail;
        }
        if (d < 0 || (isfinite(d) && d > MAX_SAFE_INTEGER)) {
            MBJS_ThrowRangeError(ctx, "must be positive");
            goto fail;
        }
        // +Infinity means "skip everything"; use MAX_SAFE_INTEGER
        to_skip = isfinite(d) ? (int64_t)d : MAX_SAFE_INTEGER;
    }

    // Note: a failure here propagates without closing the iterator.
    method = MBJS_GetProperty(ctx, this_val, MBJS_ATOM_next);
    if (MBJS_IsException(method))
        return MBJS_EXCEPTION;

    for (skipped = 0; /*empty*/; /*empty*/) {
        item = MBJS_IteratorNext(ctx, this_val, method, 0, NULL, &done);
        if (MBJS_IsException(item)) {
            // IteratorStepValue marks the iterator done, it does not close it.
            MBJS_FreeValue(ctx, method);
            return MBJS_EXCEPTION;
        }
        if (done) {
            MBJS_FreeValue(ctx, method);
            return MBJS_FALSE;
        }
        if (skipped < to_skip) {
            skipped++;
        } else if (mbjs_same_value_zero(ctx, item, argv[0])) {
            MBJS_FreeValue(ctx, item);
            MBJS_FreeValue(ctx, method);
            if (MBJS_IteratorClose(ctx, this_val, false) < 0)
                return MBJS_EXCEPTION;
            return MBJS_TRUE;
        }
        MBJS_FreeValue(ctx, item);
    }
fail:
    MBJS_IteratorClose(ctx, this_val, true);
    return MBJS_EXCEPTION;
}

static MBJSValue mbjs_iterator_proto_reduce(MBJSContext *ctx, MBJSValueConst this_val,
                                        int argc, MBJSValueConst *argv)
{
    MBJSValue item, method, ret, func, index_val, acc;
    MBJSValueConst args[3];
    int64_t idx;
    int done;

    if (check_iterator(ctx, this_val) < 0)
        return MBJS_EXCEPTION;
    acc = MBJS_UNDEFINED;
    func = MBJS_UNDEFINED;
    method = MBJS_UNDEFINED;
    if (check_function(ctx, argv[0]))
        goto exception;
    func = mbjs_dup(argv[0]);
    /* GetIteratorDirect: propagates as is, no IteratorClose */
    method = MBJS_GetProperty(ctx, this_val, MBJS_ATOM_next);
    if (MBJS_IsException(method))
        goto step_exception;
    if (argc > 1) {
        acc = mbjs_dup(argv[1]);
        idx = 0;
    } else {
        acc = MBJS_IteratorNext(ctx, this_val, method, 0, NULL, &done);
        if (MBJS_IsException(acc))
            goto step_exception;
        if (done) {
            /* the iterator is already done, don't close it */
            MBJS_ThrowTypeError(ctx, "empty iterator");
            goto step_exception;
        }
        idx = 1;
    }
    for (/* empty */; /*empty*/; idx++) {
        item = MBJS_IteratorNext(ctx, this_val, method, 0, NULL, &done);
        if (MBJS_IsException(item))
            goto step_exception;
        if (done)
            break;
        index_val = mbjs_int64(idx);
        args[0] = acc;
        args[1] = item;
        args[2] = index_val;
        ret = MBJS_Call(ctx, func, MBJS_UNDEFINED, countof(args), args);
        MBJS_FreeValue(ctx, item);
        MBJS_FreeValue(ctx, index_val);
        if (MBJS_IsException(ret))
            goto exception;
        MBJS_FreeValue(ctx, acc);
        acc = ret;
        index_val = MBJS_UNDEFINED;
        ret = MBJS_UNDEFINED;
        item = MBJS_UNDEFINED;
    }
    MBJS_FreeValue(ctx, func);
    MBJS_FreeValue(ctx, method);
    return acc;
exception:
    /* an abrupt completion from the reducer closes the iterator
       (IfAbruptCloseIterator) */
    MBJS_IteratorClose(ctx, this_val, true);
step_exception:
    /* GetIteratorDirect and IteratorStepValue leave the iterator alone */
    MBJS_FreeValue(ctx, acc);
    MBJS_FreeValue(ctx, func);
    MBJS_FreeValue(ctx, method);
    return MBJS_EXCEPTION;
}

static MBJSValue mbjs_iterator_proto_toArray(MBJSContext *ctx, MBJSValueConst this_val,
                                         int argc, MBJSValueConst *argv)
{
    MBJSValue item, method, result;
    int64_t idx;
    int done;

    result = MBJS_UNDEFINED;
    if (check_iterator(ctx, this_val) < 0)
        return MBJS_EXCEPTION;
    method = MBJS_GetProperty(ctx, this_val, MBJS_ATOM_next);
    if (MBJS_IsException(method))
        return MBJS_EXCEPTION;
    result = MBJS_NewArray(ctx);
    if (MBJS_IsException(result))
        goto exception;
    for (idx = 0; /*empty*/; idx++) {
        item = MBJS_IteratorNext(ctx, this_val, method, 0, NULL, &done);
        if (MBJS_IsException(item))
            goto exception;
        if (done)
            break;
        if (MBJS_DefinePropertyValueInt64(ctx, result, idx, item,
                                        MBJS_PROP_C_W_E | MBJS_PROP_THROW) < 0)
            goto exception;
    }
    if (MBJS_SetProperty(ctx, result, MBJS_ATOM_length, mbjs_uint32(idx)) < 0)
        goto exception;
    MBJS_FreeValue(ctx, method);
    return result;
exception:
    MBJS_FreeValue(ctx, result);
    MBJS_FreeValue(ctx, method);
    return MBJS_EXCEPTION;
}

static MBJSValue mbjs_iterator_proto_join(MBJSContext *ctx, MBJSValueConst this_val,
                                      int argc, MBJSValueConst *argv)
{
    MBJSValue item, method, sep = MBJS_UNDEFINED;
    StringBuffer b_s, *b = &b_s;
    MBJSString *p = NULL;
    bool first;
    int c, done;

    if (check_iterator(ctx, this_val) < 0)
        return MBJS_EXCEPTION;
    c = ',';    /* default separator */
    if (!MBJS_IsUndefined(argv[0])) {
        sep = MBJS_ToString(ctx, argv[0]);
        if (MBJS_IsException(sep)) {
            MBJS_IteratorClose(ctx, this_val, /*is_exception_pending*/true);
            return MBJS_EXCEPTION;
        }
        p = MBJS_VALUE_GET_STRING(sep);
        if (p->len == 1 && !p->is_wide_char)
            c = str8(p)[0];
        else
            c = -1;
    }
    method = MBJS_GetProperty(ctx, this_val, MBJS_ATOM_next);
    if (MBJS_IsException(method)) {
        MBJS_FreeValue(ctx, sep);
        return MBJS_EXCEPTION;
    }
    string_buffer_init(ctx, b, 0);
    for (first = true; /*empty*/; first = false) {
        item = MBJS_IteratorNext(ctx, this_val, method, 0, NULL, &done);
        if (MBJS_IsException(item))
            goto fail;
        if (done)
            break;
        if (!first) {
            if (c >= 0)
                string_buffer_putc8(b, c);
            else
                string_buffer_concat(b, p, 0, p->len);
        }
        /* nullish values contribute the empty string */
        if (MBJS_IsNull(item) || MBJS_IsUndefined(item)) {
            MBJS_FreeValue(ctx, item);
            continue;
        }
        if (string_buffer_concat_value_free(b, item))
            goto close;
    }
    MBJS_FreeValue(ctx, method);
    MBJS_FreeValue(ctx, sep);
    return string_buffer_end(b);

close:
    MBJS_IteratorClose(ctx, this_val, /*is_exception_pending*/true);
fail:
    string_buffer_free(b);
    MBJS_FreeValue(ctx, method);
    MBJS_FreeValue(ctx, sep);
    return MBJS_EXCEPTION;
}

static MBJSValue mbjs_async_dispose_to_undef(MBJSContext *ctx, MBJSValueConst this_val,
                                         int argc, MBJSValueConst *argv,
                                         int magic, MBJSValueConst *func_data);

static MBJSValue mbjs_iterator_proto_dispose(MBJSContext *ctx, MBJSValueConst this_val,
                                         int argc, MBJSValueConst *argv)
{
    MBJSValue method;

    method = MBJS_GetProperty(ctx, this_val, MBJS_ATOM_return);
    if (MBJS_IsException(method))
        return MBJS_EXCEPTION;
    if (MBJS_IsUndefined(method))
        return MBJS_UNDEFINED;
    return MBJS_CallFree(ctx, method, this_val, 0, NULL);
}

static MBJSValue mbjs_async_iterator_proto_dispose(MBJSContext *ctx,
                                               MBJSValueConst this_val,
                                               int argc, MBJSValueConst *argv)
{
    MBJSValue method, ret, promise, undef_fn, then_args[1], result;
    MBJSValue undef = MBJS_UNDEFINED;

    method = MBJS_GetProperty(ctx, this_val, MBJS_ATOM_return);
    if (MBJS_IsException(method)) {
        MBJSValue exc = MBJS_GetException(ctx);
        MBJSValue p = mbjs_promise_resolve(ctx, ctx->promise_ctor, 1, vc(&exc), 1);
        MBJS_FreeValue(ctx, exc);
        return p;
    }
    if (MBJS_IsUndefined(method)) {
        return mbjs_promise_resolve(ctx, ctx->promise_ctor, 1, vc(&undef), 0);
    }
    ret = MBJS_Call(ctx, method, this_val, 0, NULL);
    MBJS_FreeValue(ctx, method);
    if (MBJS_IsException(ret)) {
        MBJSValue exc = MBJS_GetException(ctx);
        MBJSValue p = mbjs_promise_resolve(ctx, ctx->promise_ctor, 1, vc(&exc), 1);
        MBJS_FreeValue(ctx, exc);
        return p;
    }
    /* Wrap in Promise.resolve(ret).then(() => undefined) */
    promise = mbjs_promise_resolve(ctx, ctx->promise_ctor, 1, vc(&ret), 0);
    MBJS_FreeValue(ctx, ret);
    if (MBJS_IsException(promise))
        return promise;
    undef_fn = MBJS_NewCFunctionData(ctx, mbjs_async_dispose_to_undef, 0, 0, 0,
                                   NULL);
    if (MBJS_IsException(undef_fn)) {
        MBJS_FreeValue(ctx, promise);
        return MBJS_EXCEPTION;
    }
    then_args[0] = undef_fn;
    result = MBJS_Invoke(ctx, promise, MBJS_ATOM_then, 1, vc(then_args));
    MBJS_FreeValue(ctx, undef_fn);
    MBJS_FreeValue(ctx, promise);
    return result;
}

static MBJSValue mbjs_iterator_proto_iterator(MBJSContext *ctx, MBJSValueConst this_val,
                                          int argc, MBJSValueConst *argv)
{
    return mbjs_dup(this_val);
}

static MBJSValue mbjs_iterator_proto_get_toStringTag(MBJSContext *ctx, MBJSValueConst this_val)
{
    return MBJS_AtomToString(ctx, MBJS_ATOM_Iterator);
}

static MBJSValue mbjs_iterator_proto_set_toStringTag(MBJSContext *ctx, MBJSValueConst this_val, MBJSValueConst val)
{
    int res;

    if (check_iterator(ctx, this_val) < 0)
        return MBJS_EXCEPTION;
    if (mbjs_same_value(ctx, this_val, ctx->class_proto[MBJS_CLASS_ITERATOR]))
        return MBJS_ThrowTypeError(ctx, "Cannot assign to read only property");
    res = MBJS_GetOwnProperty(ctx, NULL, this_val, MBJS_ATOM_Symbol_toStringTag);
    if (res < 0)
        return MBJS_EXCEPTION;
    if (res) {
        if (MBJS_SetProperty(ctx, this_val, MBJS_ATOM_Symbol_toStringTag, mbjs_dup(val)) < 0)
            return MBJS_EXCEPTION;
    } else {
        if (MBJS_DefinePropertyValueConst(ctx, this_val, MBJS_ATOM_Symbol_toStringTag, val, MBJS_PROP_C_W_E | MBJS_PROP_THROW) < 0)
            return MBJS_EXCEPTION;
    }
    return MBJS_UNDEFINED;
}

static void mbjs_iterator_helper_finalizer(MBJSRuntime *rt, MBJSValueConst val)
{
    MBJSObject *p = MBJS_VALUE_GET_OBJ(val);
    MBJSIteratorHelperData *it = p->u.iterator_helper_data;
    if (it) {
        MBJS_FreeValueRT(rt, it->obj);
        MBJS_FreeValueRT(rt, it->func);
        MBJS_FreeValueRT(rt, it->next);
        MBJS_FreeValueRT(rt, it->inner);
        while (it->buf_count > 0)
            MBJS_FreeValueRT(rt, it->buf[--it->buf_count]);
        mbjs_free_rt(rt, it->buf);
        mbjs_free_rt(rt, it);
    }
}

static void mbjs_iterator_helper_mark(MBJSRuntime *rt, MBJSValueConst val,
                                   MBJS_MarkFunc *mark_func)
{
    MBJSObject *p = MBJS_VALUE_GET_OBJ(val);
    MBJSIteratorHelperData *it = p->u.iterator_helper_data;
    if (it) {
        MBJS_MarkValue(rt, it->obj, mark_func);
        MBJS_MarkValue(rt, it->func, mark_func);
        MBJS_MarkValue(rt, it->next, mark_func);
        MBJS_MarkValue(rt, it->inner, mark_func);
        for (int i = 0; i < it->buf_count; i++)
            MBJS_MarkValue(rt, it->buf[i], mark_func);
    }
}

static MBJSValue mbjs_iterator_helper_next(MBJSContext *ctx, MBJSValueConst this_val,
                                      int argc, MBJSValueConst *argv,
                                      int *pdone, int magic)
{
    MBJSIteratorHelperData *it;
    bool finished;
    MBJSValue ret;

    *pdone = false;
    finished = false;

    /* Iterator.concat() also hands out Iterator Helper objects, sharing this
       prototype but keeping their own state */
    if (MBJS_VALUE_GET_TAG(this_val) == MBJS_TAG_OBJECT &&
        MBJS_VALUE_GET_OBJ(this_val)->class_id == MBJS_CLASS_ITERATOR_CONCAT) {
        if (magic == GEN_MAGIC_RETURN)
            return mbjs_iterator_concat_return(ctx, this_val, argc, argv, pdone,
                                             magic);
        return mbjs_iterator_concat_next(ctx, this_val, argc, argv, pdone, magic);
    }

    it = MBJS_GetOpaque2(ctx, this_val, MBJS_CLASS_ITERATOR_HELPER);
    if (!it)
        return MBJS_EXCEPTION;
    if (it->executing)
        return MBJS_ThrowTypeError(ctx, "cannot invoke a running iterator");
    if (it->done) {
        *pdone = true;
        return MBJS_UNDEFINED;
    }

    it->executing = 1;

    switch (it->kind) {
    case MBJS_ITERATOR_HELPER_KIND_CHUNKS:
    case MBJS_ITERATOR_HELPER_KIND_WINDOWS:
        {
            bool windows = it->kind == MBJS_ITERATOR_HELPER_KIND_WINDOWS;
            MBJSValue item;

            if (magic == GEN_MAGIC_RETURN)
                goto close;
            for (;;) {
                item = MBJS_IteratorNext(ctx, it->obj, it->next, 0, NULL, pdone);
                if (MBJS_IsException(item))
                    goto step_fail;
                if (*pdone) {
                    MBJS_FreeValue(ctx, item);
                    /* the underlying iterator is done: yield what's left in
                       the buffer, if anything, then stop */
                    finished = true;
                    ret = MBJS_UNDEFINED;
                    if (it->buf_count < 1)
                        goto done;
                    if (windows) {
                        /* a full window was already yielded */
                        if (!it->allow_partial || it->buf_count >= it->count)
                            goto done;
                        ret = mbjs_create_array(ctx, it->buf_count, vc(it->buf));
                    } else {
                        ret = MBJS_NewArrayFrom(ctx, it->buf_count, it->buf);
                        it->buf_count = 0; // ownership transferred
                    }
                    if (MBJS_IsException(ret))
                        goto step_fail;
                    *pdone = false;
                    goto done;
                }
                if (windows && it->buf_count == it->count) {
                    /* slide the window */
                    MBJS_FreeValue(ctx, it->buf[0]);
                    it->buf_count--;
                    memmove(it->buf, &it->buf[1],
                            it->buf_count * sizeof(*it->buf));
                }
                if (mbjs_resize_array(ctx, (void **)&it->buf, sizeof(*it->buf),
                                    &it->buf_size, it->buf_count + 1)) {
                    MBJS_FreeValue(ctx, item);
                    goto step_fail;
                }
                it->buf[it->buf_count++] = item;
                if (it->buf_count == it->count) {
                    if (windows) {
                        ret = mbjs_create_array(ctx, it->buf_count, vc(it->buf));
                    } else {
                        ret = MBJS_NewArrayFrom(ctx, it->buf_count, it->buf);
                        it->buf_count = 0; // ownership transferred
                    }
                    if (MBJS_IsException(ret))
                        goto step_fail;
                    goto done;
                }
            }
        }
        break;
    case MBJS_ITERATOR_HELPER_KIND_DROP:
        {
            MBJSValue item;
            if (magic == GEN_MAGIC_RETURN)
                goto close;
            while (it->count > 0) {
                it->count--;
                item = MBJS_IteratorNext(ctx, it->obj, it->next, 0, NULL, pdone);
                if (MBJS_IsException(item))
                    goto step_fail;
                MBJS_FreeValue(ctx, item);
                if (*pdone) {
                    ret = MBJS_UNDEFINED;
                    goto done;
                }
            }

            item = MBJS_IteratorNext(ctx, it->obj, it->next, 0, NULL, pdone);
            if (MBJS_IsException(item))
                goto step_fail;
            ret = item;
            goto done;
        }
        break;
    case MBJS_ITERATOR_HELPER_KIND_FILTER:
        {
            MBJSValue item, selected, index_val;
            MBJSValueConst args[2];
            if (magic == GEN_MAGIC_RETURN)
                goto close;
        filter_again:
            item = MBJS_IteratorNext(ctx, it->obj, it->next, 0, NULL, pdone);
            if (MBJS_IsException(item))
                goto step_fail;
            if (*pdone) {
                ret = item;
                goto done;
            }
            index_val = mbjs_int64(it->count++);
            args[0] = item;
            args[1] = index_val;
            selected = MBJS_Call(ctx, it->func, MBJS_UNDEFINED, countof(args), args);
            MBJS_FreeValue(ctx, index_val);
            if (MBJS_IsException(selected)) {
                MBJS_FreeValue(ctx, item);
                goto fail;
            }
            if (MBJS_ToBoolFree(ctx, selected)) {
                ret = item;
                goto done;
            }
            MBJS_FreeValue(ctx, item);
            goto filter_again;
        }
        break;
    case MBJS_ITERATOR_HELPER_KIND_FLAT_MAP:
        {
            MBJSValue item, method, index_val, iter;
            MBJSValueConst args[2];
            if (magic == GEN_MAGIC_RETURN)
                goto close;
        flat_map_again:
            if (MBJS_IsUndefined(it->inner)) {
                item = MBJS_IteratorNext(ctx, it->obj, it->next, 0, NULL, pdone);
                if (MBJS_IsException(item))
                    goto step_fail;
                if (*pdone) {
                    ret = item;
                    goto done;
                }
                index_val = mbjs_int64(it->count++);
                args[0] = item;
                args[1] = index_val;
                ret = MBJS_Call(ctx, it->func, MBJS_UNDEFINED, countof(args), args);
                MBJS_FreeValue(ctx, item);
                MBJS_FreeValue(ctx, index_val);
                if (MBJS_IsException(ret))
                    goto fail;
                if (!MBJS_IsObject(ret)) {
                    MBJS_FreeValue(ctx, ret);
                    MBJS_ThrowTypeError(ctx, "not an object");
                    goto fail;
                }
                method = MBJS_GetProperty(ctx, ret, MBJS_ATOM_Symbol_iterator);
                if (MBJS_IsException(method)) {
                    MBJS_FreeValue(ctx, ret);
                    goto fail;
                }
                if (MBJS_IsNull(method) || MBJS_IsUndefined(method)) {
                    MBJS_FreeValue(ctx, method);
                    iter = ret;
                } else {
                    iter = MBJS_GetIterator2(ctx, ret, method);
                    MBJS_FreeValue(ctx, method);
                    MBJS_FreeValue(ctx, ret);
                    if (MBJS_IsException(iter))
                        goto fail;
                }

                it->inner = iter;
            }

            method = MBJS_GetProperty(ctx, it->inner, MBJS_ATOM_next);
            if (MBJS_IsException(method)) {
            inner_fail:
                /* the inner iterator is only marked done, the outer one is
                   closed by the |fail| label */
                MBJS_FreeValue(ctx, it->inner);
                it->inner = MBJS_UNDEFINED;
                goto fail;
            }
            item = MBJS_IteratorNext(ctx, it->inner, method, 0, NULL, pdone);
            MBJS_FreeValue(ctx, method);
            if (MBJS_IsException(item))
                goto inner_fail;
            if (*pdone) {
                *pdone = false; // The outer iterator must continue.
                MBJS_IteratorClose(ctx, it->inner, false);
                MBJS_FreeValue(ctx, it->inner);
                it->inner = MBJS_UNDEFINED;
                goto flat_map_again;
            }
            ret = item;
            goto done;
        }
        break;
    case MBJS_ITERATOR_HELPER_KIND_MAP:
        {
            MBJSValue item, index_val;
            MBJSValueConst args[2];
            if (magic == GEN_MAGIC_RETURN)
                goto close;
            item = MBJS_IteratorNext(ctx, it->obj, it->next, 0, NULL, pdone);
            if (MBJS_IsException(item))
                goto step_fail;
            if (*pdone) {
                ret = item;
                goto done;
            }
            index_val = mbjs_int64(it->count++);
            args[0] = item;
            args[1] = index_val;
            ret = MBJS_Call(ctx, it->func, MBJS_UNDEFINED, countof(args), args);
            MBJS_FreeValue(ctx, index_val);
            MBJS_FreeValue(ctx, item);
            if (MBJS_IsException(ret))
                goto fail;
            goto done;
        }
        break;
    case MBJS_ITERATOR_HELPER_KIND_TAKE:
        {
            MBJSValue item;
            if (magic == GEN_MAGIC_RETURN || it->count == 0)
                goto close;
            it->count--;
            item = MBJS_IteratorNext(ctx, it->obj, it->next, 0, NULL, pdone);
            if (MBJS_IsException(item))
                goto step_fail;
            ret = item;
            goto done;
        }
        break;
    default:
        abort();
    }

close:
    *pdone = true;
    ret = MBJS_UNDEFINED;
    if (!MBJS_IsUndefined(it->inner)) {
        if (MBJS_IteratorClose(ctx, it->inner, false))
            ret = MBJS_EXCEPTION;
        MBJS_FreeValue(ctx, it->inner);
        it->inner = MBJS_UNDEFINED;
    }
    if (MBJS_IteratorClose(ctx, it->obj, MBJS_IsException(ret)))
        ret = MBJS_EXCEPTION;

done:
    it->done = finished || (magic == GEN_MAGIC_NEXT ? *pdone : 1);
    it->executing = 0;
    if (it->done && it->buf) {
        while (it->buf_count > 0)
            MBJS_FreeValue(ctx, it->buf[--it->buf_count]);
        mbjs_free(ctx, it->buf);
        it->buf = NULL;
        it->buf_size = 0;
    }
    return ret;
step_fail:
    /* an abrupt completion from stepping the iterator object, or from the body
       of the closure, does not close it: IteratorStepValue only marks the
       iterator record done */
    finished = true;
    ret = MBJS_EXCEPTION;
    goto done;
fail:
    /* an abrupt completion from the callback closes the iterator object
       (IfAbruptCloseIterator), preserving the pending exception */
    finished = true;
    MBJS_IteratorClose(ctx, it->obj, true);
    ret = MBJS_EXCEPTION;
    goto done;
}

