/* Number */

static MBJSValue mbjs_number_constructor(MBJSContext *ctx, MBJSValueConst new_target,
                                     int argc, MBJSValueConst *argv)
{
    MBJSValue val, obj;
    if (argc == 0) {
        val = mbjs_int32(0);
    } else {
        val = MBJS_ToNumeric(ctx, argv[0]);
        if (MBJS_IsException(val))
            return val;
        switch(MBJS_VALUE_GET_TAG(val)) {
        case MBJS_TAG_SHORT_BIG_INT:
            val = mbjs_int64(MBJS_VALUE_GET_SHORT_BIG_INT(val));
            if (MBJS_IsException(val))
                return val;
            break;
        case MBJS_TAG_BIG_INT:
            {
                MBJSBigInt *p = MBJS_VALUE_GET_PTR(val);
                double d;
                d = mbjs_bigint_to_float64(ctx, p);
                MBJS_FreeValue(ctx, val);
                val = mbjs_float64(d);
            }
            break;
        default:
            break;
        }
    }
    if (!MBJS_IsUndefined(new_target)) {
        obj = mbjs_create_from_ctor(ctx, new_target, MBJS_CLASS_NUMBER);
        if (!MBJS_IsException(obj))
            MBJS_SetObjectData(ctx, obj, val);
        return obj;
    } else {
        return val;
    }
}

static MBJSValue mbjs_number_isNaN(MBJSContext *ctx, MBJSValueConst this_val,
                               int argc, MBJSValueConst *argv)
{
    if (!MBJS_IsNumber(argv[0]))
        return MBJS_FALSE;
    return mbjs_global_isNaN(ctx, this_val, argc, argv);
}

static MBJSValue mbjs_number_isFinite(MBJSContext *ctx, MBJSValueConst this_val,
                                  int argc, MBJSValueConst *argv)
{
    if (!MBJS_IsNumber(argv[0]))
        return MBJS_FALSE;
    return mbjs_global_isFinite(ctx, this_val, argc, argv);
}

static MBJSValue mbjs_number_isInteger(MBJSContext *ctx, MBJSValueConst this_val,
                                   int argc, MBJSValueConst *argv)
{
    int ret;
    ret = MBJS_NumberIsInteger(ctx, argv[0]);
    if (ret < 0)
        return MBJS_EXCEPTION;
    else
        return mbjs_bool(ret);
}

static MBJSValue mbjs_number_isSafeInteger(MBJSContext *ctx, MBJSValueConst this_val,
                                       int argc, MBJSValueConst *argv)
{
    double d;
    if (!MBJS_IsNumber(argv[0]))
        return MBJS_FALSE;
    if (unlikely(MBJS_ToFloat64(ctx, &d, argv[0])))
        return MBJS_EXCEPTION;
    return mbjs_bool(is_safe_integer(d));
}

