/* Math */

/* precondition: a and b are not NaN */
static double mbjs_fmin(double a, double b)
{
    if (a == 0 && b == 0) {
        MBJSFloat64Union a1, b1;
        a1.d = a;
        b1.d = b;
        a1.u64 |= b1.u64;
        return a1.d;
    } else {
        return a < b ? a : b;
    }
}

/* precondition: a and b are not NaN */
static double mbjs_fmax(double a, double b)
{
    if (a == 0 && b == 0) {
        MBJSFloat64Union a1, b1;
        a1.d = a;
        b1.d = b;
        a1.u64 &= b1.u64;
        return a1.d;
    } else {
        return a < b ? b : a;
    }
}

static MBJSValue mbjs_math_min_max(MBJSContext *ctx, MBJSValueConst this_val,
                               int argc, MBJSValueConst *argv, int magic)
{
    bool is_max = magic;
    double r, a;
    int i;
    uint32_t tag;

    if (unlikely(argc == 0)) {
        return mbjs_float64(is_max ? -INFINITY : INFINITY);
    }

    tag = MBJS_VALUE_GET_TAG(argv[0]);
    if (tag == MBJS_TAG_INT) {
        int a1, r1 = MBJS_VALUE_GET_INT(argv[0]);
        for(i = 1; i < argc; i++) {
            tag = MBJS_VALUE_GET_TAG(argv[i]);
            if (tag != MBJS_TAG_INT) {
                r = r1;
                goto generic_case;
            }
            a1 = MBJS_VALUE_GET_INT(argv[i]);
            if (is_max)
                r1 = max_int(r1, a1);
            else
                r1 = min_int(r1, a1);

        }
        return mbjs_int32(r1);
    } else {
        if (MBJS_ToFloat64(ctx, &r, argv[0]))
            return MBJS_EXCEPTION;
        i = 1;
    generic_case:
        while (i < argc) {
            if (MBJS_ToFloat64(ctx, &a, argv[i]))
                return MBJS_EXCEPTION;
            if (!isnan(r)) {
                if (isnan(a)) {
                    r = a;
                } else {
                    if (is_max)
                        r = mbjs_fmax(r, a);
                    else
                        r = mbjs_fmin(r, a);
                }
            }
            i++;
        }
        return mbjs_number(r);
    }
}

static double mbjs_math_sign(double a)
{
    if (isnan(a) || a == 0.0)
        return a;
    if (a < 0)
        return -1;
    else
        return 1;
}

static double mbjs_math_round(double a)
{
    MBJSFloat64Union u;
    uint64_t frac_mask, one;
    unsigned int e, s;

    u.d = a;
    e = (u.u64 >> 52) & 0x7ff;
    if (e < 1023) {
        /* abs(a) < 1 */
        if (e == (1023 - 1) && u.u64 != 0xbfe0000000000000) {
            /* abs(a) > 0.5 or a = 0.5: return +/-1.0 */
            u.u64 = (u.u64 & ((uint64_t)1 << 63)) | ((uint64_t)1023 << 52);
        } else {
            /* return +/-0.0 */
            u.u64 &= (uint64_t)1 << 63;
        }
    } else if (e < (1023 + 52)) {
        s = u.u64 >> 63;
        one = (uint64_t)1 << (52 - (e - 1023));
        frac_mask = one - 1;
        u.u64 += (one >> 1) - s;
        u.u64 &= ~frac_mask; /* truncate to an integer */
    }
    /* otherwise: abs(a) >= 2^52, or NaN, +/-Infinity: no change */
    return u.d;
}

static MBJSValue mbjs_math_hypot(MBJSContext *ctx, MBJSValueConst this_val,
                             int argc, MBJSValueConst *argv)
{
    double r, a;
    int i;

    r = 0;
    if (argc > 0) {
        if (MBJS_ToFloat64(ctx, &r, argv[0]))
            return MBJS_EXCEPTION;
        if (argc == 1) {
            r = fabs(r);
        } else {
            /* use the built-in function to minimize precision loss */
            for (i = 1; i < argc; i++) {
                if (MBJS_ToFloat64(ctx, &a, argv[i]))
                    return MBJS_EXCEPTION;
                r = hypot(r, a);
            }
        }
    }
    return mbjs_float64(r);
}

static double mbjs_math_f16round(double a)
{
    return fromfp16(tofp16(a));
}

static double mbjs_math_fround(double a)
{
    return (float)a;
}

static MBJSValue mbjs_math_imul(MBJSContext *ctx, MBJSValueConst this_val,
                            int argc, MBJSValueConst *argv)
{
    uint32_t a, b, c;
    int32_t d;

    if (MBJS_ToUint32(ctx, &a, argv[0]))
        return MBJS_EXCEPTION;
    if (MBJS_ToUint32(ctx, &b, argv[1]))
        return MBJS_EXCEPTION;
    c = a * b;
    memcpy(&d, &c, sizeof(d));
    return mbjs_int32(d);
}

static MBJSValue mbjs_math_clz32(MBJSContext *ctx, MBJSValueConst this_val,
                             int argc, MBJSValueConst *argv)
{
    uint32_t a, r;

    if (MBJS_ToUint32(ctx, &a, argv[0]))
        return MBJS_EXCEPTION;
    if (a == 0)
        r = 32;
    else
        r = clz32(a);
    return mbjs_int32(r);
}

/* we add one extra limb to avoid having to test for overflows during the sum */
#define SUM_PRECISE_ACC_LEN 34

typedef enum {
    SUM_PRECISE_STATE_MINUS_ZERO,
    SUM_PRECISE_STATE_FINITE,
    SUM_PRECISE_STATE_INFINITY,
    SUM_PRECISE_STATE_MINUS_INFINITY, /* must be after SUM_PRECISE_STATE_INFINITY */
    SUM_PRECISE_STATE_NAN, /* must be after SUM_PRECISE_STATE_MINUS_INFINITY */
} SumPreciseStateEnum;

typedef struct {
    uint64_t acc[SUM_PRECISE_ACC_LEN];
    int n_limbs; /* acc is not necessarily normalized */
    SumPreciseStateEnum state;
} SumPreciseState;

static void sum_precise_init(SumPreciseState *s)
{
    s->state = SUM_PRECISE_STATE_MINUS_ZERO;
    s->acc[0] = 0;
    s->n_limbs = 1;
}

#define ADDC64(res, carry_out, op1, op2, carry_in)      \
do {                                                    \
    uint64_t __v, __a, __k, __k1;                       \
    __v = (op1);                                        \
    __a = __v + (op2);                                  \
    __k1 = __a < __v;                                   \
    __k = (carry_in);                                   \
    __a = __a + __k;                                    \
    carry_out = (__a < __k) | __k1;                     \
    res = __a;                                          \
} while (0)

static void sum_precise_add(SumPreciseState *s, double d)
{
    uint64_t a, m, a0, carry, acc_sign, a_sign;
    int sgn, e, p, n, i;
    unsigned shift;

    a = float64_as_uint64(d);
    sgn = a >> 63;
    e = (a >> 52) & ((1 << 11) - 1);
    m = a & (((uint64_t)1 << 52) - 1);
    if (unlikely(e == 2047)) {
        if (m == 0) {
            /* +/- infinity */
            if (s->state == SUM_PRECISE_STATE_NAN ||
                (s->state == SUM_PRECISE_STATE_MINUS_INFINITY && !sgn) ||
                (s->state == SUM_PRECISE_STATE_INFINITY && sgn)) {
                s->state = SUM_PRECISE_STATE_NAN;
            } else {
                s->state = SUM_PRECISE_STATE_INFINITY + sgn;
            }
        } else {
            /* NaN */
            s->state = SUM_PRECISE_STATE_NAN;
        }
    } else if (e == 0) {
        if (likely(m == 0)) {
            /* zero */
            if (s->state == SUM_PRECISE_STATE_MINUS_ZERO && !sgn)
                s->state = SUM_PRECISE_STATE_FINITE;
        } else {
            /* subnormal */
            p = 0;
            shift = 0;
            goto add;
        }
    } else {
        m |= (uint64_t)1 << 52;
        shift = e - 1;
        p = shift / 64;
        /* 'p' is the position of a0 in acc */
        shift %= 64;
    add:
        if (s->state >= SUM_PRECISE_STATE_INFINITY)
            return;
        s->state = SUM_PRECISE_STATE_FINITE;
        n = s->n_limbs;

        acc_sign = (int64_t)s->acc[n - 1] >> 63;

        /* sign extend acc */
        for(i = n; i <= p; i++)
            s->acc[i] = acc_sign;

        carry = sgn;
        a_sign = -sgn;
        a0 = m << shift;
        ADDC64(s->acc[p], carry, s->acc[p], a0 ^ a_sign, carry);
        if (shift >= 12) {
            p++;
            if (p >= n)
                s->acc[p] = acc_sign;
            a0 = m >> (64 - shift);
            ADDC64(s->acc[p], carry, s->acc[p], a0 ^ a_sign, carry);
        }
        p++;
        if (p >= n) {
            n = p;
        } else {
            /* carry */
            for(i = p; i < n; i++) {
                /* if 'a' positive: stop condition: carry = 0.
                   if 'a' negative: stop condition: carry = 1. */
                if (carry == sgn)
                    goto done;
                ADDC64(s->acc[i], carry, s->acc[i], a_sign, carry);
            }
        }

        /* extend the accumulator if needed */
        a0 = carry + acc_sign + a_sign;
        /* -1 <= a0 <= 1 (if both acc and a are negative, carry is set) */
        if (a0 != ((int64_t)s->acc[n - 1] >> 63)) {
            s->acc[n++] = a0;
        }
    done:
        s->n_limbs = n;
    }
}

static double sum_precise_get_result(SumPreciseState *s)
{
    int n, shift, e, p, is_neg, i;
    uint64_t m, addend, carry;

    if (s->state != SUM_PRECISE_STATE_FINITE) {
        switch(s->state) {
        default:
        case SUM_PRECISE_STATE_MINUS_ZERO:
            return -0.0;
        case SUM_PRECISE_STATE_INFINITY:
            return INFINITY;
        case SUM_PRECISE_STATE_MINUS_INFINITY:
            return -INFINITY;
        case SUM_PRECISE_STATE_NAN:
            return NAN;
        }
    }

    /* extract the sign and absolute value */
    n = s->n_limbs;
    is_neg = s->acc[n - 1] >> 63;
    if (is_neg) {
        /* acc = -acc */
        carry = 1;
        for(i = 0; i < n; i++) {
            ADDC64(s->acc[i], carry, ~s->acc[i], 0, carry);
        }
    }
    /* normalize */
    while (n > 0 && s->acc[n - 1] == 0)
        n--;
    /* zero result. The spec tells it is always positive in the finite case */
    if (n == 0)
        return 0.0;
    /* subnormal case */
    if (n == 1 && s->acc[0] < ((uint64_t)1 << 52))
        return uint64_as_float64(((uint64_t)is_neg << 63) | s->acc[0]);
    /* normal case */
    e = n * 64;
    p = n - 1;
    m = s->acc[p];
    shift = clz64(m);
    e = e - shift - 52;
    if (shift != 0) {
        m <<= shift;
        if (p > 0) {
            int shift1;
            uint64_t nz;
            p--;
            shift1 = 64 - shift;
            nz = s->acc[p] & (((uint64_t)1 << shift1) - 1);
            m = m | (s->acc[p] >> shift1) | (nz != 0);
        }
    }
    if ((m & ((1 << 10) - 1)) == 0) {
        /* see if the LSB part is non zero for the final rounding  */
        while (p > 0) {
            p--;
            if (s->acc[p] != 0) {
                m |= 1;
                break;
            }
        }
    }
    /* rounding to nearest with ties to even */
    addend = (1 << 10) - 1 + ((m >> 11) & 1);
    m = (m + addend) >> 11;
    /* handle overflow in the rounding */
    if (m == 0)
        e++;
    if (unlikely(e >= 2047)) {
        /* infinity */
        return uint64_as_float64(((uint64_t)is_neg << 63) | ((uint64_t)2047 << 52));
    } else {
        m &= (((uint64_t)1 << 52) - 1);
        return uint64_as_float64(((uint64_t)is_neg << 63) | ((uint64_t)e << 52) | m);
    }
}

static MBJSValue mbjs_math_sumPrecise(MBJSContext *ctx, MBJSValueConst this_val,
                                  int argc, MBJSValueConst *argv)
{
    MBJSValue iter, next, item, ret;
    uint32_t tag;
    int done;
    double d;
    SumPreciseState s_s, *s = &s_s;

    iter = MBJS_GetIterator(ctx, argv[0], /*is_async*/false);
    if (MBJS_IsException(iter))
        return MBJS_EXCEPTION;
    ret = MBJS_EXCEPTION;
    next = MBJS_GetProperty(ctx, iter, MBJS_ATOM_next);
    if (MBJS_IsException(next))
        goto fail;
    sum_precise_init(s);
    for (;;) {
        item = MBJS_IteratorNext(ctx, iter, next, 0, NULL, &done);
        if (MBJS_IsException(item))
            goto fail;
        if (done)
            break;
        tag = MBJS_VALUE_GET_TAG(item);
        if (MBJS_TAG_IS_FLOAT64(tag)) {
            d = MBJS_VALUE_GET_FLOAT64(item);
        } else if (tag == MBJS_TAG_INT) {
            d = MBJS_VALUE_GET_INT(item);
        } else {
            MBJS_FreeValue(ctx, item);
            MBJS_ThrowTypeError(ctx, "not a number");
            MBJS_IteratorClose(ctx, iter, /*is_exception_pending*/true);
            goto fail;
        }
        sum_precise_add(s, d);
    }
    ret = mbjs_float64(sum_precise_get_result(s));
fail:
    MBJS_FreeValue(ctx, iter);
    MBJS_FreeValue(ctx, next);
    return ret;
}

/* xorshift* random number generator by Marsaglia */
static uint64_t xorshift64star(uint64_t *pstate)
{
    uint64_t x;
    x = *pstate;
    x ^= x >> 12;
    x ^= x << 25;
    x ^= x >> 27;
    *pstate = x;
    return x * 0x2545F4914F6CDD1D;
}

static MBJSValue mbjs_math_random(MBJSContext *ctx, MBJSValueConst this_val,
                              int argc, MBJSValueConst *argv)
{
    MBJSFloat64Union u;
    uint64_t v;

    v = xorshift64star(&ctx->random_state);
    /* 1.0 <= u.d < 2 */
    u.u64 = ((uint64_t)0x3ff << 52) | (v >> 12);
    return mbjs_float64(u.d - 1.0);
}

/* use local wrappers for math functions to
   - avoid initializing data with dynamic library entry points.
   - avoid some overhead if the call can be inlined at compile or link time.
 */
static double mbjs_math_fabs(double d) { return fabs(d); }
static double mbjs_math_floor(double d) { return floor(d); }
static double mbjs_math_ceil(double d) { return ceil(d); }
static double mbjs_math_sqrt(double d) { return sqrt(d); }
static double mbjs_math_acos(double d) { return acos(d); }
static double mbjs_math_asin(double d) { return asin(d); }
static double mbjs_math_atan(double d) { return atan(d); }
static double mbjs_math_atan2(double a, double b) { return atan2(a, b); }
static double mbjs_math_cos(double d) { return cos(d); }
static double mbjs_math_exp(double d) { return exp(d); }
static double mbjs_math_log(double d) { return log(d); }
static double mbjs_math_sin(double d) { return sin(d); }
static double mbjs_math_tan(double d) { return tan(d); }
static double mbjs_math_trunc(double d) { return trunc(d); }
static double mbjs_math_cosh(double d) { return cosh(d); }
static double mbjs_math_sinh(double d) { return sinh(d); }
static double mbjs_math_tanh(double d) { return tanh(d); }
static double mbjs_math_acosh(double d) { return acosh(d); }
static double mbjs_math_asinh(double d) { return asinh(d); }
static double mbjs_math_atanh(double d) { return atanh(d); }
static double mbjs_math_expm1(double d) { return expm1(d); }
static double mbjs_math_log1p(double d) { return log1p(d); }
static double mbjs_math_log2(double d) { return log2(d); }
static double mbjs_math_log10(double d) { return log10(d); }
static double mbjs_math_cbrt(double d) { return cbrt(d); }

/* Math.clamp(x, lo, hi) — clamp x to [lo, hi], swapping lo/hi if reversed.
   Proposal-stage helper (V8/Node do not have it yet, so this is a MochiBerry
   superset). */
static MBJSValue mbjs_math_clamp(MBJSContext *ctx, MBJSValueConst this_val,
                                 int argc, MBJSValueConst *argv)
{
    double x, lo, hi, r;
    if (argc < 3)
        return MBJS_ThrowTypeError(ctx, "clamp needs 3 arguments");
    if (MBJS_ToFloat64(ctx, &x, argv[0]) ||
        MBJS_ToFloat64(ctx, &lo, argv[1]) ||
        MBJS_ToFloat64(ctx, &hi, argv[2]))
        return MBJS_EXCEPTION;
    if (lo > hi) { double t = lo; lo = hi; hi = t; }
    r = x < lo ? lo : x;
    r = r > hi ? hi : r;
    return mbjs_float64(r);
}

