/* Date */

/* OS dependent. d = argv[0] is in ms from 1970. Return the difference
   between UTC time and local time 'd' in minutes */
static int getTimezoneOffset(int64_t time) {
#if defined(_WIN32)
    DWORD r;
    TIME_ZONE_INFORMATION t;
    r = GetTimeZoneInformation(&t);
    if (r == TIME_ZONE_ID_INVALID)
        return 0;
    if (r == TIME_ZONE_ID_DAYLIGHT)
         return (int)(t.Bias + t.DaylightBias);
    return (int)t.Bias;
#else
    time_t ti;
    struct tm tm;

    time /= 1000; /* convert to seconds */
    if (sizeof(time_t) == 4) {
        /* on 32-bit systems, we need to clamp the time value to the
           range of `time_t`. This is better than truncating values to
           32 bits and hopefully provides the same result as 64-bit
           implementation of localtime_r.
         */
        if ((time_t)-1 < 0) {
            if (time < INT32_MIN) {
                time = INT32_MIN;
            } else if (time > INT32_MAX) {
                time = INT32_MAX;
            }
        } else {
            if (time < 0) {
                time = 0;
            } else if (time > UINT32_MAX) {
                time = UINT32_MAX;
            }
        }
    }
    ti = time;
    localtime_r(&ti, &tm);
#ifdef NO_TM_GMTOFF
    struct tm gmt;
    gmtime_r(&ti, &gmt);

    /* disable DST adjustment on the local tm struct */
    tm.tm_isdst = 0;

    return (int)difftime(mktime(&gmt), mktime(&tm)) / 60;
#else
    return -tm.tm_gmtoff / 60;
#endif /* NO_TM_GMTOFF */
#endif
}

/* RegExp */

static void mbjs_regexp_finalizer(MBJSRuntime *rt, MBJSValueConst val)
{
    MBJSObject *p = MBJS_VALUE_GET_OBJ(val);
    MBJSRegExp *re = &p->u.regexp;
    MBJS_FreeValueRT(rt, MBJS_MKPTR(MBJS_TAG_STRING, re->bytecode));
    MBJS_FreeValueRT(rt, MBJS_MKPTR(MBJS_TAG_STRING, re->pattern));
}

/* create a string containing the RegExp bytecode */
static MBJSValue mbjs_compile_regexp(MBJSContext *ctx, MBJSValueConst pattern,
                                 MBJSValueConst flags)
{
    const char *str;
    int re_flags, mask;
    uint8_t *re_bytecode_buf;
    size_t i, len;
    int re_bytecode_len;
    MBJSValue ret;
    char error_msg[64];

    re_flags = 0;
    if (!MBJS_IsUndefined(flags)) {
        str = MBJS_ToCStringLen(ctx, &len, flags);
        if (!str)
            return MBJS_EXCEPTION;
        /* XXX: re_flags = LRE_FLAG_OCTAL unless strict mode? */
        for (i = 0; i < len; i++) {
            switch(str[i]) {
            case 'd':
                mask = LRE_FLAG_INDICES;
                break;
            case 'g':
                mask = LRE_FLAG_GLOBAL;
                break;
            case 'i':
                mask = LRE_FLAG_IGNORECASE;
                break;
            case 'm':
                mask = LRE_FLAG_MULTILINE;
                break;
            case 's':
                mask = LRE_FLAG_DOTALL;
                break;
            case 'u':
                mask = LRE_FLAG_UNICODE;
                break;
            case 'v':
                mask = LRE_FLAG_UNICODE_SETS;
                break;
            case 'y':
                mask = LRE_FLAG_STICKY;
                break;
            default:
                goto bad_flags;
            }
            if ((re_flags & mask) != 0) {
            bad_flags:
                MBJS_FreeCString(ctx, str);
                return MBJS_ThrowSyntaxError(ctx, "invalid regular expression flags");
            }
            re_flags |= mask;
        }
        MBJS_FreeCString(ctx, str);
    }

    if (re_flags & LRE_FLAG_UNICODE)
        if (re_flags & LRE_FLAG_UNICODE_SETS)
            return MBJS_ThrowSyntaxError(ctx, "invalid regular expression flags");

    /* The v flag implies full Unicode, like u, so the pattern must be
       UTF-8 (not CESU-8) for both. */
    str = MBJS_ToCStringLen2(ctx, &len, pattern,
                           !(re_flags & (LRE_FLAG_UNICODE | LRE_FLAG_UNICODE_SETS)));
    if (!str)
        return MBJS_EXCEPTION;
    re_bytecode_buf = lre_compile(&re_bytecode_len, error_msg,
                                  sizeof(error_msg), str, len, re_flags, ctx);
    MBJS_FreeCString(ctx, str);
    if (!re_bytecode_buf) {
        MBJS_ThrowSyntaxError(ctx, "%s", error_msg);
        return MBJS_EXCEPTION;
    }

    ret = mbjs_new_string8_len(ctx, (void *)&re_bytecode_buf,
                             sizeof(re_bytecode_buf));
    if (MBJS_IsException(ret)) {
        mbjs_free(ctx, re_bytecode_buf);
    } else {
        MBJSString *p = MBJS_VALUE_GET_STRING(ret);
        p->kind = MBJS_STRING_KIND_INDIRECT;
        p->len = re_bytecode_len;
    }
    return ret;
}

/* create a RegExp object from a string containing the RegExp bytecode
   and the source pattern */
static MBJSValue mbjs_regexp_constructor_internal(MBJSContext *ctx, MBJSValueConst ctor,
                                              MBJSValue pattern, MBJSValue bc)
{
    MBJSValue obj;
    MBJSObject *p;
    MBJSRegExp *re;
    MBJSProperty prop;

    /* sanity check */
    if (MBJS_VALUE_GET_TAG(bc) != MBJS_TAG_STRING ||
        MBJS_VALUE_GET_TAG(pattern) != MBJS_TAG_STRING) {
        MBJS_ThrowTypeError(ctx, "string expected");
        goto fail;
    }
    prop.u.value = mbjs_int32(0); // lastIndex
    if (ctx->regexp_shape && MBJS_IsUndefined(ctor)) {
        obj = MBJS_NewObjectFromShape(ctx, mbjs_dup_shape(ctx->regexp_shape),
                                    MBJS_CLASS_REGEXP, &prop);
        if (MBJS_IsException(obj))
            goto fail;
    } else {
        obj = mbjs_create_from_ctor(ctx, ctor, MBJS_CLASS_REGEXP);
        if (MBJS_IsException(obj))
            goto fail;
        MBJS_DefinePropertyValue(ctx, obj, MBJS_ATOM_lastIndex, prop.u.value,
                               MBJS_PROP_WRITABLE);
    }
    p = MBJS_VALUE_GET_OBJ(obj);
    re = &p->u.regexp;
    re->pattern = MBJS_VALUE_GET_STRING(pattern);
    re->bytecode = MBJS_VALUE_GET_STRING(bc);
    return obj;
fail:
    MBJS_FreeValue(ctx, bc);
    MBJS_FreeValue(ctx, pattern);
    return MBJS_EXCEPTION;
}

static MBJSRegExp *mbjs_get_regexp(MBJSContext *ctx, MBJSValueConst obj,
                               bool throw_error)
{
    if (MBJS_VALUE_GET_TAG(obj) == MBJS_TAG_OBJECT) {
        MBJSObject *p = MBJS_VALUE_GET_OBJ(obj);
        if (p->class_id == MBJS_CLASS_REGEXP)
            return &p->u.regexp;
    }
    if (throw_error) {
        MBJS_ThrowTypeErrorInvalidClass(ctx, MBJS_CLASS_REGEXP);
    }
    return NULL;
}

/* return < 0 if exception or true/false */
static int mbjs_is_regexp(MBJSContext *ctx, MBJSValueConst obj)
{
    MBJSValue m;

    if (!MBJS_IsObject(obj))
        return false;
    m = MBJS_GetProperty(ctx, obj, MBJS_ATOM_Symbol_match);
    if (MBJS_IsException(m))
        return -1;
    if (!MBJS_IsUndefined(m))
        return MBJS_ToBoolFree(ctx, m);
    return mbjs_get_regexp(ctx, obj, false) != NULL;
}

static MBJSValue mbjs_regexp_constructor(MBJSContext *ctx, MBJSValueConst new_target,
                                     int argc, MBJSValueConst *argv)
{
    MBJSValue pattern, flags, bc, val;
    MBJSValueConst pat, flags1;
    MBJSRegExp *re;
    int pat_is_regexp;

    pat = argv[0];
    flags1 = argv[1];
    pat_is_regexp = mbjs_is_regexp(ctx, pat);
    if (pat_is_regexp < 0)
        return MBJS_EXCEPTION;
    if (MBJS_IsUndefined(new_target)) {
        /* called as a function */
        new_target = MBJS_GetActiveFunction(ctx);
        if (pat_is_regexp && MBJS_IsUndefined(flags1)) {
            MBJSValue ctor;
            bool res;
            ctor = MBJS_GetProperty(ctx, pat, MBJS_ATOM_constructor);
            if (MBJS_IsException(ctor))
                return ctor;
            res = mbjs_same_value(ctx, ctor, new_target);
            MBJS_FreeValue(ctx, ctor);
            if (res)
                return mbjs_dup(pat);
        }
    }
    re = mbjs_get_regexp(ctx, pat, false);
    if (re) {
        pattern = mbjs_dup(MBJS_MKPTR(MBJS_TAG_STRING, re->pattern));
        if (MBJS_IsUndefined(flags1)) {
            bc = mbjs_dup(MBJS_MKPTR(MBJS_TAG_STRING, re->bytecode));
            goto no_compilation;
        } else {
            flags = MBJS_ToString(ctx, flags1);
            if (MBJS_IsException(flags))
                goto fail;
        }
    } else {
        flags = MBJS_UNDEFINED;
        if (pat_is_regexp) {
            pattern = MBJS_GetProperty(ctx, pat, MBJS_ATOM_source);
            if (MBJS_IsException(pattern))
                goto fail;
            if (MBJS_IsUndefined(flags1)) {
                flags = MBJS_GetProperty(ctx, pat, MBJS_ATOM_flags);
                if (MBJS_IsException(flags))
                    goto fail;
            } else {
                flags = mbjs_dup(flags1);
            }
        } else {
            pattern = mbjs_dup(pat);
            flags = mbjs_dup(flags1);
        }
        if (MBJS_IsUndefined(pattern)) {
            pattern = mbjs_empty_string(ctx->rt);
        } else {
            val = pattern;
            pattern = MBJS_ToString(ctx, val);
            MBJS_FreeValue(ctx, val);
            if (MBJS_IsException(pattern))
                goto fail;
        }
    }
    bc = mbjs_compile_regexp(ctx, pattern, flags);
    if (MBJS_IsException(bc))
        goto fail;
    MBJS_FreeValue(ctx, flags);
 no_compilation:
    return mbjs_regexp_constructor_internal(ctx, new_target, pattern, bc);
 fail:
    MBJS_FreeValue(ctx, pattern);
    MBJS_FreeValue(ctx, flags);
    return MBJS_EXCEPTION;
}

static MBJSValue mbjs_regexp_compile(MBJSContext *ctx, MBJSValueConst this_val,
                                 int argc, MBJSValueConst *argv)
{
    MBJSRegExp *re1, *re;
    MBJSValueConst pattern1, flags1;
    MBJSValue bc, pattern;

    re = mbjs_get_regexp(ctx, this_val, true);
    if (!re)
        return MBJS_EXCEPTION;
    pattern1 = argv[0];
    flags1 = argv[1];
    re1 = mbjs_get_regexp(ctx, pattern1, false);
    if (re1) {
        if (!MBJS_IsUndefined(flags1))
            return MBJS_ThrowTypeError(ctx, "flags must be undefined");
        pattern = mbjs_dup(MBJS_MKPTR(MBJS_TAG_STRING, re1->pattern));
        bc = mbjs_dup(MBJS_MKPTR(MBJS_TAG_STRING, re1->bytecode));
    } else {
        bc = MBJS_UNDEFINED;
        if (MBJS_IsUndefined(pattern1))
            pattern = mbjs_empty_string(ctx->rt);
        else
            pattern = MBJS_ToString(ctx, pattern1);
        if (MBJS_IsException(pattern))
            goto fail;
        bc = mbjs_compile_regexp(ctx, pattern, flags1);
        if (MBJS_IsException(bc))
            goto fail;
    }
    MBJS_FreeValue(ctx, MBJS_MKPTR(MBJS_TAG_STRING, re->pattern));
    MBJS_FreeValue(ctx, MBJS_MKPTR(MBJS_TAG_STRING, re->bytecode));
    re->pattern = MBJS_VALUE_GET_STRING(pattern);
    re->bytecode = MBJS_VALUE_GET_STRING(bc);
    if (MBJS_SetProperty(ctx, this_val, MBJS_ATOM_lastIndex,
                       mbjs_int32(0)) < 0)
        return MBJS_EXCEPTION;
    return mbjs_dup(this_val);
 fail:
    MBJS_FreeValue(ctx, pattern);
    MBJS_FreeValue(ctx, bc);
    return MBJS_EXCEPTION;
}

static MBJSValue mbjs_regexp_get_source(MBJSContext *ctx, MBJSValueConst this_val)
{
    MBJSRegExp *re;
    MBJSString *p;
    StringBuffer b_s, *b = &b_s;
    int i, n, c, c2, bra;

    if (MBJS_VALUE_GET_TAG(this_val) != MBJS_TAG_OBJECT)
        return MBJS_ThrowTypeErrorNotAnObject(ctx);

    if (mbjs_same_value(ctx, this_val, ctx->class_proto[MBJS_CLASS_REGEXP]))
        goto empty_regex;

    re = mbjs_get_regexp(ctx, this_val, true);
    if (!re)
        return MBJS_EXCEPTION;

    p = re->pattern;

    if (p->len == 0) {
    empty_regex:
        return mbjs_new_string8(ctx, "(?:)");
    }
    string_buffer_init2(ctx, b, p->len, p->is_wide_char);

    /* Escape '/' and newline sequences as needed */
    bra = 0;
    for (i = 0, n = p->len; i < n;) {
        c2 = -1;
        switch (c = string_get(p, i++)) {
        case '\\':
            if (i < n)
                c2 = string_get(p, i++);
            break;
        case ']':
            bra = 0;
            break;
        case '[':
            if (!bra) {
                if (i < n && string_get(p, i) == ']')
                    c2 = string_get(p, i++);
                bra = 1;
            }
            break;
        case '\n':
            c = '\\';
            c2 = 'n';
            break;
        case '\r':
            c = '\\';
            c2 = 'r';
            break;
        case '/':
            if (!bra) {
                c = '\\';
                c2 = '/';
            }
            break;
        }
        string_buffer_putc16(b, c);
        if (c2 >= 0)
            string_buffer_putc16(b, c2);
    }
    return string_buffer_end(b);
}

static MBJSValue mbjs_regexp_get_flag(MBJSContext *ctx, MBJSValueConst this_val, int mask)
{
    MBJSRegExp *re;
    int flags;

    if (MBJS_VALUE_GET_TAG(this_val) != MBJS_TAG_OBJECT)
        return MBJS_ThrowTypeErrorNotAnObject(ctx);

    re = mbjs_get_regexp(ctx, this_val, false);
    if (!re) {
        if (mbjs_same_value(ctx, this_val, ctx->class_proto[MBJS_CLASS_REGEXP]))
            return MBJS_UNDEFINED;
        else
            return MBJS_ThrowTypeErrorInvalidClass(ctx, MBJS_CLASS_REGEXP);
    }

    flags = lre_get_flags(str8(re->bytecode));
    return mbjs_bool(flags & mask);
}

static MBJSValue mbjs_regexp_get_flags(MBJSContext *ctx, MBJSValueConst this_val)
{
    char str[8], *p = str;
    int res;

    if (MBJS_VALUE_GET_TAG(this_val) != MBJS_TAG_OBJECT)
        return MBJS_ThrowTypeErrorNotAnObject(ctx);

    res = MBJS_ToBoolFree(ctx, MBJS_GetPropertyStr(ctx, this_val, "hasIndices"));
    if (res < 0)
        goto exception;
    if (res)
        *p++ = 'd';
    res = MBJS_ToBoolFree(ctx, MBJS_GetProperty(ctx, this_val, MBJS_ATOM_global));
    if (res < 0)
        goto exception;
    if (res)
        *p++ = 'g';
    res = MBJS_ToBoolFree(ctx, MBJS_GetPropertyStr(ctx, this_val, "ignoreCase"));
    if (res < 0)
        goto exception;
    if (res)
        *p++ = 'i';
    res = MBJS_ToBoolFree(ctx, MBJS_GetPropertyStr(ctx, this_val, "multiline"));
    if (res < 0)
        goto exception;
    if (res)
        *p++ = 'm';
    res = MBJS_ToBoolFree(ctx, MBJS_GetPropertyStr(ctx, this_val, "dotAll"));
    if (res < 0)
        goto exception;
    if (res)
        *p++ = 's';
    res = MBJS_ToBoolFree(ctx, MBJS_GetProperty(ctx, this_val, MBJS_ATOM_unicode));
    if (res < 0)
        goto exception;
    if (res)
        *p++ = 'u';
    res = MBJS_ToBoolFree(ctx, MBJS_GetPropertyStr(ctx, this_val, "unicodeSets"));
    if (res < 0)
        goto exception;
    if (res)
        *p++ = 'v';
    res = MBJS_ToBoolFree(ctx, MBJS_GetPropertyStr(ctx, this_val, "sticky"));
    if (res < 0)
        goto exception;
    if (res)
        *p++ = 'y';
    if (p == str)
        return mbjs_empty_string(ctx->rt);
    return mbjs_new_string8_len(ctx, str, p - str);

exception:
    return MBJS_EXCEPTION;
}

static MBJSValue mbjs_regexp_toString(MBJSContext *ctx, MBJSValueConst this_val,
                                  int argc, MBJSValueConst *argv)
{
    MBJSValue pattern, flags;
    StringBuffer b_s, *b = &b_s;

    if (!MBJS_IsObject(this_val))
        return MBJS_ThrowTypeErrorNotAnObject(ctx);

    string_buffer_init(ctx, b, 0);
    string_buffer_putc8(b, '/');
    pattern = MBJS_GetProperty(ctx, this_val, MBJS_ATOM_source);
    if (string_buffer_concat_value_free(b, pattern))
        goto fail;
    string_buffer_putc8(b, '/');
    flags = MBJS_GetProperty(ctx, this_val, MBJS_ATOM_flags);
    if (string_buffer_concat_value_free(b, flags))
        goto fail;
    return string_buffer_end(b);

fail:
    string_buffer_free(b);
    return MBJS_EXCEPTION;
}

bool lre_check_stack_overflow(void *opaque, size_t alloca_size)
{
    MBJSContext *ctx = opaque;
    return mbjs_check_stack_overflow(ctx->rt, alloca_size);
}

int lre_check_timeout(void *opaque)
{
    MBJSContext *ctx = opaque;
    MBJSRuntime *rt = ctx->rt;
    return (rt->interrupt_handler &&
            rt->interrupt_handler(ctx, rt->interrupt_opaque));
}

void *lre_realloc(void *opaque, void *ptr, size_t size)
{
    MBJSContext *ctx = opaque;
    /* No JS exception is raised here */
    return mbjs_realloc_rt(ctx->rt, ptr, size);
}

/* RegExp.escape helpers, ES2025 22.2.1.1 (sec-encodeforregexescape).
   These deliberately do not use strchr()/lre_is_white_space(): the code
   point is not necessarily a single byte, and Unicode's White_Space
   property is not the same set as the ECMAScript WhiteSpace production
   (it contains U+0085, which the WhiteSpace production does not). */

/* Table 64 "ControlEscape": returns the control escape letter for c, 0 if
   c is not a control character with a dedicated escape. */
static int mbjs_regexp_escape_control(uint32_t c)
{
    switch (c) {
    case 0x09: return 't';
    case 0x0A: return 'n';
    case 0x0B: return 'v';
    case 0x0C: return 'f';
    case 0x0D: return 'r';
    default: return 0;
    }
}

/* SyntaxCharacter or U+002F (SOLIDUS) */
static bool mbjs_regexp_escape_syntax(uint32_t c)
{
    switch (c) {
    case '^': case '$': case '\\': case '.': case '*': case '+':
    case '?': case '(': case ')': case '[': case ']': case '{':
    case '}': case '|': case '/':
        return true;
    default:
        return false;
    }
}

/* "otherPunctuators": , - = < > # & ! % : ; @ ~ ` ' " */
static bool mbjs_regexp_escape_other_punctuator(uint32_t c)
{
    switch (c) {
    case ',': case '-': case '=': case '<': case '>': case '#':
    case '&': case '!': case '%': case ':': case ';': case '@':
    case '~': case '`': case '\'': case '"':
        return true;
    default:
        return false;
    }
}

/* WhiteSpace or LineTerminator of the ECMAScript lexical grammar:
   <TAB> <VT> <FF> <ZWNBSP> <USP> and <LF> <CR> <LS> <PS>. */
static bool mbjs_regexp_escape_white_space(uint32_t c)
{
    switch (c) {
    case 0x09: case 0x0A: case 0x0B: case 0x0C: case 0x0D:
    case 0x20: case 0xA0: case 0x1680:
    case 0x2000: case 0x2001: case 0x2002: case 0x2003:
    case 0x2004: case 0x2005: case 0x2006: case 0x2007:
    case 0x2008: case 0x2009: case 0x200A:
    case 0x2028: case 0x2029: case 0x202F: case 0x205F: case 0x3000:
    case 0xFEFF:
        return true;
    default:
        return false;
    }
}

static MBJSValue mbjs_regexp_escape(MBJSContext *ctx, MBJSValueConst this_val,
                                int argc, MBJSValueConst *argv)
{
    StringBuffer b_s, *b = &b_s;
    MBJSValue str, ret;
    MBJSString *p;
    uint32_t c, i;
    char s[16];
    bool first;

    if (!MBJS_IsString(argv[0]))
        return MBJS_ThrowTypeError(ctx, "not a string");
    if (MBJS_VALUE_GET_TAG(argv[0]) == MBJS_TAG_STRING_ROPE) {
        str = mbjs_linearize_string_rope(ctx, argv[0]);
        if (MBJS_IsException(str))
            return MBJS_EXCEPTION;
    } else {
        str = mbjs_dup(argv[0]);
    }
    p = MBJS_VALUE_GET_STRING(str);
    string_buffer_init2(ctx, b, 0, p->is_wide_char);
    first = true;
    for (i = 0; i < p->len; i++) {
        c = p->is_wide_char ? (uint32_t)str16(p)[i] : (uint32_t)str8(p)[i];
        if (p->is_wide_char && is_hi_surrogate(c) && i + 1 < p->len &&
            is_lo_surrogate((uint32_t)str16(p)[i + 1])) {
            /* astral code point (surrogate pair): emitted as-is */
            string_buffer_putc16(b, c);
            string_buffer_putc16(b, str16(p)[i + 1]);
            i++;
            first = false;
            continue;
        }
        if (first) {
            first = false;
            if ((c >= '0' && c <= '9') ||
                (c >= 'A' && c <= 'Z') ||
                (c >= 'a' && c <= 'z')) {
                /* RegExp.escape step 4.a: escape an initial DecimalDigit or
                   AsciiLetter so the result cannot extend a preceding
                   numeric escape. */
                snprintf(s, sizeof(s), "\\x%02x", c);
                string_buffer_puts8(b, s);
                continue;
            }
        }
        if (mbjs_regexp_escape_syntax(c)) {
            /* EncodeForRegExpEscape step 1 */
            string_buffer_putc8(b, '\\');
            string_buffer_putc16(b, c);
            continue;
        }
        {
            int ctrl = mbjs_regexp_escape_control(c);
            if (ctrl) {
                /* EncodeForRegExpEscape step 2 (Table 64) */
                string_buffer_putc8(b, '\\');
                string_buffer_putc8(b, ctrl);
                continue;
            }
        }
        if (mbjs_regexp_escape_other_punctuator(c) ||
            mbjs_regexp_escape_white_space(c) ||
            is_surrogate(c)) {
            /* EncodeForRegExpEscape step 5 */
            if (c <= 0xFF)
                snprintf(s, sizeof(s), "\\x%02x", c);
            else
                snprintf(s, sizeof(s), "\\u%04x", c);
            string_buffer_puts8(b, s);
            continue;
        }
        /* EncodeForRegExpEscape step 6: the code point is emitted as-is */
        string_buffer_putc16(b, c);
    }
    ret = string_buffer_end(b);
    MBJS_FreeValue(ctx, str);
    return ret;
}

static MBJSValue mbjs_regexp_exec(MBJSContext *ctx, MBJSValueConst this_val,
                              int argc, MBJSValueConst *argv)
{
    int rc, capture_count, alloc_count, shift, index, i, re_flags, prop_flags;
    MBJSRegExp *re = mbjs_get_regexp(ctx, this_val, true);
    MBJSString *str;
    MBJSValue t, ret, str_val, obj, val, groups;
    MBJSValue indices, indices_groups;
    uint8_t *re_bytecode;
    uint8_t **capture, *str_buf;
    int64_t last_index;
    const char *group_name_ptr;
    MBJSAtom group_name;
    MBJSProperty props[4]; // length, index, input, groups, in that order

    if (!re)
        return MBJS_EXCEPTION;

    str_val = MBJS_ToString(ctx, argv[0]);
    if (MBJS_IsException(str_val))
        return MBJS_EXCEPTION;

    ret = MBJS_EXCEPTION;
    obj = MBJS_NULL;
    groups = MBJS_UNDEFINED;
    indices = MBJS_UNDEFINED;
    indices_groups = MBJS_UNDEFINED;
    group_name = MBJS_ATOM_NULL;
    capture = NULL;

    val = MBJS_GetProperty(ctx, this_val, MBJS_ATOM_lastIndex);
    if (MBJS_IsException(val) || MBJS_ToLengthFree(ctx, &last_index, val))
        goto fail;

    re_bytecode = str8(re->bytecode);
    re_flags = lre_get_flags(re_bytecode);
    if ((re_flags & (LRE_FLAG_GLOBAL | LRE_FLAG_STICKY)) == 0) {
        last_index = 0;
    }
    str = MBJS_VALUE_GET_STRING(str_val);
    capture_count = lre_get_capture_count(re_bytecode);
    /* The register-based executor writes capture positions AND temporary
       registers into the capture buffer; it must be sized by alloc_count
       (= capture_count*2 + register_count), not capture_count*2. Sizing it
       by capture_count*2 silently overflows the heap on any regexp that
       uses registers (i.e. most non-trivial patterns). */
    alloc_count = lre_get_alloc_count(re_bytecode);
    if (alloc_count > 0) {
        capture = mbjs_malloc(ctx, sizeof(capture[0]) * alloc_count);
        if (!capture)
            goto fail;
    }
    shift = str->is_wide_char;
    str_buf = str8(str);
    if (last_index > str->len) {
        rc = 2;
    } else {
        rc = lre_exec(capture, re_bytecode,
                      str_buf, last_index, str->len,
                      shift, ctx);
    }
    if (rc != 1) {
        if (rc >= 0) {
            if (rc == 2 || (re_flags & (LRE_FLAG_GLOBAL | LRE_FLAG_STICKY))) {
                if (MBJS_SetProperty(ctx, this_val, MBJS_ATOM_lastIndex,
                                   mbjs_int32(0)) < 0)
                    goto fail;
            }
        } else {
            switch(rc) {
            case LRE_RET_TIMEOUT:
                MBJS_ThrowInterrupted(ctx);
                break;
            case LRE_RET_MEMORY_ERROR:
                MBJS_ThrowOutOfMemory(ctx);
                break;
            case LRE_RET_BYTECODE_ERROR:
                MBJS_ThrowInternalError(ctx, "corrupted bytecode in regexp execution");
                break;
            default:
                abort();
            }
            goto fail;
        }
    } else {
        if (re_flags & (LRE_FLAG_GLOBAL | LRE_FLAG_STICKY)) {
            if (MBJS_SetProperty(ctx, this_val, MBJS_ATOM_lastIndex,
                               mbjs_int32((capture[1] - str_buf) >> shift)) < 0)
                goto fail;
        }
        group_name_ptr = lre_get_groupnames(re_bytecode);
        if (group_name_ptr) {
            groups = MBJS_NewObjectProto(ctx, MBJS_NULL);
            if (MBJS_IsException(groups))
                goto fail;
        }
        if (re_flags & LRE_FLAG_INDICES) {
            indices = MBJS_NewArray(ctx);
            if (MBJS_IsException(indices))
                goto fail;
            if (group_name_ptr) {
                indices_groups = MBJS_NewObjectProto(ctx, MBJS_NULL);
                if (MBJS_IsException(indices_groups))
                    goto fail;
            }
        }
        index = (capture[0] - str_buf) >> shift;
        props[0].u.value = mbjs_int32(capture_count); // length
        props[1].u.value = mbjs_int32(index);         // index
        props[2].u.value = str_val;                 // input
        props[3].u.value = mbjs_dup(groups);          // groups
        str_val = MBJS_UNDEFINED;
        obj = MBJS_NewObjectFromShape(ctx, mbjs_dup_shape(ctx->regexp_result_shape),
                                    MBJS_CLASS_ARRAY, props);
        if (MBJS_IsException(obj))
            goto fail;
        prop_flags = MBJS_PROP_C_W_E | MBJS_PROP_THROW;
        for(i = 0; i < capture_count; i++) {
            uint8_t **match = &capture[2 * i];
            int start = -1;
            int end = -1;

            if (group_name_ptr && i > 0) {
                if (*group_name_ptr) {
                    /* XXX: slow, should create a shape when the regexp is
                       compiled */
                    group_name = MBJS_NewAtom(ctx, group_name_ptr);
                    if (group_name == MBJS_ATOM_NULL)
                        goto fail;
                }
                group_name_ptr += strlen(group_name_ptr) + LRE_GROUP_NAME_TRAILER_LEN;
            }

            if (match[0] && match[1]) {
                start = (match[0] - str_buf) >> shift;
                end = (match[1] - str_buf) >> shift;
            }

            if (!MBJS_IsUndefined(indices)) {
                MBJSValue val = MBJS_UNDEFINED;
                if (start != -1) {
                    val = MBJS_NewArray(ctx);
                    if (MBJS_IsException(val))
                        goto fail;
                    if (MBJS_DefinePropertyValueUint32(ctx, val, 0,
                                                     mbjs_int32(start),
                                                     prop_flags) < 0) {
                        MBJS_FreeValue(ctx, val);
                        goto fail;
                    }
                    if (MBJS_DefinePropertyValueUint32(ctx, val, 1,
                                                     mbjs_int32(end),
                                                     prop_flags) < 0) {
                        MBJS_FreeValue(ctx, val);
                        goto fail;
                    }
                }
                if (group_name != MBJS_ATOM_NULL &&
                    !MBJS_IsUndefined(indices_groups)) {
                    /* For duplicate named groups, only the alternative that
                       actually matched (non-undefined) wins; a later
                       undefined alternative must not clobber it. */
                    if (!MBJS_IsUndefined(val) ||
                        !MBJS_HasProperty(ctx, indices_groups, group_name)) {
                        if (MBJS_DefinePropertyValue(ctx, indices_groups,
                                                   group_name, mbjs_dup(val),
                                                   prop_flags) < 0) {
                            MBJS_FreeValue(ctx, val);
                            goto fail;
                        }
                    }
                }
                if (MBJS_DefinePropertyValueUint32(ctx, indices, i, val,
                                                 prop_flags) < 0) {
                    goto fail;
                }
            }

            MBJSValue val = MBJS_UNDEFINED;
            if (start != -1) {
                val = mbjs_sub_string(ctx, str, start, end);
                if (MBJS_IsException(val))
                    goto fail;
            }

            if (group_name != MBJS_ATOM_NULL) {
                /* duplicate named groups: matched alternative wins (see above) */
                if (!MBJS_IsUndefined(val) ||
                    !MBJS_HasProperty(ctx, groups, group_name)) {
                    if (MBJS_DefinePropertyValue(ctx, groups, group_name,
                                               mbjs_dup(val), prop_flags) < 0) {
                        MBJS_FreeValue(ctx, val);
                        goto fail;
                    }
                }
                MBJS_FreeAtom(ctx, group_name);
                group_name = MBJS_ATOM_NULL;
            }

            if (MBJS_DefinePropertyValueUint32(ctx, obj, i, val, prop_flags) < 0)
                goto fail;
        }

        if (!MBJS_IsUndefined(indices)) {
            t = indices_groups, indices_groups = MBJS_UNDEFINED;
            if (MBJS_DefinePropertyValue(ctx, indices, MBJS_ATOM_groups,
                                       t, prop_flags) < 0) {
                goto fail;
            }
            t = indices, indices = MBJS_UNDEFINED;
            if (MBJS_DefinePropertyValue(ctx, obj, MBJS_ATOM_indices,
                                       t, prop_flags) < 0) {
                goto fail;
            }
        }
    }
    ret = obj;
    obj = MBJS_UNDEFINED;
fail:
    MBJS_FreeAtom(ctx, group_name);
    MBJS_FreeValue(ctx, indices_groups);
    MBJS_FreeValue(ctx, indices);
    MBJS_FreeValue(ctx, str_val);
    MBJS_FreeValue(ctx, groups);
    MBJS_FreeValue(ctx, obj);
    mbjs_free(ctx, capture);
    return ret;
}

/* delete portions of a string that match a given regex */
static MBJSValue MBJS_RegExpDelete(MBJSContext *ctx, MBJSValueConst this_val, MBJSValue arg)
{
    MBJSRegExp *re = mbjs_get_regexp(ctx, this_val, true);
    MBJSString *str;
    MBJSValue str_val, val;
    uint8_t *re_bytecode;
    int ret;
    uint8_t **capture, *str_buf;
    int alloc_count, shift, re_flags;
    int next_src_pos, start, end;
    int64_t last_index;
    StringBuffer b_s, *b = &b_s;

    if (!re)
        return MBJS_EXCEPTION;

    string_buffer_init(ctx, b, 0);

    capture = NULL;
    str_val = MBJS_ToString(ctx, arg);
    if (MBJS_IsException(str_val))
        goto fail;
    str = MBJS_VALUE_GET_STRING(str_val);
    re_bytecode = str8(re->bytecode);
    re_flags = lre_get_flags(re_bytecode);
    if ((re_flags & (LRE_FLAG_GLOBAL | LRE_FLAG_STICKY)) == 0) {
        last_index = 0;
    } else {
        val = MBJS_GetProperty(ctx, this_val, MBJS_ATOM_lastIndex);
        if (MBJS_IsException(val) || MBJS_ToLengthFree(ctx, &last_index, val))
            goto fail;
    }
    /* size by alloc_count: the register executor uses capture[] beyond
       the capture positions for its registers (see mbjs_regexp_exec). */
    alloc_count = lre_get_alloc_count(re_bytecode);
    if (alloc_count > 0) {
        capture = mbjs_malloc(ctx, sizeof(capture[0]) * alloc_count);
        if (!capture)
            goto fail;
    }
    shift = str->is_wide_char;
    str_buf = str8(str);
    next_src_pos = 0;
    for (;;) {
        if (last_index > str->len)
            break;

        ret = lre_exec(capture, re_bytecode,
                       str_buf, last_index, str->len, shift, ctx);
        if (ret != 1) {
            if (ret >= 0) {
                if (ret == 2 || (re_flags & (LRE_FLAG_GLOBAL | LRE_FLAG_STICKY))) {
                    if (MBJS_SetProperty(ctx, this_val, MBJS_ATOM_lastIndex,
                                       mbjs_int32(0)) < 0)
                        goto fail;
                }
            } else {
                switch(ret) {
                case LRE_RET_TIMEOUT:
                    MBJS_ThrowInterrupted(ctx);
                    break;
                case LRE_RET_MEMORY_ERROR:
                    MBJS_ThrowOutOfMemory(ctx);
                    break;
                case LRE_RET_BYTECODE_ERROR:
                    MBJS_ThrowInternalError(ctx, "corrupted bytecode in regexp execution");
                    break;
                default:
                    abort();
                }
                goto fail;
            }
            break;
        }
        start = (capture[0] - str_buf) >> shift;
        end = (capture[1] - str_buf) >> shift;
        last_index = end;
        if (next_src_pos < start) {
            if (string_buffer_concat(b, str, next_src_pos, start))
                goto fail;
        }
        next_src_pos = end;
        if (!(re_flags & LRE_FLAG_GLOBAL)) {
            if (MBJS_SetProperty(ctx, this_val, MBJS_ATOM_lastIndex,
                               mbjs_int32(end)) < 0)
                goto fail;
            break;
        }
        if (end == start) {
            if (!(re_flags & (LRE_FLAG_UNICODE | LRE_FLAG_UNICODE_SETS)) || (unsigned)end >= str->len || !str->is_wide_char) {
                end++;
            } else {
                string_getc(str, &end);
            }
        }
        last_index = end;
    }
    if (string_buffer_concat(b, str, next_src_pos, str->len))
        goto fail;
    MBJS_FreeValue(ctx, str_val);
    mbjs_free(ctx, capture);
    return string_buffer_end(b);
fail:
    MBJS_FreeValue(ctx, str_val);
    mbjs_free(ctx, capture);
    string_buffer_free(b);
    return MBJS_EXCEPTION;
}

static MBJSValue MBJS_RegExpExec(MBJSContext *ctx, MBJSValueConst r, MBJSValueConst s)
{
    MBJSValue method, ret;

    method = MBJS_GetProperty(ctx, r, MBJS_ATOM_exec);
    if (MBJS_IsException(method))
        return method;
    if (MBJS_IsFunction(ctx, method)) {
        ret = MBJS_CallFree(ctx, method, r, 1, &s);
        if (MBJS_IsException(ret))
            return ret;
        if (!MBJS_IsObject(ret) && !MBJS_IsNull(ret)) {
            MBJS_FreeValue(ctx, ret);
            return MBJS_ThrowTypeError(ctx, "RegExp exec method must return an object or null");
        }
        return ret;
    }
    MBJS_FreeValue(ctx, method);
    return mbjs_regexp_exec(ctx, r, 1, &s);
}

static MBJSValue mbjs_regexp_test(MBJSContext *ctx, MBJSValueConst this_val,
                              int argc, MBJSValueConst *argv)
{
    MBJSValue val;
    bool ret;

    val = MBJS_RegExpExec(ctx, this_val, argv[0]);
    if (MBJS_IsException(val))
        return MBJS_EXCEPTION;
    ret = !MBJS_IsNull(val);
    MBJS_FreeValue(ctx, val);
    return mbjs_bool(ret);
}

static MBJSValue mbjs_regexp_Symbol_match(MBJSContext *ctx, MBJSValueConst this_val,
                                      int argc, MBJSValueConst *argv)
{
    // [Symbol.match](str)
    MBJSValueConst rx = this_val;
    MBJSValue A, S, flags, result, matchStr;
    int global, n, fullUnicode, isEmpty;
    MBJSString *p;

    if (!MBJS_IsObject(rx))
        return MBJS_ThrowTypeErrorNotAnObject(ctx);

    A = MBJS_UNDEFINED;
    flags = MBJS_UNDEFINED;
    result = MBJS_UNDEFINED;
    matchStr = MBJS_UNDEFINED;
    S = MBJS_ToString(ctx, argv[0]);
    if (MBJS_IsException(S))
        goto exception;

    flags = MBJS_GetProperty(ctx, rx, MBJS_ATOM_flags);
    if (MBJS_IsException(flags))
        goto exception;
    flags = MBJS_ToStringFree(ctx, flags);
    if (MBJS_IsException(flags))
        goto exception;
    p = MBJS_VALUE_GET_STRING(flags);

    global = (-1 != string_indexof_char(p, 'g', 0));
    if (!global) {
        A = MBJS_RegExpExec(ctx, rx, S);
    } else {
        // 'v' flag implies full Unicode, like 'u'
        fullUnicode = (string_indexof_char(p, 'u', 0) >= 0 ||
                       string_indexof_char(p, 'v', 0) >= 0);

        if (MBJS_SetProperty(ctx, rx, MBJS_ATOM_lastIndex, mbjs_int32(0)) < 0)
            goto exception;
        A = MBJS_NewArray(ctx);
        if (MBJS_IsException(A))
            goto exception;
        n = 0;
        for(;;) {
            MBJS_FreeValue(ctx, result);
            result = MBJS_RegExpExec(ctx, rx, S);
            if (MBJS_IsException(result))
                goto exception;
            if (MBJS_IsNull(result))
                break;
            matchStr = MBJS_ToStringFree(ctx, MBJS_GetPropertyInt64(ctx, result, 0));
            if (MBJS_IsException(matchStr))
                goto exception;
            isEmpty = MBJS_IsEmptyString(matchStr);
            if (MBJS_SetPropertyInt64(ctx, A, n++, matchStr) < 0)
                goto exception;
            if (isEmpty) {
                int64_t thisIndex, nextIndex;
                if (MBJS_ToLengthFree(ctx, &thisIndex,
                                    MBJS_GetProperty(ctx, rx, MBJS_ATOM_lastIndex)) < 0)
                    goto exception;
                p = MBJS_VALUE_GET_STRING(S);
                nextIndex = string_advance_index(p, thisIndex, fullUnicode);
                if (MBJS_SetProperty(ctx, rx, MBJS_ATOM_lastIndex, mbjs_int64(nextIndex)) < 0)
                    goto exception;
            }
        }
        if (n == 0) {
            MBJS_FreeValue(ctx, A);
            A = MBJS_NULL;
        }
    }
    MBJS_FreeValue(ctx, result);
    MBJS_FreeValue(ctx, flags);
    MBJS_FreeValue(ctx, S);
    return A;

exception:
    MBJS_FreeValue(ctx, A);
    MBJS_FreeValue(ctx, result);
    MBJS_FreeValue(ctx, flags);
    MBJS_FreeValue(ctx, S);
    return MBJS_EXCEPTION;
}

typedef struct MBJSRegExpStringIteratorData {
    MBJSValue iterating_regexp;
    MBJSValue iterated_string;
    bool global;
    bool unicode;
    int done;
} MBJSRegExpStringIteratorData;

static void mbjs_regexp_string_iterator_finalizer(MBJSRuntime *rt,
                                                MBJSValueConst val)
{
    MBJSObject *p = MBJS_VALUE_GET_OBJ(val);
    MBJSRegExpStringIteratorData *it = p->u.regexp_string_iterator_data;
    if (it) {
        MBJS_FreeValueRT(rt, it->iterating_regexp);
        MBJS_FreeValueRT(rt, it->iterated_string);
        mbjs_free_rt(rt, it);
    }
}

static void mbjs_regexp_string_iterator_mark(MBJSRuntime *rt, MBJSValueConst val,
                                           MBJS_MarkFunc *mark_func)
{
    MBJSObject *p = MBJS_VALUE_GET_OBJ(val);
    MBJSRegExpStringIteratorData *it = p->u.regexp_string_iterator_data;
    if (it) {
        MBJS_MarkValue(rt, it->iterating_regexp, mark_func);
        MBJS_MarkValue(rt, it->iterated_string, mark_func);
    }
}

static MBJSValue mbjs_regexp_string_iterator_next(MBJSContext *ctx,
                                              MBJSValueConst this_val,
                                              int argc, MBJSValueConst *argv,
                                              int *pdone, int magic)
{
    MBJSRegExpStringIteratorData *it;
    MBJSValue R, S;
    MBJSValue matchStr = MBJS_UNDEFINED, match = MBJS_UNDEFINED;
    MBJSString *sp;

    it = MBJS_GetOpaque2(ctx, this_val, MBJS_CLASS_REGEXP_STRING_ITERATOR);
    if (!it)
        goto exception;
    if (it->done) {
        *pdone = true;
        return MBJS_UNDEFINED;
    }
    R = it->iterating_regexp;
    S = it->iterated_string;
    match = MBJS_RegExpExec(ctx, R, S);
    if (MBJS_IsException(match))
        goto exception;
    if (MBJS_IsNull(match)) {
        it->done = true;
        *pdone = true;
        return MBJS_UNDEFINED;
    } else if (it->global) {
        matchStr = MBJS_ToStringFree(ctx, MBJS_GetPropertyInt64(ctx, match, 0));
        if (MBJS_IsException(matchStr))
            goto exception;
        if (MBJS_IsEmptyString(matchStr)) {
            int64_t thisIndex, nextIndex;
            if (MBJS_ToLengthFree(ctx, &thisIndex,
                                MBJS_GetProperty(ctx, R, MBJS_ATOM_lastIndex)) < 0)
                goto exception;
            sp = MBJS_VALUE_GET_STRING(S);
            nextIndex = string_advance_index(sp, thisIndex, it->unicode);
            if (MBJS_SetProperty(ctx, R, MBJS_ATOM_lastIndex, mbjs_int64(nextIndex)) < 0)
                goto exception;
        }
        MBJS_FreeValue(ctx, matchStr);
    } else {
        it->done = true;
    }
    *pdone = false;
    return match;
 exception:
    MBJS_FreeValue(ctx, match);
    MBJS_FreeValue(ctx, matchStr);
    *pdone = false;
    return MBJS_EXCEPTION;
}

static MBJSValue mbjs_regexp_Symbol_matchAll(MBJSContext *ctx, MBJSValueConst this_val,
                                         int argc, MBJSValueConst *argv)
{
    // [Symbol.matchAll](str)
    MBJSValueConst R = this_val;
    MBJSValue S, C, flags, matcher, iter;
    MBJSValueConst args[2];
    MBJSString *strp;
    int64_t lastIndex;
    MBJSRegExpStringIteratorData *it;

    if (!MBJS_IsObject(R))
        return MBJS_ThrowTypeErrorNotAnObject(ctx);

    C = MBJS_UNDEFINED;
    flags = MBJS_UNDEFINED;
    matcher = MBJS_UNDEFINED;
    iter = MBJS_UNDEFINED;

    S = MBJS_ToString(ctx, argv[0]);
    if (MBJS_IsException(S))
        goto exception;
    C = MBJS_SpeciesConstructor(ctx, R, ctx->regexp_ctor);
    if (MBJS_IsException(C))
        goto exception;
    flags = MBJS_ToStringFree(ctx, MBJS_GetProperty(ctx, R, MBJS_ATOM_flags));
    if (MBJS_IsException(flags))
        goto exception;
    args[0] = R;
    args[1] = flags;
    matcher = MBJS_CallConstructor(ctx, C, 2, args);
    if (MBJS_IsException(matcher))
        goto exception;
    if (MBJS_ToLengthFree(ctx, &lastIndex,
                        MBJS_GetProperty(ctx, R, MBJS_ATOM_lastIndex)))
        goto exception;
    if (MBJS_SetProperty(ctx, matcher, MBJS_ATOM_lastIndex, mbjs_int64(lastIndex)) < 0)
        goto exception;

    iter = MBJS_NewObjectClass(ctx, MBJS_CLASS_REGEXP_STRING_ITERATOR);
    if (MBJS_IsException(iter))
        goto exception;
    it = mbjs_malloc(ctx, sizeof(*it));
    if (!it)
        goto exception;
    it->iterating_regexp = matcher;
    it->iterated_string = S;
    strp = MBJS_VALUE_GET_STRING(flags);
    it->global = string_indexof_char(strp, 'g', 0) >= 0;
    it->unicode = string_indexof_char(strp, 'u', 0) >= 0 ||
                  string_indexof_char(strp, 'v', 0) >= 0;
    it->done = false;
    MBJS_SetOpaqueInternal(iter, it);

    MBJS_FreeValue(ctx, C);
    MBJS_FreeValue(ctx, flags);
    return iter;
 exception:
    MBJS_FreeValue(ctx, S);
    MBJS_FreeValue(ctx, C);
    MBJS_FreeValue(ctx, flags);
    MBJS_FreeValue(ctx, matcher);
    MBJS_FreeValue(ctx, iter);
    return MBJS_EXCEPTION;
}

typedef struct ValueBuffer {
    MBJSContext *ctx;
    MBJSValue *arr;
    MBJSValue def[4];
    int len;
    int size;
    int error_status;
} ValueBuffer;

static int value_buffer_init(MBJSContext *ctx, ValueBuffer *b)
{
    b->ctx = ctx;
    b->len = 0;
    b->size = 4;
    b->error_status = 0;
    b->arr = b->def;
    return 0;
}

static void value_buffer_free(ValueBuffer *b)
{
    while (b->len > 0)
        MBJS_FreeValue(b->ctx, b->arr[--b->len]);
    if (b->arr != b->def)
        mbjs_free(b->ctx, b->arr);
    b->arr = b->def;
    b->size = 4;
}

static int value_buffer_append(ValueBuffer *b, MBJSValue val)
{
    if (b->error_status)
        return -1;

    if (b->len >= b->size) {
        int new_size = (b->len + (b->len >> 1) + 31) & ~16;
        MBJSValue *new_arr;

        if (b->arr == b->def) {
            new_arr = mbjs_realloc(b->ctx, NULL, sizeof(*b->arr) * new_size);
            if (new_arr)
                memcpy(new_arr, b->def, sizeof b->def);
        } else {
            new_arr = mbjs_realloc(b->ctx, b->arr, sizeof(*b->arr) * new_size);
        }
        if (!new_arr) {
            value_buffer_free(b);
            MBJS_FreeValue(b->ctx, val);
            b->error_status = -1;
            return -1;
        }
        b->arr = new_arr;
        b->size = new_size;
    }
    b->arr[b->len++] = val;
    return 0;
}

static int mbjs_is_standard_regexp(MBJSContext *ctx, MBJSValueConst rx)
{
    MBJSValue val;
    int res;

    val = MBJS_GetProperty(ctx, rx, MBJS_ATOM_constructor);
    if (MBJS_IsException(val))
        return -1;
    // rx.constructor === RegExp
    res = mbjs_same_value(ctx, val, ctx->regexp_ctor);
    MBJS_FreeValue(ctx, val);
    if (res) {
        val = MBJS_GetProperty(ctx, rx, MBJS_ATOM_exec);
        if (MBJS_IsException(val))
            return -1;
        // rx.exec === RE_exec
        res = MBJS_IsCFunction(ctx, val, mbjs_regexp_exec, 0);
        MBJS_FreeValue(ctx, val);
    }
    return res;
}

static MBJSValue mbjs_regexp_Symbol_replace(MBJSContext *ctx, MBJSValueConst this_val,
                                        int argc, MBJSValueConst *argv)
{
    // [Symbol.replace](str, rep)
    MBJSValueConst rx = this_val, rep = argv[1];
    MBJSValueConst args[6];
    MBJSValue flags, str, rep_val, matched, tab, rep_str, namedCaptures, res;
    MBJSString *p, *sp, *rp;
    StringBuffer b_s, *b = &b_s;
    ValueBuffer v_b, *results = &v_b;
    int nextSourcePosition, n, j, functionalReplace, is_global, fullUnicode;
    uint32_t nCaptures;
    int64_t position;

    if (!MBJS_IsObject(rx))
        return MBJS_ThrowTypeErrorNotAnObject(ctx);

    string_buffer_init(ctx, b, 0);
    value_buffer_init(ctx, results);

    rep_val = MBJS_UNDEFINED;
    matched = MBJS_UNDEFINED;
    tab = MBJS_UNDEFINED;
    flags = MBJS_UNDEFINED;
    rep_str = MBJS_UNDEFINED;
    namedCaptures = MBJS_UNDEFINED;

    str = MBJS_ToString(ctx, argv[0]);
    if (MBJS_IsException(str))
        goto exception;

    sp = MBJS_VALUE_GET_STRING(str);
    rp = NULL;
    functionalReplace = MBJS_IsFunction(ctx, rep);
    if (!functionalReplace) {
        rep_val = MBJS_ToString(ctx, rep);
        if (MBJS_IsException(rep_val))
            goto exception;
        rp = MBJS_VALUE_GET_STRING(rep_val);
    }

    flags = MBJS_GetProperty(ctx, rx, MBJS_ATOM_flags);
    if (MBJS_IsException(flags))
        goto exception;
    flags = MBJS_ToStringFree(ctx, flags);
    if (MBJS_IsException(flags))
        goto exception;
    p = MBJS_VALUE_GET_STRING(flags);

    fullUnicode = 0;
    is_global = (-1 != string_indexof_char(p, 'g', 0));
    if (is_global) {
        // 'v' flag implies full Unicode, like 'u'
        fullUnicode = (string_indexof_char(p, 'u', 0) >= 0 ||
                       string_indexof_char(p, 'v', 0) >= 0);
        if (MBJS_SetProperty(ctx, rx, MBJS_ATOM_lastIndex, mbjs_int32(0)) < 0)
            goto exception;
    }

    if (rp && rp->len == 0 && is_global && mbjs_is_standard_regexp(ctx, rx)) {
        /* use faster version for simple cases */
        res = MBJS_RegExpDelete(ctx, rx, str);
        goto done;
    }
    for(;;) {
        MBJSValue result;
        result = MBJS_RegExpExec(ctx, rx, str);
        if (MBJS_IsException(result))
            goto exception;
        if (MBJS_IsNull(result))
            break;
        if (value_buffer_append(results, result) < 0)
            goto exception;
        if (!is_global)
            break;
        MBJS_FreeValue(ctx, matched);
        matched = MBJS_ToStringFree(ctx, MBJS_GetPropertyInt64(ctx, result, 0));
        if (MBJS_IsException(matched))
            goto exception;
        if (MBJS_IsEmptyString(matched)) {
            /* always advance of at least one char */
            int64_t thisIndex, nextIndex;
            if (MBJS_ToLengthFree(ctx, &thisIndex, MBJS_GetProperty(ctx, rx, MBJS_ATOM_lastIndex)) < 0)
                goto exception;
            nextIndex = string_advance_index(sp, thisIndex, fullUnicode);
            if (MBJS_SetProperty(ctx, rx, MBJS_ATOM_lastIndex, mbjs_int64(nextIndex)) < 0)
                goto exception;
        }
    }
    nextSourcePosition = 0;
    for(j = 0; j < results->len; j++) {
        MBJSValue result;
        result = results->arr[j];
        if (mbjs_get_length32(ctx, &nCaptures, result) < 0)
            goto exception;
        MBJS_FreeValue(ctx, matched);
        matched = MBJS_ToStringFree(ctx, MBJS_GetPropertyInt64(ctx, result, 0));
        if (MBJS_IsException(matched))
            goto exception;
        if (MBJS_ToLengthFree(ctx, &position, MBJS_GetProperty(ctx, result, MBJS_ATOM_index)))
            goto exception;
        if (position > sp->len)
            position = sp->len;
        else if (position < 0)
            position = 0;
        /* ignore substition if going backward (can happen
           with custom regexp object) */
        MBJS_FreeValue(ctx, tab);
        tab = MBJS_NewArray(ctx);
        if (MBJS_IsException(tab))
            goto exception;
        if (MBJS_DefinePropertyValueInt64Const(ctx, tab, 0, matched,
                                             MBJS_PROP_C_W_E | MBJS_PROP_THROW) < 0)
            goto exception;
        for(n = 1; n < nCaptures; n++) {
            MBJSValue capN;
            capN = MBJS_GetPropertyInt64(ctx, result, n);
            if (MBJS_IsException(capN))
                goto exception;
            if (!MBJS_IsUndefined(capN)) {
                capN = MBJS_ToStringFree(ctx, capN);
                if (MBJS_IsException(capN))
                    goto exception;
            }
            if (MBJS_DefinePropertyValueInt64(ctx, tab, n, capN,
                                            MBJS_PROP_C_W_E | MBJS_PROP_THROW) < 0)
                goto exception;
        }
        MBJS_FreeValue(ctx, namedCaptures);
        namedCaptures = MBJS_GetProperty(ctx, result, MBJS_ATOM_groups);
        if (MBJS_IsException(namedCaptures))
            goto exception;
        if (functionalReplace) {
            if (MBJS_DefinePropertyValueInt64(ctx, tab, n++, mbjs_int32(position), MBJS_PROP_C_W_E | MBJS_PROP_THROW) < 0)
                goto exception;
            if (MBJS_DefinePropertyValueInt64Const(ctx, tab, n++, str, MBJS_PROP_C_W_E | MBJS_PROP_THROW) < 0)
                goto exception;
            if (!MBJS_IsUndefined(namedCaptures)) {
                if (MBJS_DefinePropertyValueInt64Const(ctx, tab, n++, namedCaptures, MBJS_PROP_C_W_E | MBJS_PROP_THROW) < 0)
                    goto exception;
            }
            args[0] = MBJS_UNDEFINED;
            args[1] = tab;
            MBJS_FreeValue(ctx, rep_str);
            rep_str = MBJS_ToStringFree(ctx, mbjs_function_apply(ctx, rep, 2, args, 0));
        } else {
            MBJSValue namedCaptures1;
            if (!MBJS_IsUndefined(namedCaptures)) {
                namedCaptures1 = MBJS_ToObject(ctx, namedCaptures);
                if (MBJS_IsException(namedCaptures1))
                    goto exception;
            } else {
                namedCaptures1 = MBJS_UNDEFINED;
            }
            args[0] = matched;
            args[1] = str;
            args[2] = mbjs_int32(position);
            args[3] = tab;
            args[4] = namedCaptures1;
            args[5] = rep_val;
            MBJS_FreeValue(ctx, rep_str);
            rep_str = mbjs_string___GetSubstitution(ctx, MBJS_UNDEFINED, 6, args);
            MBJS_FreeValue(ctx, namedCaptures1);
        }
        if (MBJS_IsException(rep_str))
            goto exception;
        if (position >= nextSourcePosition) {
            string_buffer_concat(b, sp, nextSourcePosition, position);
            string_buffer_concat_value(b, rep_str);
            nextSourcePosition = position + MBJS_VALUE_GET_STRING(matched)->len;
        }
    }
    string_buffer_concat(b, sp, nextSourcePosition, sp->len);
    res = string_buffer_end(b);
    goto done1;

exception:
    res = MBJS_EXCEPTION;
done:
    string_buffer_free(b);
done1:
    value_buffer_free(results);
    MBJS_FreeValue(ctx, rep_val);
    MBJS_FreeValue(ctx, matched);
    MBJS_FreeValue(ctx, flags);
    MBJS_FreeValue(ctx, tab);
    MBJS_FreeValue(ctx, rep_str);
    MBJS_FreeValue(ctx, namedCaptures);
    MBJS_FreeValue(ctx, str);
    return res;
}

static MBJSValue mbjs_regexp_Symbol_search(MBJSContext *ctx, MBJSValueConst this_val,
                                       int argc, MBJSValueConst *argv)
{
    MBJSValueConst rx = this_val;
    MBJSValue str, previousLastIndex, currentLastIndex, result, index;

    if (!MBJS_IsObject(rx))
        return MBJS_ThrowTypeErrorNotAnObject(ctx);

    result = MBJS_UNDEFINED;
    currentLastIndex = MBJS_UNDEFINED;
    previousLastIndex = MBJS_UNDEFINED;
    str = MBJS_ToString(ctx, argv[0]);
    if (MBJS_IsException(str))
        goto exception;

    previousLastIndex = MBJS_GetProperty(ctx, rx, MBJS_ATOM_lastIndex);
    if (MBJS_IsException(previousLastIndex))
        goto exception;

    if (!mbjs_same_value(ctx, previousLastIndex, mbjs_int32(0))) {
        if (MBJS_SetProperty(ctx, rx, MBJS_ATOM_lastIndex, mbjs_int32(0)) < 0) {
            goto exception;
        }
    }
    result = MBJS_RegExpExec(ctx, rx, str);
    if (MBJS_IsException(result))
        goto exception;
    currentLastIndex = MBJS_GetProperty(ctx, rx, MBJS_ATOM_lastIndex);
    if (MBJS_IsException(currentLastIndex))
        goto exception;
    if (mbjs_same_value(ctx, currentLastIndex, previousLastIndex)) {
        MBJS_FreeValue(ctx, previousLastIndex);
    } else {
        if (MBJS_SetProperty(ctx, rx, MBJS_ATOM_lastIndex, previousLastIndex) < 0) {
            previousLastIndex = MBJS_UNDEFINED;
            goto exception;
        }
    }
    MBJS_FreeValue(ctx, str);
    MBJS_FreeValue(ctx, currentLastIndex);

    if (MBJS_IsNull(result)) {
        return mbjs_int32(-1);
    } else {
        index = MBJS_GetProperty(ctx, result, MBJS_ATOM_index);
        MBJS_FreeValue(ctx, result);
        return index;
    }

exception:
    MBJS_FreeValue(ctx, result);
    MBJS_FreeValue(ctx, str);
    MBJS_FreeValue(ctx, currentLastIndex);
    MBJS_FreeValue(ctx, previousLastIndex);
    return MBJS_EXCEPTION;
}

static MBJSValue mbjs_regexp_Symbol_split(MBJSContext *ctx, MBJSValueConst this_val,
                                       int argc, MBJSValueConst *argv)
{
    // [Symbol.split](str, limit)
    MBJSValueConst rx = this_val;
    MBJSValueConst args[2];
    MBJSValue str, ctor, splitter, A, flags, z, sub;
    MBJSString *strp;
    uint32_t lim, size, p, q;
    int unicodeMatching;
    int64_t lengthA, e, numberOfCaptures, i;

    if (!MBJS_IsObject(rx))
        return MBJS_ThrowTypeErrorNotAnObject(ctx);

    ctor = MBJS_UNDEFINED;
    splitter = MBJS_UNDEFINED;
    A = MBJS_UNDEFINED;
    flags = MBJS_UNDEFINED;
    z = MBJS_UNDEFINED;
    str = MBJS_ToString(ctx, argv[0]);
    if (MBJS_IsException(str))
        goto exception;
    ctor = MBJS_SpeciesConstructor(ctx, rx, ctx->regexp_ctor);
    if (MBJS_IsException(ctor))
        goto exception;
    flags = MBJS_ToStringFree(ctx, MBJS_GetProperty(ctx, rx, MBJS_ATOM_flags));
    if (MBJS_IsException(flags))
        goto exception;
    strp = MBJS_VALUE_GET_STRING(flags);
    unicodeMatching = string_indexof_char(strp, 'u', 0) >= 0 ||
                      string_indexof_char(strp, 'v', 0) >= 0;
    if (string_indexof_char(strp, 'y', 0) < 0) {
        flags = MBJS_ConcatString3(ctx, "", flags, "y");
        if (MBJS_IsException(flags))
            goto exception;
    }
    args[0] = rx;
    args[1] = flags;
    splitter = MBJS_CallConstructor(ctx, ctor, 2, args);
    if (MBJS_IsException(splitter))
        goto exception;
    A = MBJS_NewArray(ctx);
    if (MBJS_IsException(A))
        goto exception;
    lengthA = 0;
    if (MBJS_IsUndefined(argv[1])) {
        lim = 0xffffffff;
    } else {
        if (MBJS_ToUint32(ctx, &lim, argv[1]) < 0)
            goto exception;
        if (lim == 0)
            goto done;
    }
    strp = MBJS_VALUE_GET_STRING(str);
    p = q = 0;
    size = strp->len;
    if (size == 0) {
        z = MBJS_RegExpExec(ctx, splitter, str);
        if (MBJS_IsException(z))
            goto exception;
        if (MBJS_IsNull(z))
            goto add_tail;
        goto done;
    }
    while (q < size) {
        if (MBJS_SetProperty(ctx, splitter, MBJS_ATOM_lastIndex, mbjs_int32(q)) < 0)
            goto exception;
        MBJS_FreeValue(ctx, z);
        z = MBJS_RegExpExec(ctx, splitter, str);
        if (MBJS_IsException(z))
            goto exception;
        if (MBJS_IsNull(z)) {
            q = string_advance_index(strp, q, unicodeMatching);
        } else {
            if (MBJS_ToLengthFree(ctx, &e, MBJS_GetProperty(ctx, splitter, MBJS_ATOM_lastIndex)))
                goto exception;
            if (e > size)
                e = size;
            if (e == p) {
                q = string_advance_index(strp, q, unicodeMatching);
            } else {
                sub = mbjs_sub_string(ctx, strp, p, q);
                if (MBJS_IsException(sub))
                    goto exception;
                if (MBJS_DefinePropertyValueInt64(ctx, A, lengthA++, sub,
                                                MBJS_PROP_C_W_E | MBJS_PROP_THROW) < 0)
                    goto exception;
                if (lengthA == lim)
                    goto done;
                p = e;
                if (mbjs_get_length64(ctx, &numberOfCaptures, z))
                    goto exception;
                for(i = 1; i < numberOfCaptures; i++) {
                    sub = MBJS_GetPropertyInt64(ctx, z, i);
                    if (MBJS_IsException(sub))
                        goto exception;
                    if (!MBJS_IsUndefined(sub)) {
                        sub = MBJS_ToStringFree(ctx, sub);
                        if (MBJS_IsException(sub))
                            goto exception;
                    }
                    if (MBJS_DefinePropertyValueInt64(ctx, A, lengthA++, sub, MBJS_PROP_C_W_E | MBJS_PROP_THROW) < 0)
                        goto exception;
                    if (lengthA == lim)
                        goto done;
                }
                q = p;
            }
        }
    }
add_tail:
    if (p > size)
        p = size;
    sub = mbjs_sub_string(ctx, strp, p, size);
    if (MBJS_IsException(sub))
        goto exception;
    if (MBJS_DefinePropertyValueInt64(ctx, A, lengthA++, sub, MBJS_PROP_C_W_E | MBJS_PROP_THROW) < 0)
        goto exception;
    goto done;
exception:
    MBJS_FreeValue(ctx, A);
    A = MBJS_EXCEPTION;
done:
    MBJS_FreeValue(ctx, str);
    MBJS_FreeValue(ctx, ctor);
    MBJS_FreeValue(ctx, splitter);
    MBJS_FreeValue(ctx, flags);
    MBJS_FreeValue(ctx, z);
    return A;
}

