static MBJSValue mbjs_async_from_sync_iterator_unwrap(MBJSContext *ctx,
                                                  MBJSValueConst this_val,
                                                  int argc, MBJSValueConst *argv,
                                                  int magic, MBJSValueConst *func_data)
{
    return mbjs_create_iterator_result(ctx, mbjs_dup(argv[0]),
                                     MBJS_ToBool(ctx, func_data[0]));
}

static MBJSValue mbjs_async_from_sync_iterator_unwrap_func_create(MBJSContext *ctx,
                                                              bool done)
{
    MBJSValueConst func_data[1];

    func_data[0] = mbjs_bool(done);
    return MBJS_NewCFunctionData(ctx, mbjs_async_from_sync_iterator_unwrap,
                               1, 0, 1, func_data);
}

/* AsyncIteratorPrototype */

static const MBJSCFunctionListEntry mbjs_async_iterator_proto_funcs[] = {
    MBJS_CFUNC_DEF("[Symbol.asyncIterator]", 0, mbjs_iterator_proto_iterator ),
    MBJS_CFUNC_DEF("[Symbol.asyncDispose]", 0, mbjs_async_iterator_proto_dispose ),
};

/* AsyncFromSyncIteratorPrototype */

typedef struct MBJSAsyncFromSyncIteratorData {
    MBJSValue sync_iter;
    MBJSValue next_method;
} MBJSAsyncFromSyncIteratorData;

static void mbjs_async_from_sync_iterator_finalizer(MBJSRuntime *rt,
                                                  MBJSValueConst val)
{
    MBJSAsyncFromSyncIteratorData *s =
        MBJS_GetOpaque(val, MBJS_CLASS_ASYNC_FROM_SYNC_ITERATOR);
    if (s) {
        MBJS_FreeValueRT(rt, s->sync_iter);
        MBJS_FreeValueRT(rt, s->next_method);
        mbjs_free_rt(rt, s);
    }
}

static void mbjs_async_from_sync_iterator_mark(MBJSRuntime *rt, MBJSValueConst val,
                                             MBJS_MarkFunc *mark_func)
{
    MBJSAsyncFromSyncIteratorData *s =
        MBJS_GetOpaque(val, MBJS_CLASS_ASYNC_FROM_SYNC_ITERATOR);
    if (s) {
        MBJS_MarkValue(rt, s->sync_iter, mark_func);
        MBJS_MarkValue(rt, s->next_method, mark_func);
    }
}

static MBJSValue MBJS_CreateAsyncFromSyncIterator(MBJSContext *ctx,
                                              MBJSValue sync_iter)
{
    MBJSValue async_iter, next_method;
    MBJSAsyncFromSyncIteratorData *s;

    next_method = MBJS_GetProperty(ctx, sync_iter, MBJS_ATOM_next);
    if (MBJS_IsException(next_method))
        return MBJS_EXCEPTION;
    async_iter = MBJS_NewObjectClass(ctx, MBJS_CLASS_ASYNC_FROM_SYNC_ITERATOR);
    if (MBJS_IsException(async_iter)) {
        MBJS_FreeValue(ctx, next_method);
        return async_iter;
    }
    s = mbjs_mallocz(ctx, sizeof(*s));
    if (!s) {
        MBJS_FreeValue(ctx, async_iter);
        MBJS_FreeValue(ctx, next_method);
        return MBJS_EXCEPTION;
    }
    s->sync_iter = mbjs_dup(sync_iter);
    s->next_method = next_method;
    MBJS_SetOpaqueInternal(async_iter, s);
    return async_iter;
}

static MBJSValue mbjs_async_from_sync_iterator_next(MBJSContext *ctx, MBJSValueConst this_val,
                                                int argc, MBJSValueConst *argv,
                                                int magic)
{
    MBJSValue promise, resolving_funcs[2], value, err, method;
    MBJSAsyncFromSyncIteratorData *s;
    int done;
    int is_reject;

    promise = MBJS_NewPromiseCapability(ctx, resolving_funcs);
    if (MBJS_IsException(promise))
        return MBJS_EXCEPTION;
    s = MBJS_GetOpaque(this_val, MBJS_CLASS_ASYNC_FROM_SYNC_ITERATOR);
    if (!s) {
        MBJS_ThrowTypeError(ctx, "not an Async-from-Sync Iterator");
        goto reject;
    }

    if (magic == GEN_MAGIC_NEXT) {
        method = mbjs_dup(s->next_method);
    } else {
        method = MBJS_GetProperty(ctx, s->sync_iter,
                                magic == GEN_MAGIC_RETURN ? MBJS_ATOM_return :
                                MBJS_ATOM_throw);
        if (MBJS_IsException(method))
            goto reject;
        if (MBJS_IsUndefined(method) || MBJS_IsNull(method)) {
            if (magic == GEN_MAGIC_RETURN) {
                err = mbjs_create_iterator_result(ctx, mbjs_dup(argv[0]), true);
                is_reject = 0;
            } else if (MBJS_IteratorClose(ctx, s->sync_iter, false)) {
                err = MBJS_GetException(ctx);
                is_reject = 1;
            } else {
                err = MBJS_MakeError2(ctx, MBJS_TYPE_ERROR, /*add_backtrace*/true,
                                    "throw is not a method");
                is_reject = 1;
            }
            goto done_resolve;
        }
    }
    value = MBJS_IteratorNext2(ctx, s->sync_iter, method,
                             argc >= 1 ? 1 : 0, argv, &done);
    MBJS_FreeValue(ctx, method);
    if (MBJS_IsException(value))
        goto reject;
    if (done == 2) {
        MBJSValue obj = value;
        value = MBJS_IteratorGetCompleteValue(ctx, obj, &done);
        MBJS_FreeValue(ctx, obj);
        if (MBJS_IsException(value))
            goto reject;
    }

    if (MBJS_IsException(value)) {
        MBJSValue res2;
    reject:
        err = MBJS_GetException(ctx);
        is_reject = 1;
    done_resolve:
        res2 = MBJS_Call(ctx, resolving_funcs[is_reject], MBJS_UNDEFINED,
                       1, vc(&err));
        MBJS_FreeValue(ctx, err);
        MBJS_FreeValue(ctx, res2);
        MBJS_FreeValue(ctx, resolving_funcs[0]);
        MBJS_FreeValue(ctx, resolving_funcs[1]);
        return promise;
    }
    {
        MBJSValue value_wrapper_promise, resolve_reject[2];
        int res;

        value_wrapper_promise = mbjs_promise_resolve(ctx, ctx->promise_ctor,
                                                   1, vc(&value), 0);
        if (MBJS_IsException(value_wrapper_promise)) {
            MBJS_FreeValue(ctx, value);
            goto reject;
        }

        resolve_reject[0] =
            mbjs_async_from_sync_iterator_unwrap_func_create(ctx, done);
        if (MBJS_IsException(resolve_reject[0])) {
            MBJS_FreeValue(ctx, value_wrapper_promise);
            goto fail;
        }
        MBJS_FreeValue(ctx, value);
        resolve_reject[1] = MBJS_UNDEFINED;

        res = perform_promise_then(ctx, value_wrapper_promise,
                                   vc(resolve_reject),
                                   vc(resolving_funcs));
        MBJS_FreeValue(ctx, resolve_reject[0]);
        MBJS_FreeValue(ctx, value_wrapper_promise);
        MBJS_FreeValue(ctx, resolving_funcs[0]);
        MBJS_FreeValue(ctx, resolving_funcs[1]);
        if (res) {
            MBJS_FreeValue(ctx, promise);
            return MBJS_EXCEPTION;
        }
    }
    return promise;
 fail:
    MBJS_FreeValue(ctx, value);
    MBJS_FreeValue(ctx, resolving_funcs[0]);
    MBJS_FreeValue(ctx, resolving_funcs[1]);
    MBJS_FreeValue(ctx, promise);
    return MBJS_EXCEPTION;
}

static const MBJSCFunctionListEntry mbjs_async_from_sync_iterator_proto_funcs[] = {
    MBJS_CFUNC_MAGIC_DEF("next", 1, mbjs_async_from_sync_iterator_next, GEN_MAGIC_NEXT ),
    MBJS_CFUNC_MAGIC_DEF("return", 1, mbjs_async_from_sync_iterator_next, GEN_MAGIC_RETURN ),
    MBJS_CFUNC_MAGIC_DEF("throw", 1, mbjs_async_from_sync_iterator_next, GEN_MAGIC_THROW ),
};

